var ENDS8={
 true:{n:"Ánh đèn không cần khán giả",c:"Tiểu Châu đọc kết quả: đạt, trọn vẹn. Ác niệm của Tạ Chiêu Minh đã về không. Chiếc xe tải chỉ còn là tin trong báo cũ, Quản Kiêu và Thừa Vĩ phải đứng trước pháp luật. Hôm cưới, anh nắm tay cô bước qua sảnh dưới nắng, không còn nhìn quanh tìm lối thoát. Nhiều năm sau, hai người vẫn sống trong căn nhà ven sông; cô vẫn nấu cháo mỗi khi anh quên ăn, còn anh vẫn đọc kịch bản trên ghế cạnh bếp.",gain:120,piece:1,heat:.1,scene:"ywed"},
 near:{n:"Một vệt đèn đỏ cuối cánh gà",c:"Tiểu Châu đọc kết quả: đạt, nhưng chưa trọn. Hai người cưới trong một buổi sáng yên ổn. Anh không còn muốn trả thù ai, nhưng thỉnh thoảng đêm khuya vẫn tỉnh dậy vì những giấc mơ cũ, và cô vẫn ngồi bên cạnh cho đến sáng. Vết đỏ trong mắt anh nhạt dần theo từng mùa; cô biết rồi nó sẽ tan.",gain:90,piece:1,heat:.35,scene:"ysea"},
 half:{n:"Hai người, một cánh gà",c:"Tiểu Châu đọc kết quả: chưa đạt. Họ vẫn cưới và vẫn cùng nhau làm phim, nhưng mối hận với nhà họ Tạ chưa được gỡ hết. Anh vẫn lạnh với Uyển Như, vẫn giữ khoảng cách với cha, và cô vẫn đứng cạnh anh những lúc anh im lặng. Hai người đi cùng nhau, dù con đường còn dài.",gain:60,piece:0,heat:.6,scene:"ywed"},
 black:{n:"Đèn tắt giữa buổi lễ",c:"Hắc hóa chạm 100. Anh không còn nghe thấy tên mình, không còn nghe thấy lời cô. Sảnh lễ vắng lặng, đèn sân khấu tắt từng ngọn. Tiểu Châu kéo cô đi trước khi cánh cửa sảnh khép lại sau lưng.",gain:0,piece:0,heat:1,scene:"ystage"},
 bdead:{n:"Chiếc nhẫn trong lòng bàn tay",c:"Sinh mệnh của Tạ Chiêu Minh về 0. Trên nền sảnh cưới lạnh, chiếc nhẫn nằm trong lòng bàn tay cô, vẫn còn ấm. Cô giữ nó rất lâu, cho đến khi Tiểu Châu khẽ gọi cô về.",gain:0,piece:0,heat:.9,scene:"ywed"},
 dead:{n:"Chiếc xe ven sông",c:"Sinh mệnh cạn kiệt. Giữa tiếng còi và ánh đèn pha trên con đường ven sông, cô nhìn lại sảnh cưới ở cuối đường lần cuối. Tiểu Châu kéo linh hồn cô đi, khi ở đâu đó Chiêu Minh vẫn đang chờ trong bộ vest cưới, tay nắm chặt một chiếc nhẫn.",gain:0,piece:0,heat:.8,scene:"yroad"}
};

function w8emblem(heat){
  /* Ống kính máy quay, vòng khẩu độ ngả đỏ dần theo Hắc hóa */
  var c='color-mix(in oklab,var(--ember) '+Math.round(heat*100)+'%,#dfe4ea)';
  var s='<svg class="eye" viewBox="0 0 96 96" role="img" aria-label="Ống kính máy quay, ngả đỏ dần theo Hắc hóa"><circle cx="48" cy="48" r="45" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="48" cy="48" r="45" fill="none" stroke="var(--ember)" stroke-width="2" stroke-dasharray="'+(heat*283)+' 283" transform="rotate(-90 48 48)"/>'
   +'<circle cx="48" cy="48" r="28" fill="none" stroke="var(--fg)" stroke-width="2.5" opacity=".85"/><circle cx="48" cy="48" r="14" fill="'+c+'" stroke="var(--fg)" stroke-width="2"/>';
  for(var i=0;i<6;i++){var a=i*Math.PI/3;s+='<path d="M'+(48+14*Math.cos(a)).toFixed(1)+' '+(48+14*Math.sin(a)).toFixed(1)+' L'+(48+28*Math.cos(a+.6)).toFixed(1)+' '+(48+28*Math.sin(a+.6)).toFixed(1)+'" stroke="var(--fg)" stroke-width="1.6" opacity=".6"/>'}
  return s+'<circle cx="60" cy="36" r="3" fill="#fff" opacity=".85"/></svg>';
}

