   yoffice:function(){return room(68)+city().replace(/class="m1"/g,'class="m2"')+'<rect y="0" width="800" height="340" fill="var(--bg)" opacity=".5"/>'+desk(400,270,300)+mal(300,270,1)+fem(500,270,.95)+lamp(400,70)},
