 EV:EV10,ENDS:ENDS10,CHAP_END:[9,19,29,37,44],PROG:[{ac:-1,hac:-1,hao:2},{ac:-1,hac:-2,hao:2},{ac:-2,hac:-2,hao:2},{ac:-2,hac:-2,hao:2},{ac:-2,hac:-2,hao:2}],PBIAS:0.072,P0:{mi:56,tri:64,van:52},
