/* ================= THẾ GIỚI 11 · Nhất Trung Thanh Giang · Hiện đại học đường ================= */
var E11=E4;
function sk11(n,v){return function(){return hasSk(n)?v:0}}
function w11spike(base,soft,flag){return function(d){var o=Object.assign({},d);o.set={hac:Math.min(95,S.hac+(S.f[flag]?soft:base))};return o}}
Object.assign(CN,{unh:"Trình Nhược Hi",udt:"Hoắc Dịch Trì",umg:"Chu Mộng Giai",udh:"Tần Dĩ Hằng",udp:"Quan Đình Phong",uqq:"Quan phu nhân",uta:"Quan Tú Anh",uch:"Hoắc Chấn Hải",utt:"Phương Tiểu Tuyết",udl:"Đại Lực",uco:"Dư Chấn Hoa",ucd:"Thầy Cao Văn Đạt",uba:"Trình Kiến Quốc",ume:"Văn Ngọc Chi",uth:"Thanh Hạc đạo nhân",uel:"Elara",uso:"Soren"});
var EV11=[
/* ---- Chương 1: Mặt có sẹo, trở lại trường (mốc 1–8) ---- */
E11("h01","zhosp","Bệnh viện thành phố Thanh Giang · Sáng","duyen","Tỉnh dậy trong bệnh viện",
"Nhược Hi mở mắt giữa mùi thuốc sát trùng. Nửa mặt phải quấn băng, đau rát âm ỉ; theo hồ sơ thì cô đã nằm viện nửa tháng. Một quả cầu ngọc xanh nhỏ lơ lửng cạnh gối: «Ta là Tiểu Châu». Nó nói gọn: nguyên chủ 17 tuổi, học giỏi nhất khối, bị nhầm với người khác nên chịu một vết thương nặng trước khi cô đến. Nhà Trình đấu không lại nhà Quan, quỹ đạo gốc là cô sống cô độc cả đời dù không làm gì sai. Người cần cảm hóa là bạn cùng bàn Hoắc Dịch Trì, giáo bá cuối bảng, từng là thần đồng, mẹ mất sớm, bị cha Hoắc Chấn Hải và dì ghẻ Quan Tú Anh bỏ mặc.",
"Dậy rồi à? Chuyện cũ ta nói gọn thôi, đừng bắt ta tả. Việc của ngươi là sống cho ra sống, và kéo cái cậu bạn cùng bàn lạnh lùng kia ra khỏi bóng tối.",
"unh,udt,tc",[
 CH("Hỏi Tiểu Châu thật kỹ quỹ đạo gốc và về Hoắc Dịch Trì","tri",0.560,["Cô nghe hết, ghi nhớ từng mốc và nhận ra Dịch Trì mới là người cô đơn nhất trong câu chuyện này. Đầu óc cô tỉnh táo hẳn.",{sinh:2},"biet_quydao"],["Cô nghe được nửa chừng thì cơn đau trở lại, đầu quay cuồng. Cô chỉ nhớ mang máng.",{sinh:-2}]),
 CH("Gọi y tá, hỏi rõ tình trạng của mình trước","van",0.500,["Y tá nói vết thương đang hồi phục tốt, tuần sau có thể xuất viện. Cô thở ra, thấy mình có thêm một chỗ dựa.",{sinh:3}],["Y tá bận, chỉ dặn nghỉ ngơi. Cô nằm đó thêm nửa tiếng với đầu óc rối bời.",{sinh:-2}]),
 CH("Nằm im sắp xếp lại ý nghĩ, hỏi sau","",0,["Cô nhìn trần nhà một lúc lâu rồi quyết định: mình sẽ không sống như quỹ đạo gốc đã vẽ. Lòng cô dịu lại, đủ để tính tiếp.",{sinh:1}])],
{ctx:"Sáng, bệnh viện thành phố Thanh Giang. Nhược Hi, 17 tuổi, tỉnh dậy sau nửa tháng nằm viện và nhận nhiệm vụ cảm hóa Hoắc Dịch Trì."}),

E11("h02","zhosp","Phòng bệnh · Tối cùng ngày","chon","Ba mẹ muốn đòi công bằng",
"Tối, Trình Kiến Quốc và Văn Ngọc Chi tới sau giờ làm, mắt đỏ hoe. Hai người đã liên hệ bệnh viện nước ngoài và muốn kiện ngay, dù chưa có chứng cứ nào trong tay. Nhược Hi biết nhà Quan lớn hơn nhà Trình nhiều; kiện lúc này chỉ khiến công ty nhà cô mất thêm.",
"Ba mẹ ngươi thương con nên nóng. Khuyên cho khéo, đừng để họ nghĩ ngươi sợ.",
"unh,uba,ume,tc",[
 CH("Nắm tay ba mẹ, nói con cần ba mẹ khỏe để cùng con chờ đúng lúc","mi",0.500,["Mẹ bật khóc, ba siết tay cô thật chặt. Hai người gật đầu, bảo sẽ cùng nhau xây lại công ty trước.",{ac:0,sinh:3},"ba_me_tin"],["Mẹ vẫn nghẹn ngào, ba đứng im không đáp. Cô phải nhắc lại lần nữa mới yên.",{sinh:-2}]),
 CH("Phân tích từng lợi hại: vì sao kiện lúc này chỉ có thiệt","tri",0.530,["Cô nói chậm, rõ từng ý. Ba nhìn cô lâu rồi hỏi: «Con lớn từ bao giờ thế?» Hai người đồng ý ẩn nhẫn.",{sinh:2},"ba_me_tin"],["Cô nói dài quá, ba mẹ nghe không kịp. Họ gật đầu cho xong nhưng lòng còn nặng.",{sinh:-2}]),
 CH("Ôm ba mẹ, rồi hứa sẽ kể hết khi đủ chứng cứ","van",0.470,["Ba mẹ im lặng ôm cô rất lâu. Không ai nhắc đến chuyện kiện nữa tối đó.",{sinh:2},"ba_me_tin"],["Mẹ vẫn thút thít, ba quay mặt đi. Cô ôm hai người mà lòng thấy trống.",{sinh:-2}])],
{ctx:"Tối cùng ngày, phòng bệnh. Ba mẹ Trình muốn kiện ngay dù chưa có chứng cứ; Nhược Hi phải khuyên ẩn nhẫn."}),

E11("h03","apart","Giường bệnh · Đêm đó","duyen","Khôi phục đoạn camera",
"Tiểu Châu vừa được nâng cấp, báo rằng camera đầu phố hôm xảy ra chuyện đã bị cắt xóa. Nó có thể khôi phục, nhưng cô phải học cách kiểm tra từng bản và lưu thêm vài bản để không ai sửa được. Trong đoạn phim hiện ra, Chu Mộng Giai chạy ngang đụng ngã cô, và Quan Đình Phong đuổi theo ngay sau. Cô nhìn đến khi hiểu hết, rồi tắt màn hình.",
"Chứng cứ sạch là thứ đáng giá nhất trong chuyện này. Làm chậm mà chắc, đừng để một bản duy nhất.",
"unh,umg,udp,tc",[
 CH("Cùng Tiểu Châu khôi phục từng đoạn, kiểm tra tính nguyên vẹn từng bản","tri",0.520,["Từng đoạn hiện ra đúng thời gian, đúng nhịp. Cô lưu ra ba bản, mã hóa cẩn thận. Cô nhận ra mình đã học được một kỹ năng thật sự.",{sinh:2},"giu_cam"],["Một đoạn bị lỗi, cô phải làm lại hai lần mới sạch. Cô thấy mệt nhưng không bỏ.",{sinh:-3},"giu_cam"]),
 CH("Lưu thêm bản sao ở nhiều nơi khác nhau, rồi mới xem","van",0.480,["Các bản sao nằm yên ở ba nơi khác nhau. Cô nhẹ cả người khi biết không ai xóa nổi cả ba.",{sinh:1},"giu_cam"],["Một nơi lưu bị đầy, cô phải dọn lại từ đầu. Tốn cả đêm.",{sinh:-3}]),
 CH("Xem hết đoạn phim thật kỹ, ghi lại mốc thời gian từng cảnh","mi",0.440,["Cô ghi lại từng giây, đủ để sau này trình bày trước bất kỳ ai. Đêm đó cô ngủ vững hơn.",{sinh:2},"giu_cam"],["Cô xem đến gần sáng, đầu óc căng ra, ghi chép lộn xộn. Phải chép lại vào hôm sau.",{sinh:-4}])],
{ctx:"Đêm đó, giường bệnh. Tiểu Châu khôi phục camera phố bị xóa; cô thấy Mộng Giai đụng ngã mình và Đình Phong đuổi theo.",learn:{n:"Khôi phục dữ liệu",s:"tri",v:1}}),

E11("h04","zstudy","Nhóm giao lưu vị diện · Cùng đêm","duyen","Nhóm giao lưu vị diện",
"Tiểu Châu phát hiện Mộng Giai đang ở trong một nhóm trò chuyện liên thế giới, nơi cô ta đổi đồ ăn lấy đồ quý để giữ dung mạo. Nhược Hi dùng nick «Hoa Khôi» xin vào và bất ngờ được trao quyền chủ nhóm. Ba đàn hữu lần lượt giới thiệu: Thanh Hạc đạo nhân, nữ phù thủy Elara và Soren, thợ chỉnh nhan từ một thế giới tinh tế. Mộng Giai chưa biết nhóm đã có chủ mới.",
"Chủ nhóm là ngươi rồi đấy. Nói ít, làm khéo, và nhớ cái nhóm này chỉ là màn hình thôi, đừng để nó nuốt thời gian học của ngươi.",
"unh,uth,uel,uso,tc",[
 CH("Giới thiệu thân thiện, phát vài món ăn làm quà ra mắt","mi",0.500,["Ba đàn hữu khen rối rít, gọi cô là «chủ nhóm đáng yêu». Họ tin cô từ những tin nhắn đầu tiên.",{ac:0,sinh:2},"chu_nhom"],["Món ăn gửi trễ nhịp, ba người chỉ phản hồi qua loa. Cô phải bù thêm sau.",{sinh:-1}]),
 CH("Đọc kỹ quy tắc nhóm trước khi nói câu nào","tri",0.540,["Cô phát hiện một điều khoản về đổi vật phẩm mà ai cũng bỏ qua. Cô ghi nhớ để dùng sau.",{sinh:2},"chu_nhom"],["Quy tắc dài và rối, cô đọc gần xong thì có người nhắn dồn dập. Cô vẫn phải trả lời vội.",{sinh:-2}]),
 CH("Chỉ chào ngắn, quan sát xem ba người trò chuyện thế nào","van",0.470,["Ba người nói chuyện rất tự nhiên, để lộ ai thật thà, ai hay tính toán. Cô đọc ra tính cách từng người.",{sinh:1},"chu_nhom"],["Cô lơ đãng bỏ lỡ nửa buổi trò chuyện, chỉ nắm được vài tên.",{sinh:-1}])],
{ctx:"Cùng đêm. Nhược Hi vào nhóm giao lưu vị diện bằng nick «Hoa Khôi» và thành chủ nhóm; Mộng Giai chưa biết."}),

E11("h05","zstudy","Nhóm giao lưu vị diện · Vài hôm sau","chon","Quả trứng nướng",
"Cô phát trứng nướng cho cả nhóm làm quà. Ba đàn hữu ăn ngay và khen, riêng Mộng Giai giật được một quả, thấy vỏ sáng bóng thì tin là trứng thần thú, giấu đi và không hỏi ai. Nhược Hi biết trứng chỉ giữ được vài ngày. Cô có thể nhắc Mộng Giai, hoặc để cô ta tự quyết.",
"Trứng thường thôi, nhưng cô ta thì tin là thần thú. Nhắc hay không là ở ngươi, nhưng đã nhắc thì nhắc cho rõ.",
"unh,umg,uel,tc",[
 CH("Nhắn Mộng Giai: «Ăn sớm, đừng để lâu»","mi",0.470,["Mộng Giai chỉ trả lời một chữ «ừ», nhưng cô đã làm tròn phần mình. Đàn hữu thấy cô cẩn thận.",{ac:-1,hao:1},"nhac_trung"],["Mộng Giai bảo cô ghen vì không được trứng. Nhóm hơi ngượng nhưng cô chẳng cãi.",{hao:0}]),
 CH("Chỉ ghi lại chuyện đã xảy ra, không nói thêm","tri",0.500,["Cô ghi chép gọn, đủ để sau này chứng minh mình đã không lừa ai.",{hao:1},"ghi_trung"],["Cô quên đánh dấu ngày giờ. Ghi chép thiếu một chỗ.",{hao:0}]),
 CH("Nhắn riêng cho Elara nhờ để mắt tới Mộng Giai","van",0.450,["Elara đồng ý ngay. Cô được thêm một người hiểu chuyện trong nhóm.",{hao:1,sinh:1},"nhac_trung"],["Elara đang bận đi xa, tin nhắn nằm im cả ngày.",{hao:0}])],
{ctx:"Vài hôm sau, trong nhóm. Mộng Giai giật được một quả trứng nướng và tin đó là trứng thần thú."}),

E11("h06","school","Cổng trường Nhất Trung Thanh Giang · Thứ ba","duyen","Trở lại trường",
"Thứ ba, Nhược Hi bước qua cổng Nhất Trung Thanh Giang với băng gạc vừa tháo, nửa má phải còn sẹo. Cô kể thẳng với lớp 11A3 chuyện mình bị nhầm người, không giấu, không khóc. Bạn học sửng sốt rồi nể. Ở góc lớp, Hoắc Dịch Trì ngủ gục trên bàn, giáo thảo Tần Dĩ Hằng ngồi cạnh bạn gái Chu Mộng Giai. Khi cô ngồi xuống chỗ cạnh Dịch Trì, hắn ngẩng lên nhìn cô lâu hơn mọi người.",
"Ngươi làm rất tốt. Mặt còn sẹo thì kệ, ngẩng đầu là đủ. Hắn nhìn ngươi rồi đó, ghi lại.",
"unh,udt,umg,udh,tc",[
 CH("Kể thẳng chuyện bị nhầm người, giọng bình tĩnh","mi",0.500,["Cả lớp lặng đi rồi vài người vỗ tay nhẹ. Cô đứng thẳng, cảm thấy nhẹ nhõm lạ.",{ac:-2,hao:2,sinh:1},"ve_truong"],["Giọng cô run ở câu cuối. Vài người quay đi, nhưng không ai cười.",{hao:0,sinh:-2}]),
 CH("Chào thầy cô, ngồi xuống im lặng làm bài","tri",0.520,["Sự yên lặng của cô khiến cả lớp dần quen. Dịch Trì nhìn cô thêm một lần nữa.",{ac:-1,hao:1,sinh:1},"ve_truong"],["Cô để rơi cuốn sách, vài tiếng thì thầm. Cô lặng lẽ nhặt lên.",{hao:0,sinh:-1}]),
 CH("Ngồi xuống cạnh Dịch Trì như chẳng có chuyện gì","van",0.470,["Hắn khẽ nghiêng người nhường chỗ, không nói gì. Cô để ý ngón tay hắn gõ nhẹ lên mặt bàn.",{ac:-2,hao:2},"ve_truong"],["Ghế kêu to, cả lớp quay lại nhìn. Cô đỏ mặt, ngồi xuống thật nhanh.",{hao:0,sinh:-2}])],
{ctx:"Thứ ba, cổng và lớp 11A3 Nhất Trung Thanh Giang. Nhược Hi trở lại trường với nửa má phải còn sẹo và ngồi cạnh Dịch Trì."}),

E11("h07","school","Lớp 11A3 · Giờ ra chơi","chon","Lời cay độc của Tiểu Tuyết",
"Giờ ra chơi, Nhược Hi đùa với Dịch Trì rằng một người có sẹo, một người cuối bảng thì cũng xứng đôi. Phương Tiểu Tuyết, nữ sinh lớp bên vốn thích Dịch Trì, bước vào chê cô xấu và bảo cô đừng bám hắn. Dịch Trì đứng dậy bỏ ra ngoài, không nói một câu chê cô.",
"Cô bé đó cay thật đấy, nhưng không đáng để ngươi giận. Hắn bỏ đi mà không chê ngươi, nhớ cái đó.",
"unh,udt,utt,tc",[
 CH("Đáp Tiểu Tuyết một câu nhẹ nhàng nhưng rõ ràng: «Bạn nói gì, mình nghe rồi»","mi",0.490,["Tiểu Tuyết sững người, không ngờ cô không giận. Cả lớp lặng đi, cô quay lại chỗ ngồi thở đều.",{ac:-2,hac:-1,hao:2},"dap_tuyet"],["Cô nói lỡ giọng, nghe như đang đáp trả. Tiểu Tuyết cười khẩy.",{hao:-1,hac:1}]),
 CH("Mặc kệ, mở sách ra làm bài như không có gì","tri",0.530,["Cô làm bài thật nhanh. Tiểu Tuyết đứng thêm một lúc rồi bỏ đi trong khó chịu.",{ac:-1,hao:1,sinh:1}],["Tay cô run làm đứt nét bút. Tiểu Tuyết thấy vậy và cười thêm một câu.",{hao:0,sinh:-2}]),
 CH("Quay sang nhờ Dịch Trì lên tiếng một câu","van",0.400,["Hắn dừng ở cửa lớp, quay đầu lại, nói gọn: «Đừng nói nữa.» Tiểu Tuyết im bặt.",{ac:-3,hac:-1,hao:4},"dt_len_tieng"],["Hắn không quay lại. Cô nhận ra mình đã nhờ sớm quá.",{hao:-2,hac:1}])],
{ctx:"Giờ ra chơi, lớp 11A3. Phương Tiểu Tuyết chê cô xấu và bảo đừng bám Dịch Trì; hắn bỏ ra ngoài mà không đáp."}),

E11("h08","school","Hành lang · Cùng ngày","duyen","Hắn không đáp",
"Ngoài hành lang, Nhược Hi hỏi Dịch Trì vì sao hắn không từ chối một câu. Hắn không nói gì, chỉ nhìn ra sân. Tiểu Châu giải thích: cô muốn nghe hắn từ chối để dứt tình cảm của nguyên chủ, nhưng hắn không cho cô cơ hội đó. Cô quyết ở gần hắn để hiểu vì sao.",
"Đây là mốc đầu của hắn đấy. Hắn không từ chối nghĩa là hắn chưa muốn dứt. Bước tiếp thế nào là ở ngươi.",
"unh,udt,tc",[
 CH("Hỏi thẳng hắn: «Cậu thật sự muốn tớ tránh xa à?»","tri",0.490,["Hắn im rất lâu, rồi lắc đầu nhẹ. Cô biết đó là câu trả lời thật nhất hắn có thể cho lúc này.",{ac:-3,hac:-1,hao:3},"hoi_thang"],["Hắn quay đi, cô không nghe được gì. Hành lang chỉ còn tiếng chuông vào lớp.",{hao:0,hac:1}]),
 CH("Đưa hắn một cái bánh, nói sẽ chờ hắn khi nào hắn muốn nói","mi",0.470,["Hắn cầm cái bánh, nhìn nó rất lâu, rồi cất vào cặp. Cô biết hắn đã nghe.",{ac:-3,hao:4,sinh:1},"cho_banh"],["Hắn để cái bánh lên bàn, không cầm lên. Cô đành nhặt lại.",{hao:0}]),
 CH("Đi cạnh hắn lặng lẽ tới cổng, không hỏi thêm","van",0.500,["Hai người đi cạnh nhau suốt đoạn đường mà không ai nói. Đến cổng hắn khẽ gật đầu với cô.",{ac:-2,hao:3},"di_canh"],["Hắn đi nhanh hơn, cô tụt lại phía sau. Cô nhìn bóng hắn xa dần.",{hao:0}])],
{ctx:"Cùng ngày, hành lang. Nhược Hi hỏi Dịch Trì vì sao không từ chối Tiểu Tuyết; hắn không đáp và cô quyết ở gần để hiểu."}),
/* ---- Chương 2: Hoắc Dịch Trì lo cho cô (mốc 9–17) ---- */
E11("h09","clinic","Lớp 11A3 và phòng y tế · Giờ nghỉ trưa","duyen","Giả thiếu máu",
"Hôm sau, Nhược Hi muốn thử phản ứng của Dịch Trì. Giờ nghỉ trưa, cô gục xuống bàn, mặt tái đi vì đã bỏ bữa sáng. Dịch Trì đi ra cửa lớp, rồi vòng lại, đỡ cô xuống phòng y tế. Bác sĩ nói cô chỉ bỏ bữa. Cô cười bảo hắn lo cho mình, hắn quay đi, tai đỏ.",
"Hắn quay lại đấy, ghi nhớ. Nhưng lần sau ăn sáng đi, đừng lấy sức khỏe ra thử người ta.",
"unh,udt,tc",[
 CH("Hơi tựa vào vai hắn trên đường xuống phòng y tế","mi",0.490,["Hắn cứng người nhưng không tránh. Đến cửa phòng y tế, hắn buông tay thật khẽ như sợ làm cô ngã.",{ac:-3,hac:-1,hao:4},"dt_tin"],["Cô tựa hơi mạnh, hắn khẽ chau mày. Hắn đỡ cô nhưng nhìn đi nơi khác.",{hao:1,sinh:-1}]),
 CH("Tự nói «chỉ choáng chút thôi» và để hắn đỡ","tri",0.520,["Hắn gật đầu, im lặng đi sát bên cô, tay đặt ở lưng ghế chờ cô ngồi xuống.",{ac:-2,hao:3,sinh:1},"dt_tin"],["Cô nói liền một hơi, nghe như đã chuẩn bị. Hắn nhìn cô ngờ vực.",{hao:0,sinh:-1}]),
 CH("Im lặng chờ xem hắn có quay lại thật không","van",0.470,["Cửa lớp bật mở, hắn quay lại thật. Cô hé mắt nhìn và thấy ngón tay hắn run nhẹ.",{ac:-3,hac:-1,hao:4},"dt_tin"],["Hắn đứng nhìn một lúc rồi đi gọi giáo viên. Cô thấy mình hơi quá đà.",{hao:0,sinh:-2}])],
{ctx:"Hôm sau, giờ nghỉ trưa. Nhược Hi giả thiếu máu để thử Dịch Trì; hắn đỡ cô xuống phòng y tế."}),

E11("h10","school","Phòng y tế và lớp học · Cùng trưa","chon","Cơm trưa",
"Dịch Trì mang đến cả một túi hộp cơm, đặt xuống bàn cô, dặn ăn đúng giờ rồi đỏ mặt nói: «Đừng hiểu lầm.» Cô nhìn mấy hộp cơm còn ấm, thấy cổ họng nghẹn lại.",
"Hắn không giỏi nói, nhưng giỏi lo. Nhìn kỹ thì thấy đấy.",
"unh,udt,tc",[
 CH("Cười, trêu: «Cậu mua gấp đôi để mình ăn hết à?»","mi",0.470,["Hắn quay mặt đi, tai đỏ hơn. «Ăn đi, nguội mất.» Nhưng khóe môi hắn khẽ nhếch.",{ac:-2,hao:3},"dt_tin"],["Hắn cau mày, nói «đừng trêu». Cô phải xin lỗi nhỏ một câu.",{hao:-1,hac:1}]),
 CH("Cảm ơn thật lòng và mời hắn ăn cùng","tri",0.540,["Hắn ngần ngừ rồi ngồi xuống. Hai người chia nhau hộp cơm, không ai nói gì nhiều nhưng bầu không khí dịu hẳn.",{ac:-3,hac:-1,hao:4,sinh:1},"dt_tin"],["Hắn lắc đầu, bảo đã ăn rồi, nhưng bụng hắn lại kêu. Cả hai đều ngượng.",{hao:1}]),
 CH("Ăn thật ngon miệng, không nói gì thêm","van",0.490,["Cô ăn hết từng hộp. Hắn liếc nhìn rồi quay đi, nhưng cô thấy nét mặt hắn giãn ra.",{ac:-2,hao:3,sinh:2},"dt_tin"],["Cô ăn nhanh quá, nghẹn một miếng. Hắn đưa chai nước, ngượng ngùng quay đi.",{hao:1,sinh:-1}])],
{ctx:"Cùng trưa. Dịch Trì mua cả túi cơm cho Nhược Hi và dặn đừng hiểu lầm."}),

E11("h11","street","Khu nhà Mộng Giai · Chiều cùng ngày","nan","Quả trứng thối",
"Cô đã báo trong nhóm đừng để quả trứng lâu và đừng đập ra. Mộng Giai giữ nó cả tháng rồi đập ra. Mùi hôi lan khắp khu chung cư, vài trẻ nhỏ và người già choáng váng, hàng xóm báo cảnh sát, Mộng Giai bị gọi lên đồn. Tần Dĩ Hằng không có mặt chiều đó. Nhược Hi theo dõi qua nhóm, chưa can thiệp.",
"Cô ta tự chọn đấy, không ai ép. Ngươi đã báo trước rồi, nhớ giữ tin nhắn.",
"unh,umg,uel,tc",[
 CH("Gửi vào nhóm ảnh chụp lời nhắc cũ của mình, không bình luận thêm","tri",0.510,["Ba đàn hữu đọc lại và không ai trách cô. Elara nhắn riêng: «Cô ấy tự chọn mà.»",{ac:-1,hao:1},"co_loi_nhac"],["Có người cho rằng cô đang ném đá xuống giếng. Cô cũng thấy khó chịu.",{hao:-1,sinh:-1}]),
 CH("Nhắn riêng cho Mộng Giai: «Mở cửa sổ, lau sạch rồi báo cho hàng xóm»","mi",0.440,["Mộng Giai không trả lời, nhưng cô ta mở cửa sổ và dọn sạch. Cô làm được việc nhỏ cần làm.",{ac:-1,sinh:1},"co_loi_nhac"],["Mộng Giai chặn tin nhắn của cô. Cô thở dài.",{hao:0}]),
 CH("Chỉ theo dõi, không can thiệp","",0,["Cô đọc từng dòng, ghi lại. Chuyện này không phải việc của cô, nhưng cô ghi nhớ.",{sinh:0}])],
{ctx:"Chiều cùng ngày, khu nhà Mộng Giai. Cô ta đập quả trứng giữ cả tháng; mùi hôi lan khắp khu và hàng xóm báo cảnh sát."}),

E11("h12","school","Lớp 11A3 · Sau giờ học","duyen","Hắn đợi sau giờ học",
"Sau giờ học, Nhược Hi ở lại làm bài tới sáu giờ rưỡi. Dịch Trì không về. Hắn nói chỉ muốn ngồi cho yên tĩnh rồi lỡ quát một câu, ngượng ngùng bỏ đi. Hôm sau hắn dặn bạn thân Đại Lực và mấy người trong nhóm để mắt tới cô.",
"Hắn lo đấy, chỉ là không biết nói. Đừng lấy đó làm chuyện để trêu.",
"unh,udt,udl,tc",[
 CH("Nói với hắn: «Hôm qua cậu quát hơi to, nhưng tớ biết cậu lo»","mi",0.480,["Hắn khựng lại, im lặng, rồi gật đầu. Cô thấy mắt hắn bớt lạnh.",{ac:-3,hao:4},"dt_tin"],["Hắn nói «không phải vậy» và bỏ đi nhanh. Cô thấy mình nói hơi sớm.",{hao:0,hac:1}]),
 CH("Cảm ơn Đại Lực và mấy bạn, mời mọi người một chầu trà sữa","van",0.510,["Đại Lực cười toe, bảo «đại ca dặn rồi». Cả nhóm kéo nhau đi, Dịch Trì đi sau cùng, lặng lẽ cười.",{ac:-2,hao:3,sinh:1},"dt_tin"],["Trà sữa hết giờ, cả nhóm tiếc nuối. Dịch Trì quay đi, vẻ không vui.",{hao:0,sinh:-1}]),
 CH("Giả vờ không biết, vẫn học bài tới giờ rồi cùng ra về","tri",0.520,["Hai người đi cạnh nhau ra cổng, hắn thôi quát, bắt chuyện về bài tập.",{ac:-2,hao:3},"dt_tin"],["Cô học quá lâu, hắn đi trước một đoạn. Cô chạy theo không kịp.",{hao:0,sinh:-1}])],
{ctx:"Sau giờ học, lớp 11A3. Dịch Trì đợi cô học xong, lỡ quát rồi dặn Đại Lực để mắt tới cô."}),

E11("h13","alley","Ngõ sau Nhị Trung · Tối","nan","Hắn biết ai là kẻ gây ra chuyện",
"Tối, Dịch Trì hỏi Đại Lực ai đã làm hại một nữ sinh Nhất Trung. Đại Lực nói tên Quan Đình Phong, cháu của Quan Tú Anh, tức dì ghẻ của hắn. Hắn giận run và đi tìm. Hôm sau hắn đến lớp mặt bầm, chỉ nói gọn là có va chạm, rồi quay sang nhìn cô. Chuyện nặng diễn ra ngoài tầm mắt cô; Tiểu Châu chỉ kể lại ngắn gọn.",
"Đây là mốc nặng. Hắn đã biết, và ngươi đã chậm một bước. Giờ phải kéo hắn lại trước khi cơn giận biến thành thứ khác.",
"unh,udt,udl,tc",[
 CH("Hỏi thẳng, đưa thuốc sát trùng, nói: «Đừng làm vậy vì tớ»","mi",0.440,["Hắn nhìn cô rất lâu, rồi cúi đầu. «Tớ… xin lỗi.» Lần đầu hắn nói xin lỗi bất cứ ai.",{ac:-4,hac:-3,hao:5,sinh:-1},"giu_dt"],["Hắn gạt tay cô, nói «cậu không hiểu». Cô vẫn ở lại băng cho hắn, dù hắn không nhìn.",{ac:-1,hao:1,sinh:-3},"giu_dt"]),
 CH("Ngồi cạnh hắn cả giờ ra chơi, không hỏi gì","van",0.500,["Hắn không nói, nhưng đôi vai căng cứng dần mềm lại. Cuối giờ hắn khẽ nói: «Cảm ơn.»",{ac:-3,hac:-2,hao:4,sinh:-1},"giu_dt"],["Hắn bỏ ra ngoài giữa giờ. Cô ngồi một mình nhìn chỗ trống bên cạnh.",{hao:0,hac:1,sinh:-2}]),
 CH("Nhắc hắn nhớ mục tiêu: cùng nhau thi vào Kinh Đại","tri",0.470,["Hắn im rất lâu, rồi gật. «Tớ không muốn tụt lại.» Cô thấy đó là lời hứa đầu tiên của hắn.",{ac:-3,hac:-2,hao:4,sinh:-1},"giu_dt"],["Hắn cười khẩy: «Kinh Đại thì được gì.» Cô nghẹn lời.",{ac:-1,hao:1,sinh:-3},"giu_dt"])],
{ctx:"Hôm sau, lớp 11A3. Dịch Trì biết Quan Đình Phong là kẻ gây ra chuyện và đi tìm hắn; cơn giận của hắn cần được kéo lại.",forced:1,fix:w11spike(14,7,"dt_tin")}),

E11("h14","school","Lớp học · Giờ toán","duyen","Bài hình trên bảng",
"Vài hôm sau, thầy Cao Văn Đạt gọi cô lên bảng giải một bài hình vượt chương. Cô giải không cần phác thảo, thầy xác nhận đáp án chuẩn, cả lớp lặng đi. Tần Dĩ Hằng nhìn cô rất lâu. Dịch Trì đang gục trên bàn khẽ ngẩng lên.",
"Hình học không gian là chỗ ngươi mạnh đấy. Giải thích cho người khác hiểu mới là kỹ năng thật.",
"unh,udt,udh,ucd,tc",[
 CH("Giải thích từng bước cho cả lớp, vẽ hình rõ ràng","tri",0.540,["Cả lớp ngồi nghe chăm chú, có người ghi lại. Dịch Trì ngồi thẳng người lần đầu trong giờ toán.",{ac:-2,hao:3,sinh:1},"giai_hinh"],["Cô vẽ sai một nét, phải xóa làm lại. Cả lớp hơi rối nhưng thầy cười động viên.",{hao:1,sinh:-2}]),
 CH("Viết đáp án gọn rồi xuống chỗ, không giải thích","van",0.500,["Thầy gật đầu, không hỏi thêm. Dịch Trì liếc bài giải của cô rồi chép lại vào vở.",{ac:-1,hao:2},"giai_hinh"],["Đáp án đúng nhưng trình bày quá vắn. Vài người hỏi lại, cô ngượng.",{hao:0}]),
 CH("Vừa giải vừa hỏi cả lớp từng bước tiếp theo","mi",0.470,["Cả lớp hào hứng trả lời, cô dẫn dắt khéo. Dịch Trì bất giác tham gia trả lời một câu.",{ac:-3,hao:3,sinh:1},"giai_hinh"],["Câu hỏi của cô quá khó, cả lớp im phăng phắc. Cô phải tự giải tiếp.",{hao:0,sinh:-1}])],
{ctx:"Vài hôm sau, giờ toán. Thầy Cao gọi Nhược Hi giải bài hình vượt chương; cô giải không cần phác thảo.",learn:{n:"Giải hình học không gian",s:"tri",v:1}}),

E11("h15","zstudy","Nhóm giao lưu vị diện · Cuối tuần","duyen","Khai Trí Đan",
"Mộng Giai điểm kém, sợ lộ ra là nhờ đan dược mới có chút tiến bộ, nên xin món thuốc giúp tăng trí. Nhược Hi nói rõ trong nhóm: tên Khai Trí Đan, mỗi viên giúp nửa canh giờ tỉnh táo, tác dụng phụ là nửa tháng sau tóc rụng một tháng, mỗi viên một tháng. Mộng Giai bỏ qua phần cuối, đổi đồ lấy năm viên. Cả nhóm đều đọc dòng cảnh báo đó.",
"Cảnh báo ghi rõ ràng, cả nhóm đều đọc. Cô ta chọn bỏ qua, không phải lỗi của ngươi. Nhưng nhớ ghim dòng cảnh báo lên đầu.",
"unh,umg,uth,uso,tc",[
 CH("Ghi rõ tác dụng phụ bằng chữ đậm, ghim lên đầu nhóm","tri",0.540,["Cả nhóm đều thấy dòng chữ. Soren nhắn: «Cô chủ nhóm làm việc cẩn thận thật.»",{ac:-2,hao:2},"canh_bao"],["Cô ghim nhầm tin nhắn, phải gỡ ra làm lại. Cuối cùng vẫn đủ rõ.",{hao:0,sinh:-1},"canh_bao"]),
 CH("Nói thẳng với Mộng Giai từng điều trong tin nhắn riêng","mi",0.470,["Mộng Giai đọc, trả lời «biết rồi», cô ta chọn bỏ qua. Cô đã nói đủ phần của mình.",{ac:-1,hao:1},"canh_bao"],["Mộng Giai không đọc kỹ, chỉ nhắn «nhanh lên». Cô phải nhắc lại lần nữa.",{hao:0}]),
 CH("Gửi bảng thuốc, để cô ta tự đọc rồi tự quyết","van",0.500,["Cả bảng thuốc có dòng cảnh báo ở cuối. Mộng Giai đọc lướt, chọn bỏ qua. Mọi người trong nhóm đều thấy.",{ac:-1,hao:1},"canh_bao"],["Bảng bị lỗi hiển thị một dòng. Cô phải gửi lại.",{hao:0,sinh:-1},"canh_bao"])],
{ctx:"Cuối tuần, trong nhóm. Mộng Giai xin thuốc tăng trí; Nhược Hi nói rõ tác dụng phụ rụng tóc, cô ta bỏ qua và đổi năm viên."}),

E11("h16","school","Phòng thi và phòng lấy phiếu điểm · Cuối học kỳ I","chon","Điểm cuối kỳ I",
"Cuối học kỳ, Nhược Hi đứng nhất khối. Mộng Giai tiến mười chín hạng nhờ đan, Dịch Trì hạng cuối. Nhược Hi nói với hắn rằng nếu muốn đi cùng cô lên Kinh Đại thì phải đổi cách sống. Hắn không đáp, chỉ nắm chặt phiếu điểm.",
"Hạng cuối là hạng cuối, nhưng hắn cầm phiếu điểm chặt đến vậy là có chuyện. Chọn cách nói cho đúng.",
"unh,udt,umg,tc",[
 CH("Khích lệ: «Cậu thông minh, chỉ cần muốn thôi»","mi",0.500,["Hắn ngẩng lên nhìn cô, mắt sáng một thoáng. «Thật à?» «Thật.» Hắn gật nhẹ.",{ac:-3,hac:-1,hao:4},"khich_le"],["Hắn cười khẩy: «Ai cũng nói vậy.» Cô lặng đi.",{hao:-1,hac:1}]),
 CH("Nói thẳng: «Hạng cuối không đưa cậu tới Kinh Đại»","tri",0.490,["Hắn im rất lâu, rồi nói: «Tớ biết.» Đó là lần đầu hắn thừa nhận điều gì với cô.",{ac:-3,hac:-1,hao:4},"noi_thang"],["Hắn bỏ ra ngoài, đóng sầm cửa. Cô biết mình nói hơi nặng.",{hao:-1,hac:1,sinh:-1}]),
 CH("Hỏi hắn: «Cậu muốn gì cho mình?»","van",0.470,["Hắn nghĩ rất lâu, rồi nói: «Tớ muốn không bị bỏ lại.» Cô gật, thấy tim mình mềm đi.",{ac:-4,hac:-2,hao:5},"hoi_muon"],["Hắn nhún vai: «Chẳng biết.» Cô thở dài.",{hao:0}])],
{ctx:"Cuối học kỳ I. Nhược Hi đứng nhất khối, Dịch Trì hạng cuối; cô nói hắn phải đổi cách sống nếu muốn cùng lên Kinh Đại."}),

E11("h17","school","Lớp 11A3 · Nửa tháng sau","hiem","Mộng Giai rụng tóc",
"Nửa tháng sau, lúc phát phiếu điểm, Mộng Giai gãi đầu và tóc rụng thành mảng. Cô ta chạy khỏi lớp, vào nhóm cầu cứu. Soren gửi nước mọc tóc nhưng không hợp thể trạng cô ta. Nhược Hi nhắc lại dòng cảnh báo ở mốc trước, đề nghị ba loại thuốc mọc tóc kèm tác dụng phụ: ngủ li bì, mất vị giác, đau đầu từng cơn. Mộng Giai từ chối cả ba, chuyển sang đội tóc giả và mũ. Đàn hữu bắt đầu xa cô ta. Không ai trong lớp cười nhạo ngoại hình cô ta.",
"Đây là hệ quả cô ta tự chọn. Ngươi đã đưa lối thoát, cô ta từ chối. Đừng chê ngoại hình cô ta, kể cả trong lòng.",
"unh,umg,uso,uth,tc",[
 CH("Nhắc lại dòng cảnh báo cũ và gửi ba loại thuốc kèm tác dụng phụ","tri",0.540,["Cô trình bày rõ từng loại, không thêm bớt một chữ. Mộng Giai đọc, từ chối cả ba, nhưng nhóm thấy cô công bằng.",{ac:-2,hao:2},"cong_bang"],["Cô gửi thiếu một loại, Soren phải bổ sung. Cô hơi ngượng.",{hao:0,sinh:-1}]),
 CH("Nhắn Mộng Giai một câu an ủi, không nhắc lại lỗi cũ","mi",0.480,["Mộng Giai không trả lời, nhưng đã đọc. Đàn hữu khen cô tử tế.",{ac:-2,hac:-1,hao:3},"cong_bang"],["Mộng Giai trả lời gay gắt: «Đừng thương hại tôi.» Cô lặng đi.",{hao:0}]),
 CH("Để cô ta tự chọn, không nhắn thêm","van",0.500,["Cô ta chọn tóc giả. Cô ghi nhớ rằng mình đã làm đủ phần của mình.",{ac:-1,hao:1,sinh:1}],["Mộng Giai im lặng rồi rời nhóm vài ngày. Cô thấy hơi áy náy.",{hao:0,sinh:-1}])],
{ctx:"Nửa tháng sau, lớp 11A3. Mộng Giai rụng tóc thành mảng, từ chối ba loại thuốc mọc tóc và chuyển sang đội tóc giả; đàn hữu bắt đầu xa cô ta."}),

/* ---- Chương 3: Hè và tin đồn nhà Quan (mốc 18–27) ---- */
E11("h18","apart","Trước nhà Trình · Mùa hè lớp 11","chon","Hắn đứng dưới lầu",
"Mùa hè, Dịch Trì nhắn tin mỗi ngày. Một chiều hắn đến đứng dưới lầu nhà Trình, chỉ để nhìn lên cửa sổ. Cô bước xuống nói chuyện. Tiểu Châu ghi nhận hắn đỡ cáu gắt hơn nhiều so với đầu năm.",
"Hắn đứng dưới lầu cả buổi rồi đấy. Mời hắn lên hay ra ngoài là ở ngươi, nhưng đừng để hắn đứng ngoài nắng.",
"unh,udt,tc",[
 CH("Mời hắn lên nhà ăn cơm với ba mẹ","mi",0.470,["Ba mẹ cô đón hắn chu đáo. Hắn ăn rất ít, nhưng lúc về ngoái nhìn lại ba lần.",{ac:-3,hac:-1,hao:4,sinh:1},"an_com_nha"],["Hắn ngại, từ chối. Cô đứng nói chuyện với hắn dưới lầu cả buổi.",{hao:1}]),
 CH("Hẹn ra quán ven đường uống nước mát","van",0.500,["Hai người ngồi ở quán nước nhỏ nghe tiếng ve. Hắn kể về ông ngoại, lần đầu nói nhiều như vậy.",{ac:-3,hao:4},"quan_nuoc"],["Quán đông, ồn quá. Hai người ngồi mười phút rồi về.",{hao:1}]),
 CH("Rủ hắn ra công viên ngồi nói chuyện bài vở","tri",0.520,["Hắn hỏi cô vài bài toán còn vướng. Cô giảng, hắn ghi lại. Trời chiều mát, hắn ngồi gần hơn một chút.",{ac:-2,hao:3,sinh:1},"cong_vien"],["Cô quên mang sách. Hai người ngồi nhìn nhau lúng túng rồi đi về.",{hao:0}])],
{ctx:"Mùa hè lớp 11, trước nhà Trình. Dịch Trì đứng dưới lầu chỉ để nhìn lên cửa sổ; cô bước xuống nói chuyện."}),

E11("h19","school","Căng tin Nhất Trung · Đầu lớp 12","hiem","Quan Đình Phong chặn đường",
"Đầu lớp 12, Quan Đình Phong lẻn vào căng tin Nhất Trung khi Dịch Trì không có mặt. Hắn từng thích Mộng Giai vì nhầm cô ta với cô bé thuở nhỏ từng giúp hắn; mẹ hắn là Quan phu nhân giữ hắn ở nhà nhưng hắn trốn đi. Hắn xin lỗi vụng về, tay run. Nhược Hi trả lời thẳng. Đại Lực và vài người đang kéo tới.",
"Đây là kẻ gây ra chuyện. Hắn đang xin lỗi, nhưng ngươi không nợ hắn sự tha thứ. Cẩn thận nhìn xung quanh.",
"unh,udp,udl,tc",[
 CH("Nói thẳng: «Tôi không tha, hãy ra trước pháp luật»","tri",0.520,["Hắn sững người, không biện hộ. Đại Lực kéo tới đưa hắn ra ngoài. Cô thở đều, tay vẫn nắm chặt khay cơm.",{ac:-2,hac:-1,hao:3,sinh:-1},"khong_tha"],["Giọng cô lạc đi một chút. Hắn cúi đầu nhưng chưa chịu đi. Phải đợi Đại Lực tới.",{hao:0,sinh:-3}]),
 CH("Đứng yên, nhìn thẳng vào mắt hắn, không đáp","mi",0.470,["Hắn không chịu nổi ánh nhìn của cô. Hắn lùi hai bước, rồi bị Đại Lực đưa ra ngoài.",{ac:-2,hao:3,sinh:-1},"khong_tha"],["Hắn nói liên tục, cô cứng người không đáp được. Đại Lực phải tới cắt ngang.",{hao:0,sinh:-3}]),
 CH("Gọi Đại Lực ngay lập tức, rời căng tin","van",0.500,["Đại Lực và vài bạn kéo tới ngay. Cô đi ra cửa, hắn bị chặn lại ở phía sau.",{ac:-1,hao:2,sinh:1},"goi_dai_luc"],["Điện thoại cô tắt pin giữa lúc cần. Cô phải chạy ra hành lang.",{hao:0,sinh:-3}])],
{ctx:"Đầu lớp 12, căng tin Nhất Trung. Quan Đình Phong lẻn vào xin lỗi vụng về; Nhược Hi nói thẳng cô không tha và để Đại Lực đưa hắn ra ngoài."}),

E11("h20","school","Lớp 12 · Cuối giờ tự học","chon","Thư tay trong giờ tự học",
"Cuối giờ tự học, Dịch Trì viết lên một trang vở rồi đẩy sang: hắn nghĩ mình thật sự thích cô. Nhược Hi đọc xong, viết lại ba chữ «em cũng vậy». Hắn đỏ mặt, khẽ nắm tay cô dưới bàn rồi buông ra ngay. Cô thấy ngón tay hắn run.",
"Hai đứa nhỏ viết thư trong giờ tự học, dễ thương thật. Nhưng nhớ mục tiêu: Kinh Đại. Đừng để thứ này lấn át bài vở.",
"unh,udt,tc",[
 CH("Viết «em cũng vậy», nắm tay hắn một lúc","mi",0.490,["Hắn nắm lại tay cô, nhẹ như chạm vào cánh bướm. Cả hai đều đỏ mặt, không ai nhìn ai.",{ac:-4,hac:-2,hao:6},"thu_tay"],["Hắn buông ra quá nhanh, giữ tay trong túi áo. Cô thấy hơi hụt hẫng.",{hao:1}]),
 CH("Viết điều kiện: «Cùng cố gắng vào Kinh Đại nhé»","tri",0.520,["Hắn đọc xong, cầm bút viết đáp lại: «Được.» Chữ hắn nắn nót hơn mọi khi.",{ac:-4,hac:-2,hao:5,sinh:1},"hen_kinh_dai"],["Hắn gạch bỏ rồi viết lại, nét chữ vội vàng. Cả hai đều ngượng.",{hao:1}]),
 CH("Trêu hắn: «Cậu viết thư cẩu thả quá»","van",0.430,["Hắn bật cười khẽ, tiếng cười ngắn mà thật. Cô nhìn nụ cười đó và thấy mọi chuyện đều đáng.",{ac:-3,hac:-1,hao:5},"thu_tay"],["Hắn cau mày, đóng vở lại. Cô hối hận vì trêu sai lúc.",{hao:-1,hac:1}])],
{ctx:"Cuối giờ tự học, lớp 12. Dịch Trì viết thư tay nói hắn thích cô; cô viết lại «em cũng vậy»."}),

E11("h21","zstudy","Thư viện và nhà ông ngoại · Mấy tháng sau","duyen","Hắn quyết học",
"Dịch Trì không muốn bị bỏ lại. Hắn xin ông ngoại Dư Chấn Hoa tìm thầy dạy thêm, rồi nhờ cô dạy kèm toán và lý. Hắn ngủ lớp ít dần, xếp sách đầy cặp. Ông ngoại nhìn cô, gật đầu thật khẽ.",
"Hắn đang cố đấy. Dạy người khác là kỹ năng khác với tự giỏi. Làm cho tốt.",
"unh,udt,uco,tc",[
 CH("Dạy từng bước, đợi hắn hiểu chắc mới sang bước sau","tri",0.540,["Hắn hiểu nhanh hơn dự kiến. Ông ngoại ngồi nghe ngoài cửa phòng, mỉm cười.",{ac:-2,hao:3,sinh:1},"day_tung_buoc"],["Hắn chưa hiểu phần phương trình, cô phải giảng lại hai lần. Cả hai đều mệt.",{hao:1,sinh:-2},"day_tung_buoc"]),
 CH("Để hắn tự làm, cô chỉ chữa lỗi sau","van",0.490,["Hắn sai ba lần rồi tự tìm ra lối. Hắn nhìn cô, mắt sáng: «Tớ làm được.»",{ac:-3,hac:-1,hao:4},"tu_lam"],["Hắn bí quá, bực bội bỏ sách xuống. Cô phải dỗ mãi mới học tiếp.",{hao:0,sinh:-2}]),
 CH("Rủ Đại Lực học cùng, tạo không khí nhóm học","mi",0.470,["Đại Lực kéo theo hai bạn nữa. Phòng học sôi nổi, Dịch Trì cũng cười nhiều hơn.",{ac:-3,hao:4,sinh:1},"nhom_hoc"],["Cả nhóm nói chuyện nhiều hơn học. Cô phải chia nhỏ lại cho yên.",{hao:1,sinh:-1}])],
{ctx:"Mấy tháng sau, thư viện và nhà ông ngoại. Dịch Trì quyết học, nhờ Nhược Hi dạy kèm toán và lý.",learn:{n:"Dạy kèm",s:"tri",v:1}}),

E11("h22","school","Bảng điểm trên cửa lớp · Cuối học kỳ II","duyen","Hắn vào top 10",
"Cô soạn kế hoạch ôn tập từng tuần cho hắn. Điểm của hắn lên rất nhanh, vào top 10 của khối nhờ toán, lý, ngoại ngữ; ngữ văn còn khó khăn mới đạt. Tần Dĩ Hằng giữ hạng ba, Mộng Giai hạng mười hai và nhìn cả hai bằng ánh mắt khó chịu.",
"Top 10 rồi, hắn tự làm được đấy. Kế hoạch tuần là lý do. Đừng quên khen hắn.",
"unh,udt,udh,umg,tc",[
 CH("Gói riêng một phần thưởng nhỏ, mang đến cho hắn","mi",0.490,["Hắn mở gói, thấy cuốn sổ nhỏ có câu: «Chúc mừng». Hắn không nói gì, chỉ ôm sổ chặt hơn.",{ac:-4,hac:-2,hao:5},"khen_dt"],["Hắn cầm gói, nói «cảm ơn» khô khốc rồi cất đi. Cô hơi hụt hẫng.",{hao:1}]),
 CH("Cùng hắn xem lại từng môn, chỉ ra chỗ còn thiếu","tri",0.520,["Hắn gật lia lịa, ghi chép. Hắn nói: «Học kỳ sau tớ lên top 5.»",{ac:-3,hao:4,sinh:1},"xem_diem"],["Kế hoạch của cô thiếu mục ngữ văn, hắn lo. Cô phải bổ sung thêm.",{hao:1,sinh:-2}]),
 CH("Nói với hắn: «Cậu giỏi lắm»","van",0.500,["Hắn đỏ mặt, quay đi. «Đừng khen nữa.» Nhưng khóe môi hắn khẽ nhếch.",{ac:-3,hac:-1,hao:4},"khen_dt"],["Hắn cau mày: «Đừng khen nữa, chưa đủ.» Cô hiểu hắn đang tự nghiêm khắc.",{hao:0}])],
{ctx:"Cuối học kỳ II. Dịch Trì vào top 10 khối nhờ kế hoạch ôn tập từng tuần của Nhược Hi.",learn:{n:"Lập kế hoạch ôn thi",s:"tri",v:1}}),

E11("h23","apart","Nhà Trình · Tuần sau phát phiếu điểm","hiem","Quan phu nhân tới nhà",
"Quan phu nhân thấy con trai cứ tới trường tìm cô. Bà cho rằng cô quyến rũ con mình và đe dọa nhà Trình nếu cô còn lại gần. Ba mẹ cô giận nhưng không đáp lại. Nhược Hi nói bình tĩnh rằng bà nên hỏi chính con trai mình. Bà ra về.",
"Bà ta tới để dọa. Ngươi đừng sợ, cũng đừng cãi to. Giữ giọng, và nhớ nhà Trình vẫn đang còn yếu.",
"unh,uqq,uba,ume,tc",[
 CH("Nói rõ ràng: «Bà nên hỏi con trai mình xem ai tìm ai»","tri",0.510,["Bà ngập ngừng, không đáp được. Ba mẹ nhìn cô, tự hào lẫn xót xa.",{ac:-2,hao:2,sinh:1},"binh_tinh"],["Giọng cô hơi cao, bà càng gắt hơn. Ba phải đứng ra mời bà về.",{hao:0,sinh:-3}]),
 CH("Rót trà mời bà, nói chuyện nhẹ nhàng","mi",0.460,["Bà không nhận trà nhưng giọng bà dịu đi. Bà ra về mà không to tiếng thêm.",{ac:-2,hao:2,sinh:1},"binh_tinh"],["Bà hất tay, tách trà rơi vỡ. Cô cúi nhặt mảnh vỡ trong im lặng.",{hao:0,sinh:-3}]),
 CH("Im lặng đứng cạnh ba mẹ, để bà nói hết","van",0.490,["Bà nói một hồi rồi cũng dừng, nhìn quanh nhà. Bà thấy ba mẹ cô chẳng sợ gì, và ra về.",{ac:-1,hao:1,sinh:1}],["Bà nói quá lâu, ba mẹ cô nghe như bị ép. Cô đứng cạnh cắn môi.",{hao:0,sinh:-3}])],
{ctx:"Tuần sau phát phiếu điểm, nhà Trình. Quan phu nhân đe dọa nhà Trình vì cho rằng cô quyến rũ con trai bà."}),

E11("h24","zoffice","Công ty Trình · Vài hôm sau","nan","Hai nhà cùng chèn ép Trình gia",
"Ba mẹ về nhà muộn. Quan gia bắt đầu ép các đối tác của Trình gia. Quan Tú Anh nói với Hoắc Chấn Hải khiến Hoắc thị cũng làm khó. Dịch Trì nghe tin, cắn răng. Nhược Hi biết một tờ chứng cứ trong tay có thể xoay chiều, nhưng cô cần thời gian để tìm đúng tờ.",
"Hai nhà cùng ép, nghe đáng sợ nhưng chưa sụp. Ba mẹ ngươi cần biết con gái có cách, nhưng đừng khoe.",
"unh,uba,ume,udt,tc",[
 CH("Nói với ba mẹ: «Con có cách, xin ba mẹ cho con vài ngày»","tri",0.510,["Ba nhìn cô lâu rồi gật. «Ba tin con.» Mẹ đặt tay lên vai cô, im lặng.",{ac:-2,hao:2,sinh:2},"ba_me_chap"],["Ba mẹ lo, hỏi dồn. Cô không giải thích đủ nên cả hai càng bất an.",{hao:0,sinh:-3}]),
 CH("Nhắn Dịch Trì: «Đừng làm gì vội, đợi tớ»","mi",0.460,["Hắn nhắn lại một chữ: «Được.» Cô biết hắn đang cố kìm lại.",{ac:-3,hac:-2,hao:3},"giu_dt_kim"],["Hắn không trả lời cả đêm. Cô lo lắng tới sáng.",{hac:1,hao:0,sinh:-2}]),
 CH("Chờ thêm vài ngày xem tình hình, không nói gì","van",0.460,["Cô ngồi cả đêm suy nghĩ. Sáng hôm sau cô biết mình nên làm gì, và hơi thở trở nên đều.",{ac:-1,hao:1,sinh:1}],["Cô chờ mà không yên, ngày nào cũng nhận thêm tin xấu. Sinh lực cạn dần.",{hao:0,sinh:-4}])],
{ctx:"Vài hôm sau, công ty Trình. Quan gia và Hoắc thị cùng chèn ép nhà Trình; Dịch Trì nghe tin và cắn răng."}),

E11("h25","apart","Phòng Nhược Hi · Cùng hôm","duyen","Lần theo sổ sách của Quan gia",
"Tiểu Châu có thể thâm nhập dữ liệu công khai và nội bộ của Quan thị. Nó giúp cô lần ra bằng chứng trốn thuế và các giao dịch ngầm, nhưng cô phải tự học cách đọc báo cáo tài chính để biết đoạn nào đáng tin. Sau lưng Quan gia còn có một quan chức bảo kê.",
"Nhiều con số lắm. Đọc chậm, đối chiếu từng cột. Cái gì cũng phải có nguồn.",
"unh,tc",[
 CH("Đối chiếu từng khoản, lập bảng riêng","tri",0.520,["Con số khớp nhau từng dòng. Cô nhìn bảng tổng hợp, biết mình đã nắm đủ.",{sinh:2},"so_sach"],["Cô sai một dòng, phải làm lại cả cột. Gần sáng mới xong.",{sinh:-3},"so_sach"]),
 CH("Nhờ Tiểu Châu đánh dấu những chỗ đáng ngờ trước, rồi tự kiểm lại","van",0.490,["Tiểu Châu đánh dấu bảy chỗ, cô kiểm lại và thấy năm chỗ thật sự có vấn đề.",{sinh:1},"so_sach"],["Tiểu Châu đánh dấu quá nhiều, cô mất cả đêm lọc lại.",{sinh:-3}]),
 CH("Học cách đọc báo cáo từ các video giảng của giáo sư kinh tế","mi",0.460,["Cô tìm được một chuỗi bài giảng rõ ràng. Hiểu xong, các cột số không còn đáng sợ.",{sinh:2},"so_sach"],["Cô chọn nhầm bài giảng quá cao, đầu óc rối. Phải bắt đầu lại.",{sinh:-4}])],
{ctx:"Cùng hôm, phòng Nhược Hi. Tiểu Châu giúp cô lần ra bằng chứng trốn thuế và giao dịch ngầm của Quan thị.",learn:{n:"Đọc báo cáo tài chính",s:"tri",v:1}}),

E11("h26","apart","Phòng Nhược Hi · Hôm sau","chon","Chuyển bằng chứng",
"Có ba cách xử lý chứng cứ: gửi thẳng cơ quan thanh tra, báo ẩn danh cho quan chức bảo kê để hắn tự rút lui, hoặc chờ thêm chứng cứ. Mỗi cách đi một đường khác nhau, và Dịch Trì đang đợi tin nhắn của cô.",
"Gửi thanh tra là đường thẳng nhất. Báo cho quan chức là đánh cược. Chờ thì có thể nhà Trình chịu thêm một tháng nữa.",
"unh,tc",[
 CH("Gửi thẳng cho cơ quan thanh tra, kèm bảng đối chiếu","tri",0.540,["Hồ sơ gọn và đủ, thanh tra nhận ngay. Cô gửi xong, thấy mình nhẹ hẳn.",{ac:-3,hac:-1,hao:3,sinh:1},"gui_thanh_tra"],["Hồ sơ thiếu một mục, thanh tra yêu cầu bổ sung. Cô mất thêm một ngày.",{hao:0,sinh:-2},"gui_thanh_tra"],{bonus:sk11("Đọc báo cáo tài chính",.08)}),
 CH("Báo ẩn danh cho quan chức bảo kê để hắn tự rút lui","van",0.350,["Quan chức rút khỏi Quan gia ngay đêm đó. Cô thở phào, nhưng linh cảm có điều chưa ổn.",{hao:1,sinh:-1},"bao_quan_chuc"],["Quan chức cảnh giác, sai người dò tung tích. Cô phải xóa dấu vết suốt đêm.",{hac:2,hao:-2,sinh:-5}]),
 CH("Chờ thêm chứng cứ, chưa gửi vội","",0,["Cô chờ thêm hai hôm, thu thêm vài chứng từ, trong lúc nhà Trình chịu thêm sức ép. Cô nghĩ mình đã đủ chắc tay để gửi.",{hac:1,sinh:-3,hao:0}])],
{ctx:"Hôm sau, phòng Nhược Hi. Cô chọn cách chuyển bằng chứng thuế và hối lộ của Quan gia."}),

E11("h27","zoffice","Tập đoàn Quan thị · Vài giờ sau","duyen","Quan gia sụp đổ",
"Thanh tra tới tập đoàn Quan thị. Quan phu nhân và Quan Tú Anh bị tạm giữ. Quan gia không còn kịp bảo vệ nhà Trình. Hoắc Chấn Hải phải bỏ chèn ép. Ba mẹ Trình thở ra, nhìn con gái thật lâu mà không hỏi gì.",
"Quan gia đổ rồi. Dịch Trì sẽ biết trước ngươi hai phút. Nhắn hắn, đừng để hắn tìm đến ngõ sau Nhị Trung lần nữa.",
"unh,uba,ume,uta,uqq,tc",[
 CH("Ở lại cạnh ba mẹ, đặt tay lên vai hai người","van",0.490,["Ba mẹ không hỏi, cô không nói. Cả ba ngồi cạnh nhau trong phòng khách tối, không ai muốn bật đèn.",{ac:-2,hao:2,sinh:3},"o_canh_ba_me"],["Mẹ òa khóc, ba lặng lẽ lau mắt. Cô nghẹn lời, chỉ biết ngồi cạnh.",{hao:0,sinh:-2}]),
 CH("Nhắn Dịch Trì: «Xong rồi. Cậu không cần làm gì nữa»","mi",0.480,["Hắn nhắn lại sau mười giây: «Tớ đến ngay.» Rồi hắn xuất hiện dưới lầu, thở dốc.",{ac:-4,hac:-3,hao:5,sinh:1},"bao_dt"],["Hắn đọc tin nhưng không trả lời. Cô lo cả đêm.",{hao:0,hac:1,sinh:-2}]),
 CH("Ghi lại danh sách việc cần làm tiếp theo trước khi quên","tri",0.510,["Cô viết xong, thấy mình đã sẵn sàng cho giai đoạn tiếp theo. Một việc đã xong, việc khác đang chờ.",{ac:-1,hao:1,sinh:2},"ke_hoach"],["Cô mệt quá, viết lộn xộn. Hôm sau phải chép lại.",{hao:0,sinh:-2}])],
{ctx:"Vài giờ sau, tập đoàn Quan thị. Thanh tra tới; Quan phu nhân và Quan Tú Anh bị tạm giữ và nhà Trình thở ra."}),
/* ---- Chương 4: Phiên tòa và vốn đầu tư (mốc 28–35) ---- */
E11("h28","zstudy","Thư phòng nhà Trình · Hôm sau","chon","Ba mẹ khởi kiện",
"Hôm sau, Nhược Hi đưa cho ba mẹ chứng cứ camera đã khôi phục từ mốc ba. Ba mẹ nộp đơn kiện Quan Đình Phong. Luật sư hỏi cô có muốn đích thân ra làm chứng hay không, vì lời của người bị hại luôn có sức nặng.",
"Đây là bản gốc cô đã giữ sạch từ đầu. Chọn cách ra mặt, nhưng nhớ cô vẫn còn nhỏ, cứ để luật sư lo phần khó.",
"unh,uba,ume,tc",[
 CH("Tự đứng ra làm chứng, nói rõ từng chi tiết","mi",0.470,["Luật sư gật đầu hài lòng. Ba mẹ nhìn cô, ánh mắt vừa lo vừa tự hào.",{ac:-2,hao:2,sinh:-1},"lam_chung"],["Cô nói hơi lủng củng khi luyện thử, luật sư phải chỉnh lại. Cô thấy mình còn thiếu một chút.",{hao:0,sinh:-3}],{bonus:function(){return (S.f.giu_cam?.08:0)}}),
 CH("Để luật sư trình bày, cô chỉ bổ sung khi cần","tri",0.520,["Luật sư trình bày gọn, hồ sơ chắc chắn. Cô thấy yên tâm hơn nhiều.",{ac:-1,hao:1,sinh:2},"luat_su"],["Luật sư hiểu sai một chi tiết nhỏ, cô phải chỉnh lại. Mất cả buổi chiều.",{hao:0,sinh:-2}]),
 CH("Hỏi ba mẹ ý kiến rồi cùng quyết","van",0.480,["Ba mẹ bàn với nhau rất lâu, rồi quyết định để cô tự chọn. Cô chọn làm chứng, nhưng chuẩn bị kỹ.",{ac:-1,hao:2,sinh:1}],["Ba mẹ bất đồng ý kiến, cô phải làm trung gian cả buổi tối. Mệt rã người.",{hao:0,sinh:-3}])],
{ctx:"Hôm sau, thư phòng nhà Trình. Ba mẹ nộp đơn kiện Đình Phong với chứng cứ camera Nhược Hi đã khôi phục."}),

E11("h29","zvilla","Nhà họ Hoắc · Cuối tuần","duyen","Dịch Trì về Hoắc thị",
"Hoắc Chấn Hải gọi con về vì Hoắc thị mất đối tác. Dịch Trì nói sẽ lấy lại phần của mẹ hắn, bảo vệ cô, và vẫn học song song. Cha hắn chịu nhún vì cần hắn. Sau đó hắn tìm cô, nói: «Anh sẽ cùng em thi vào Kinh Đại.»",
"Hắn lần đầu tự đứng ra đòi quyền của mình. Cô nên có mặt khi hắn bước ra.",
"unh,udt,uch,tc",[
 CH("Đợi hắn ngoài cổng nhà họ Hoắc, đưa chai nước ấm","mi",0.490,["Hắn bước ra, thấy cô, bước chân chậm lại. «Em đợi lâu chưa?» «Chưa đâu.» Hắn nhận chai nước, tay run nhẹ.",{ac:-4,hac:-2,hao:5},"cho_cong"],["Cô đứng nhầm cổng. Hắn đi ra bằng cửa phụ, cô phải chạy theo.",{hao:1,sinh:-1}]),
 CH("Hỏi hắn: «Anh muốn lấy lại gì trước?»","tri",0.510,["Hắn nghĩ lâu rồi trả lời: «Tên mẹ trong sổ cổ đông.» Cô gật, thấy hắn đã có kế hoạch riêng.",{ac:-3,hac:-1,hao:4,sinh:1},"hoi_muc_tieu"],["Hắn lảng tránh: «Chuyện của anh.» Cô gật, không hỏi thêm.",{hao:0}]),
 CH("Nhắc hắn không được bỏ học, dù Hoắc thị bận","van",0.480,["Hắn gật đầu: «Anh hứa.» Nụ cười hắn nhẹ hơn mọi lần.",{ac:-3,hac:-1,hao:4},"hua_khong_bo_hoc"],["Hắn cau mày: «Em cũng như ông ngoại.» Cô lặng đi vì bị hiểu nhầm.",{hao:-1,hac:1}])],
{ctx:"Cuối tuần, nhà họ Hoắc. Dịch Trì nói sẽ lấy lại phần của mẹ, bảo vệ cô, và hứa cùng cô thi vào Kinh Đại."}),

E11("h30","zoffice","Tòa án thành phố Thanh Giang · Một tháng sau","chon","Phiên tòa",
"Đình Phong và Mộng Giai bị gọi làm nhân chứng. Nhược Hi trình chứng cứ camera. Mộng Giai chối rằng không biết mình đã đụng ngã ai. Đoạn phim cho thấy rõ. Đình Phong không biện hộ nhiều. Thẩm phán chờ phần trình bày của cô.",
"Chứng cứ sạch đã có. Giờ là phần nói. Ngắn gọn hay kỹ lưỡng, đều có cái giá của nó.",
"unh,umg,udp,tc",[
 CH("Trình bày ngắn gọn, chỉ nêu mốc thời gian và hình ảnh chính","tri",0.540,["Thẩm phán gật đầu liên tục. Phần trình bày gọn của cô khiến mọi người theo kịp từng giây.",{ac:-2,hao:3,sinh:1},"trinh_gon"],["Cô bỏ sót một chi tiết, luật sư phải bổ sung. Phiên tòa kéo dài thêm nửa giờ.",{hao:0,sinh:-3}],{bonus:function(){return (S.f.giu_cam?.07:0)+(S.f.gui_thanh_tra?.03:0)}}),
 CH("Kể từng chi tiết theo thứ tự, không bỏ sót","mi",0.470,["Cô nói chậm mà rõ. Thẩm phán ghi chép, nhìn cô bằng ánh mắt tôn trọng.",{ac:-2,hao:3,sinh:-1},"trinh_ky"],["Cô nói quá dài, thẩm phán nhắc đi vào trọng tâm. Cô đỏ mặt.",{hao:0,sinh:-3}]),
 CH("Để Mộng Giai tự khai trước, cô chỉ bổ sung sau","van",0.430,["Mộng Giai tự mâu thuẫn trước tòa. Cô chỉ cần trình đoạn phim, mọi chuyện rõ ngay.",{ac:-3,hao:4,sinh:1},"doi_khai"],["Mộng Giai khai bình tĩnh hơn dự kiến. Cô phải trình bày lại từ đầu.",{hao:0,sinh:-4}])],
{ctx:"Một tháng sau, tòa án Thanh Giang. Nhược Hi trình chứng cứ camera; Mộng Giai chối nhưng đoạn phim cho thấy rõ.",learn:{n:"Trình bày chứng cứ",s:"tri",v:1}}),

E11("h31","school","Hành lang tòa án · Sau phiên tòa","nan","Lời của Quan Đình Phong",
"Sau phiên tòa, Đình Phong xin nói riêng vài câu. Hắn xin lỗi, hỏi cô có nhớ công viên mười năm trước, nơi cô đã giúp một cậu bé bị bắt nạt. Cô nhớ ra. Hắn sụp đổ khi hiểu mình đã làm hại chính cô bé hắn luôn nhớ. Cô không tha thứ, nhưng cũng không nói lời nặng. Hắn bị tuyên án.",
"Câu chuyện cũ lộ ra. Ngươi không nợ hắn sự tha thứ, nhưng cũng không cần nói nặng. Hít sâu.",
"unh,udp,udt,tc",[
 CH("Nói điềm đạm: «Tôi nhớ, nhưng tôi không tha»","mi",0.480,["Hắn gật đầu, nước mắt rơi. Hắn xoay người đi, vai run. Cô đứng đó thở ra, nhẹ nhõm đến lạ.",{ac:-3,hac:-2,hao:3,sinh:1},"khong_tha_lan_hai"],["Cô nói xong thì giọng nghẹn. Hắn thấy và lặng đi lâu hơn cô dự tính.",{hao:0,sinh:-3}]),
 CH("Im lặng nghe hết, rồi quay đi","van",0.490,["Cô nghe từng lời mà không đáp. Khi quay đi, cô thấy mình không còn mang hắn theo nữa.",{ac:-2,hac:-1,hao:2,sinh:2}],["Cô nghe một lúc thì bước chân khựng lại. Hắn gọi, cô vẫn đi tiếp, tim đập mạnh.",{hao:0,sinh:-3}]),
 CH("Nhờ Dịch Trì đứng cạnh, chỉ nói một câu cuối","tri",0.500,["Dịch Trì đứng cạnh, không nói một câu. Cô nói gọn một câu cuối. Hắn gật, rời đi.",{ac:-3,hac:-2,hao:4,sinh:1},"dt_canh"],["Dịch Trì siết nắm tay, cô khẽ chạm vào tay áo hắn để giữ hắn lại. Chuyện qua nhanh nhưng căng.",{hac:1,hao:1,sinh:-3}])],
{ctx:"Sau phiên tòa, hành lang. Đình Phong xin lỗi, kể chuyện công viên mười năm trước; cô không tha nhưng không nói nặng lời."}),

E11("h32","school","Hành lang tòa án · Cùng lúc","chon","Bạn của Mộng Giai",
"Cô bạn cùng bàn của Mộng Giai khuyên cô ta cùng đi xin lỗi Nhược Hi. Mộng Giai nổi giận, đẩy bạn ra, nói mình không sai. Mọi người xung quanh đều thấy. Cô bạn nhìn Nhược Hi bằng ánh mắt áy náy.",
"Cô ta tự để lộ trước mặt mọi người. Ngươi không cần làm gì thêm, nhưng nói một câu cũng được.",
"unh,umg,tc",[
 CH("Nói với Mộng Giai một câu: «Cậu không cần xin lỗi tôi, chỉ cần dừng lại»","mi",0.440,["Mộng Giai im lặng, mặt tái dần. Cô bạn nhìn cô, khẽ gật đầu cảm ơn.",{ac:-2,hao:2,sinh:1},"noi_mg"],["Mộng Giai gắt lên «đừng lên mặt». Cô rút lời nhưng người xung quanh đã thấy đủ.",{hao:0,sinh:-2}]),
 CH("Để cô ta tự đối mặt, quay đi không nói","van",0.500,["Cô quay đi. Sau lưng cô, tiếng Mộng Giai nhỏ dần, rồi im hẳn.",{ac:-1,hao:1,sinh:1}],["Mộng Giai đuổi theo, gọi tên cô. Cô phải dừng lại nghe cô ta nói vài câu.",{hao:0,sinh:-2}]),
 CH("Cảm ơn cô bạn vì đã dám nói thật","tri",0.510,["Cô bạn đỏ mặt, ngập ngừng: «Mình sai khi không nói sớm hơn.» Cô gật, mỉm cười.",{ac:-2,hao:2,sinh:1},"cam_on_ban"],["Cô bạn xua tay, ngượng ngùng bỏ đi. Cô thấy hơi tiếc.",{hao:0}])],
{ctx:"Sau phiên tòa, hành lang. Mộng Giai đẩy cô bạn cùng bàn ra khi bị khuyên đi xin lỗi; mọi người đều thấy."}),

E11("h33","zmall","Quán cà phê gần trường · Mùa thu lớp 12","duyen","Vốn đầu tư",
"Dịch Trì đang lỡ một dự án vì thiếu vốn. Nhược Hi nói cô đã dùng tiền tiêu vặt mua vài cổ phiếu theo gợi ý của Tiểu Châu, kiếm được một khoản, và chuyển cho hắn đầu tư. Cô chỉ hắn cách đọc nhịp thị trường. Hắn chạy xe đến dưới nhà cô vì quá vui.",
"Tiền tiêu vặt là thật, lời cũng là thật. Phân tích từng bước, đừng bảo hắn làm theo vì tin ngươi.",
"unh,udt,tc",[
 CH("Chỉ hắn đọc biểu đồ và báo cáo, để hắn tự quyết","tri",0.530,["Hắn đọc xong, nói: «Anh hiểu rồi.» Hắn tự chọn đúng hướng, cô chỉ gật đầu.",{ac:-3,hac:-1,hao:4,sinh:1},"phan_tich"],["Hắn đọc sai một chỉ số, cô phải quay lại giảng. Cả hai ngồi thêm hai giờ.",{hao:1,sinh:-2}]),
 CH("Nói rõ rủi ro: «Lời có thể mất, đừng đặt hết vào»","van",0.490,["Hắn nghe xong, gật chắc nịch. Hắn chia vốn thành ba phần, chừa lại một phần dự phòng.",{ac:-3,hao:4},"rui_ro"],["Hắn bực vì cô nhắc nhiều: «Em không tin anh à?» Cô giải thích mãi mới êm.",{hao:0,sinh:-1}]),
 CH("Cười bảo: «Lãi thì chia đôi nhé»","mi",0.430,["Hắn bật cười, hứa sẽ để dành phần cho cô. Hai người cùng xem biểu đồ đến khi tối.",{ac:-3,hac:-1,hao:5},"chia_doi"],["Hắn tưởng cô nói thật, nghiêm giọng từ chối. Cô phải giải thích đó chỉ là đùa.",{hao:-1}])],
{ctx:"Mùa thu lớp 12. Nhược Hi chuyển khoản lời cổ phiếu cho Dịch Trì làm vốn dự án và chỉ hắn cách đọc nhịp thị trường.",learn:{n:"Phân tích cổ phiếu",s:"tri",v:1}}),

E11("h34","street","Mạng xã hội và văn phòng hiệu trưởng · Học kỳ I lớp 12","hiem","Tin đồn yêu sớm",
"Một bài viết trên mạng chê hai người, nói trường dung túng yêu sớm. Bình luận tăng nhanh. Nhược Hi viết lại một bài ngắn, đính kèm bảng điểm của cả hai. Dư luận đổi chiều. Dịch Trì công khai nhận khoản đầu tư của cô, không giấu giếm gì.",
"Tin đồn lan nhanh, nhưng bảng điểm thì thật. Viết ngắn, viết rõ, và nhớ nhắc đến thầy cô nữa.",
"unh,udt,ucd,tc",[
 CH("Viết một bài nghị luận ngắn, dẫn bảng điểm và lời thầy Cao","tri",0.520,["Bài viết được chia sẻ rộng. Thầy Cao nhắn: «Em viết có lý.» Dư luận quay đầu.",{ac:-3,hac:-1,hao:4,sinh:1},"viet_bai"],["Bài viết dài, ít người đọc hết. Cô chỉnh lại bản ngắn hơn mới có chút tác dụng.",{hao:1,sinh:-3}]),
 CH("Nhờ Dịch Trì cùng ký tên vào bản trả lời","mi",0.470,["Hắn không do dự ký ngay: «Anh ký.» Hai cái tên đứng cạnh nhau, rõ ràng và thẳng thắn.",{ac:-3,hac:-2,hao:5},"cung_ky"],["Hắn bận họp Hoắc thị, ký trễ. Bài đăng chậm một ngày, dư luận đã lan xa.",{hao:0,sinh:-3}]),
 CH("Im lặng chờ nhà trường lên tiếng","van",0.400,["Hiệu trưởng ra thông báo bảo vệ hai người. Cô thở ra, nhẹ cả lòng.",{ac:-1,hao:1,sinh:1}],["Nhà trường chậm trễ, tin đồn lan thêm một ngày. Cô thức tới sáng.",{hao:-1,hac:1,sinh:-4}])],
{ctx:"Học kỳ I lớp 12. Một bài đăng chê hai người yêu sớm; Nhược Hi viết bài nghị luận kèm bảng điểm và Dịch Trì công khai nhận khoản đầu tư.",learn:{n:"Viết nghị luận",s:"mi",v:1}}),

E11("h35","zstudy","Nhóm giao lưu vị diện · Đêm trước kỳ thi đại học","chon","Viên đan cuối của Mộng Giai",
"Mộng Giai thấy điểm thi thử không đủ nên năn nỉ đổi thêm Khai Trí Đan. Nhược Hi nói rõ chỉ đổi thêm một viên và dùng quá mười lăm viên thì đầu óc kiệt, lâu mới hồi phục. Mộng Giai đã dùng gần hết giới hạn đó và vẫn nhận. Cả nhóm đọc lại lời cảnh báo.",
"Cô ta đã dùng gần hết giới hạn. Ngươi đã nói rõ. Giờ là chọn đổi hay không.",
"unh,umg,uth,uel,tc",[
 CH("Đổi một viên, nhắc lại giới hạn một lần cuối","tri",0.510,["Mộng Giai nhận viên cuối, không nói cảm ơn. Cả nhóm đọc lại dòng cảnh báo và không ai trách cô.",{ac:-2,hao:2,sinh:1},"doi_vien"],["Mộng Giai nhận mà không đọc. Cô thở dài, thấy áy náy dù đã nói đủ.",{hao:0,sinh:-1}]),
 CH("Từ chối đổi: «Cậu đã dùng đủ rồi»","mi",0.480,["Mộng Giai gắt lên, rồi cô ta im lặng. Cô ta rời nhóm mà không nói gì thêm.",{ac:-3,hac:-1,hao:3,sinh:1},"tu_choi_vien"],["Mộng Giai chửi cô ích kỷ, nhóm bàn tán. Cô giữ nguyên quyết định nhưng thấy nặng lòng.",{hao:0,sinh:-3}]),
 CH("Hỏi Elara và Thanh Hạc xem họ nghĩ sao","van",0.500,["Cả hai đồng ý với cô. Thanh Hạc nhắn: «Chủ nhóm quyết đúng.» Cô thấy yên tâm.",{ac:-2,hao:2,sinh:1},"hoi_nhom"],["Hai người ý kiến trái chiều, cô phải tự quyết. Đêm đó cô khó ngủ.",{hao:0,sinh:-2}])],
{ctx:"Đêm trước kỳ thi đại học, trong nhóm. Mộng Giai xin đổi thêm Khai Trí Đan dù đã dùng gần hết giới hạn; cô nói rõ rồi cân nhắc."}),

/* ---- Chương 5: Kinh Đại và năm năm (mốc 36–42) ---- */
E11("h36","school","Trường thi · Tháng sáu","chon","Thi đại học",
"Tháng sáu, cô và Dịch Trì thi trong cùng một khu. Hai người ra khỏi phòng thi, đứng đợi nhau dưới tán cây. Cô hỏi hắn khoa nào khó nhất, hắn nói ngữ văn. Gió thổi qua, hắn chợt đưa cô cái quạt nhỏ hắn mang theo từ sáng.",
"Hết thi rồi. Hắn mang quạt cho ngươi từ sáng đấy. Chọn lời cho khéo.",
"unh,udt,tc",[
 CH("Trấn an hắn: «Anh làm tốt rồi, em tin»","mi",0.510,["Hắn thở ra, vai chùng xuống. «Có em nói thì anh tin.» Cô cười, đón cái quạt.",{ac:-3,hac:-1,hao:4,sinh:1},"tran_an"],["Hắn không tin được hết, chỉ gật. Cô đưa nước cho hắn uống.",{hao:1}]),
 CH("Trêu: «Ngữ văn thì để em dạy lại cho anh»","van",0.470,["Hắn bật cười, mắt cong lên. «Thi xong rồi mà.» «Còn đại học nữa.» Hắn đỏ mặt.",{ac:-3,hao:5},"treu_van"],["Hắn cau mày: «Em đừng nhắc nữa.» Hắn đi trước vài bước.",{hao:-1,hac:1}]),
 CH("Cùng hắn đi bộ về dưới tán cây, không bàn gì về bài thi","tri",0.520,["Hai người đi cạnh nhau, nói về mùa hè, về ông ngoại, về món ăn mình thích. Bài thi trôi vào quên lãng.",{ac:-3,hac:-1,hao:4,sinh:1},"di_bo_ve"],["Trời nắng gắt, hai người ướt đẫm mồ hôi, nhanh chóng chia tay ở ngã ba.",{hao:0,sinh:-1}])],
{ctx:"Tháng sáu, trường thi. Nhược Hi và Dịch Trì thi cùng khu và đợi nhau dưới tán cây."}),

E11("h37","school","Sân trường Nhất Trung · Cuối tháng sáu","duyen","Điểm thi và Kinh Đại",
"Kết quả được công bố. Cả hai đạt điểm tối đa ở hầu hết các môn, cả trường vỗ tay. Tần Dĩ Hằng vào cùng trường nhưng đã buông tình cảm. Mộng Giai chỉ đỗ một trường cao đẳng. Dịch Trì chọn ngành sinh học, Nhược Hi chọn toán.",
"Kinh Đại rồi. Cả hai đều đỗ. Giờ cười đi, đừng giấu.",
"unh,udt,udh,umg,tc",[
 CH("Chạy lại ôm Dịch Trì ngay giữa sân, mặc cả trường nhìn","mi",0.480,["Hắn đứng chết lặng, rồi vòng tay ôm lại. Cả sân trường cười rộ, vỗ tay. Tai hắn đỏ rực.",{ac:-4,hac:-3,hao:6,sinh:1},"om_san"],["Cô ôm hơi vội, Dịch Trì lùi nửa bước vì bất ngờ. Cả hai đều đỏ mặt rồi cười.",{hao:2,sinh:0}]),
 CH("Bắt tay hắn thật chặt, nói «cảm ơn vì đã cố gắng»","tri",0.510,["Hắn nhìn bàn tay hai người nắm chặt, mắt sáng. «Cảm ơn em.» Cả hai im lặng một lúc lâu.",{ac:-4,hac:-2,hao:5,sinh:1},"bat_tay"],["Tay hắn ra mồ hôi, cô nắm hụt. Cả hai bật cười.",{hao:1}]),
 CH("Nhờ thầy Cao chụp một tấm ảnh cho cả hai","van",0.500,["Thầy Cao chụp lại khoảnh khắc hai người đứng cạnh nhau dưới bảng điểm. Tấm ảnh sau này ở mãi trong ví hắn.",{ac:-3,hac:-1,hao:5},"chup_anh"],["Thầy Cao chụp lệch khung hình, cả hai nhìn nhau rồi cười. Chụp lại một tấm khác.",{hao:1}])],
{ctx:"Cuối tháng sáu, trường Nhất Trung. Cả hai đạt điểm tối đa, vào Kinh Đại; Dịch Trì chọn sinh học, Nhược Hi chọn toán."}),

E11("h38","zbridge","Kinh Đại · Năm năm sau","duyen","Năm năm",
"Tiểu Châu tóm tắt năm năm trôi qua. Nhược Hi học xong đại học, vào học tiến sĩ toán, công thức đầu tiên mang tên cô được công bố. Dịch Trì vừa học sinh học vừa điều hành Hoắc thị, lập phòng thí nghiệm riêng. Hai người vẫn gặp nhau mỗi tuần dù bận.",
"Năm năm trôi nhanh lắm. Hai người vẫn gặp nhau mỗi tuần, tốt rồi. Giờ chọn cách giữ nhịp cho thật vững.",
"unh,udt,tc",[
 CH("Giữ lịch hẹn cố định mỗi chiều thứ bảy, dù bận đến đâu","tri",0.520,["Mỗi chiều thứ bảy, cả hai đều có mặt. Thời gian ít, nhưng chưa bao giờ trống.",{ac:-3,hac:-2,hao:4,sinh:1},"lich_hen"],["Cô bận đề tài, hai lần hủy hẹn. Hắn không trách nhưng im lặng suốt buổi sau đó.",{hao:0,hac:1,sinh:-2}]),
 CH("Mang đồ ăn tới phòng thí nghiệm của hắn mỗi khi hắn thức khuya","mi",0.470,["Hắn mở hộp cơm, im lặng nhìn rồi thì thầm: «Anh không xứng.» Cô nắm tay hắn: «Anh xứng.»",{ac:-4,hac:-2,hao:5,sinh:-1},"mang_com"],["Hắn đang họp, bỏ quên hộp cơm đến nguội. Cô mang về, không trách.",{hao:0,sinh:-2}]),
 CH("Viết thư tay mỗi tuần như hồi cấp ba, dù đã có điện thoại","van",0.490,["Hắn giữ từng lá thư trong ngăn kéo. Khi đọc lại, hắn mỉm cười như hồi hai người còn mặc đồng phục.",{ac:-3,hac:-2,hao:5},"thu_tay_tuan"],["Một lá thư bị thất lạc. Hắn nhắn hỏi, cô viết bù lá khác.",{hao:1,sinh:-1}])],
{ctx:"Năm năm sau, Kinh Đại. Nhược Hi vào học tiến sĩ toán, Dịch Trì vừa học sinh học vừa điều hành Hoắc thị; hai người vẫn gặp nhau mỗi tuần."}),

E11("h39","ztea","Cửa hàng kem quen · Chiều thứ bảy","chon","Cửa hàng kem",
"Chiều thứ bảy, cửa hàng kem quen, cả hai hai mươi ba tuổi. Hắn hỏi cô thích vị nào, như hồi cấp ba. Cô cười và cầu hôn trước. Hắn đỏ mặt, bảo hắn sẽ tặng món quà quý nhất. Tiểu Châu báo sức khỏe hắn đang xuống vì làm việc quá độ.",
"Cô cầu hôn rồi đấy, nhưng đừng để vui mà quên sức khỏe hắn. Ép hắn nghỉ hay để hắn tự quyết, mỗi cách có cái giá.",
"unh,udt,tc",[
 CH("Ép hắn nghỉ hẳn một tuần, cô sẽ trông phòng thí nghiệm giúp","tri",0.480,["Hắn cãi ba câu rồi chịu thua. Một tuần hắn ngủ đủ giấc, sắc mặt hồng hơn hẳn.",{ac:-3,hac:-2,hao:5,sinh:-1},"ep_nghi"],["Hắn đồng ý nhưng lén vào phòng thí nghiệm ban đêm. Cô phát hiện, hai người cãi nhỏ.",{hac:1,hao:0,sinh:-3}]),
 CH("Để hắn tự quyết, chỉ nhắc nhẹ khi cần","mi",0.460,["Hắn giảm bớt giờ làm, tự lên lịch nghỉ. Cô thở ra, thấy hắn thật sự lớn.",{ac:-2,hao:4,sinh:1},"tu_nghi"],["Hắn gật đầu rồi quên ngay. Mấy ngày sau, hắn mệt đến mức không đứng vững.",{hac:2,hao:0,bs:-4,sinh:-2}]),
 CH("Cùng hắn lập lịch nghỉ ngơi và ăn uống hằng tuần","van",0.500,["Hai người ngồi cả buổi lập lịch, chia ô từng giờ. Hắn cười: «Giống thời cấp ba.»",{ac:-3,hac:-1,hao:5,sinh:1},"lap_lich"],["Lịch quá chặt, hắn thấy ngộp, nhăn mặt. Cô sửa lại, nhưng mất cả buổi chiều.",{hao:0,sinh:-1}])],
{ctx:"Chiều thứ bảy, cửa hàng kem quen. Nhược Hi cầu hôn; hắn hứa tặng món quà quý nhất và Tiểu Châu báo sức khỏe hắn đang xuống.",setf:"cau_hon"}),

E11("h40","clinic","Phòng bệnh · Một năm sau","nan","Lọ làn da tái sinh",
"Một năm sau, Dịch Trì ngất vì kiệt sức. Tỉnh dậy trong phòng bệnh, hắn đưa cô một bình dung dịch màu xanh: làn da tái sinh, hắn nghiên cứu suốt nhiều năm để sửa vết sẹo cho cô. Hắn tự trách vì năm đó đã không bảo vệ được cô, giọng khản đặc, tay run. Đây là mốc nặng: hắn đang kéo mình xuống vì cô.",
"Hắn tự trách mình rất nặng. Ngươi đã nói nhiều lần là ngươi không để ý, hãy nói lại, đừng để hắn tự dằn vặt.",
"unh,udt,tc",[
 CH("Nắm tay hắn thật chặt: «Em không để ý vết sẹo, em chỉ cần anh khỏe»","mi",0.470,["Hắn khóc, lần đầu để cô thấy. Cô ôm hắn cho đến khi hắn thôi run. Hắn thì thầm: «Anh sẽ khỏe.»",{ac:-5,hac:-4,hao:6,sinh:-2,bs:3},"noi_that_long"],["Hắn quay mặt đi, nghẹn lại: «Em nói vậy để anh yên tâm thôi.» Cô vẫn nắm tay hắn cả đêm.",{ac:-1,hac:-1,hao:2,sinh:-4}]),
 CH("Bảo hắn đừng làm cô lo, cô cần anh còn ở đó","tri",0.500,["Hắn nghe xong thì lặng đi, rồi gật đầu. «Anh xin lỗi.» Cô lắc đầu, dựa vào vai hắn.",{ac:-4,hac:-3,hao:5,sinh:-1,bs:2},"dung_lam_lo"],["Hắn nghe nhưng lòng vẫn nặng trĩu. Cô ngồi cạnh giường, canh hắn ngủ.",{ac:-1,hao:2,sinh:-3}]),
 CH("Ngồi cạnh im lặng, đợi hắn tự nói ra","van",0.460,["Hắn nói ra hết những điều giấu từ năm năm trước. Cô nghe từng chữ, không ngắt lời. Hắn thở ra như người đặt gánh.",{ac:-4,hac:-3,hao:5,sinh:-1,bs:2},"nghe_het"],["Hắn im lặng tới sáng, mắt đỏ hoe. Cô ngủ gục cạnh giường.",{hao:0,hac:1,sinh:-4}])],
{ctx:"Một năm sau, phòng bệnh. Dịch Trì ngất vì kiệt sức, đưa cô bình làn da tái sinh và tự trách vì đã không bảo vệ được cô.",forced:1,fix:function(d){var o=Object.assign({},d);o.set={hac:Math.min(95,S.hac+((S.f.ep_nghi||S.f.tu_nghi||S.f.lap_lich)?7:14))};return o}}),

E11("h41","zwed","Hội trường · Hôm sau","chon","Lễ cưới",
"Hôm sau, hội trường đầy người. Ba mẹ Trình, bạn học cũ, Đại Lực, ông ngoại Dư Chấn Hoa và nhiều người nữa đều tới. Nhược Hi thông báo về lọ dung dịch, rồi tự mình chủ trì hôn lễ cùng hắn. Hai người trao nhẫn. Cô chọn cách đáp lại lọ dung dịch: dùng thử hay giữ nguyên.",
"Lễ cưới của hai ngươi đấy. Dùng hay không dùng, ngươi quyết, và hắn sẽ tôn trọng.",
"unh,udt,uba,ume,udl,uco,tc",[
 CH("Nói trước toàn hội trường: «Em giữ nguyên, vì đó là em»","mi",0.490,["Cả hội trường lặng đi, rồi vỗ tay vang dội. Hắn nắm chặt tay cô, mắt đỏ.",{ac:-4,hac:-3,hao:6,sinh:1},"giu_seo"],["Cô nói hơi nghẹn, nhưng ai cũng hiểu. Hắn siết tay cô, không nói gì.",{ac:-1,hao:2,sinh:0}]),
 CH("Dùng thử dung dịch ngay, để hắn thấy thành quả của mình","tri",0.470,["Dung dịch ngấm vào da, mát lạnh. Hắn nhìn cô, mắt rưng rưng: «Cảm ơn em.» Cả hội trường lặng đi rồi vỗ tay.",{ac:-4,hac:-3,hao:6,sinh:2},"dung_thu"],["Phản ứng nhẹ làm da cô hơi rát. Hắn hoảng, nhưng cô mỉm cười trấn an.",{ac:-1,hao:2,sinh:-3}]),
 CH("Cất lọ dung dịch lại, nói để sau lễ cưới sẽ quyết","van",0.500,["Hắn gật đầu, không ép. Hai người trao nhẫn, mỉm cười đón tiếng chúc mừng.",{ac:-3,hac:-2,hao:5,sinh:1},"de_sau"],["Lễ cưới có chút ngập ngừng, khách bàn tán. Cô nắm tay hắn thật chặt để lấy bình tĩnh.",{hao:1,sinh:-2}])],
{ctx:"Hôm sau, hội trường. Nhược Hi thông báo về lọ dung dịch, tự mình chủ trì hôn lễ cùng Dịch Trì; hai người trao nhẫn."}),

E11("h42","zgarden","Sau lễ cưới · Chiều muộn","nan","Lời kết",
"Tiểu Châu tóm tắt những gì xảy ra sau lễ cưới. Dịch Trì ở bên cô, dù sức khỏe có lúc lên lúc xuống, và hắn học cách nghỉ ngơi đúng giờ. Mỗi chiều thứ bảy, hai người ra cửa hàng kem quen. Câu chuyện không kết bằng một cái chết, chỉ kết bằng việc hai người cùng đi tiếp. Kết cục thế nào, các con số của cô sẽ nói.",
"Đây là mốc cuối. Ngươi đã đi cùng hắn rất xa. Hắn ra sao, các con số sẽ trả lời.",
"unh,udt,tc",[
 CH("Gọi tên hắn khẽ, đưa tay ra","mi",0.520,["Hắn quay lại, nắm lấy tay cô. Không cần nói gì thêm. Chiều muộn chảy chậm lại.",{ac:-5,hac:-5,hao:6,sinh:-2},"goi_ten"],["Cô gọi nhỏ quá, hắn không nghe. Cô chạy tới nắm tay hắn, cười.",{ac:-2,hac:-1,hao:3,sinh:-3}],{bonus:function(){return (S.f.dt_tin?.06:0)+(S.f.noi_that_long?.06:0)+(S.f.nghe_het?.04:0)}}),
 CH("Ngồi cạnh hắn, kể lại từng mốc hai người đã đi qua","tri",0.500,["Cô kể, hắn nghe, thỉnh thoảng sửa lại một chi tiết. Hai người cười nhiều hơn khóc.",{ac:-4,hac:-4,hao:5,sinh:-1},"ke_lai"],["Cô quên một chi tiết, hắn nhắc lại. Cả hai bật cười, hơi ngượng.",{ac:-2,hac:-1,hao:2,sinh:-3}],{bonus:function(){return (S.f.lich_hen?.05:0)+(S.f.lap_lich?.05:0)}}),
 CH("Đợi hắn tự bước đến bên cạnh","van",0.470,["Hắn bước đến lúc hoàng hôn, ngồi xuống cạnh cô. «Anh ở đây rồi.»",{ac:-5,hac:-4,hao:6,sinh:-1},"cho_dt"],["Hắn chưa đến khi trời tối. Cô ngồi một mình, lòng không yên.",{ac:-2,hac:-1,hao:2,sinh:-4}],{bonus:function(){return (S.f.giu_seo?.05:0)+(S.f.dung_thu?.05:0)}})],
{ctx:"Sau lễ cưới, chiều muộn. Tiểu Châu tóm tắt: hai người cùng đi tiếp; không có cái chết."})
];
var IX11={};EV11.forEach(function(e,i){e.no=i+1;IX11[e.id]=i});
/* Giãn khoảng cách tỉ lệ giữa các lựa chọn trong cùng một mốc: lựa chọn hợp nhất dễ hơn hẳn lựa chọn lệch */
function w11spread(k){EV11.forEach(function(e){var r=e.ch.filter(function(c){return c.s&&typeof c.b==="number"||c.b0!==undefined});if(r.length<2)return;r.forEach(function(c){if(c.b0===undefined)c.b0=c.b});var m=r.reduce(function(a,c){return a+c.b0},0)/r.length;r.forEach(function(c){c.b=Math.max(.2,Math.min(.8,m+k*(c.b0-m)))})})}

var ENDS11={
 true:{n:"Chiều thứ bảy ở cửa hàng kem",c:"Tiểu Châu đọc kết quả: đạt, trọn vẹn. Ác niệm của Hoắc Dịch Trì đã về không. Sau lễ cưới, hắn học cách nghỉ ngơi đúng giờ, sức khỏe dần hồi lại. Phòng thí nghiệm của hắn có thêm một chiếc ghế cho cô, bàn của cô ở Kinh Đại có thêm một lọ hoa hắn đổi mỗi tuần. Mỗi chiều thứ bảy hai người vẫn ra cửa hàng kem quen, gọi đúng hai vị như hồi mười bảy tuổi. Vết sẹo trên má cô, dù giữ hay chữa, chưa bao giờ làm hắn ngừng nhìn cô như lần đầu.",gain:120,piece:1,heat:.1,scene:"zwed"},
 near:{n:"Vệt sẹo trong lòng hắn",c:"Tiểu Châu đọc kết quả: đạt, nhưng chưa trọn. Hai người cưới nhau, hắn vẫn ở bên cô và đã biết cách nghỉ ngơi. Nhưng thỉnh thoảng giữa đêm hắn vẫn dậy ngồi ngoài ban công, như muốn chắc cô vẫn ở đó. Vệt tự trách trong mắt hắn nhạt dần theo từng năm. Cô biết rồi nó cũng sẽ tan.",gain:90,piece:1,heat:.35,scene:"zgarden"},
 half:{n:"Hai bóng chờ nhau",c:"Tiểu Châu đọc kết quả: chưa đạt. Hai người vẫn cưới nhau, vẫn đi cạnh nhau, nhưng lời hứa nghỉ ngơi của hắn còn lửng lơ. Hắn vẫn làm việc quá giờ, cô vẫn đứng ngoài phòng thí nghiệm chờ hắn ra. Cô ở cạnh hắn những lúc hắn im lặng, hy vọng một ngày hắn tin rằng mình đã được tha thứ.",gain:60,piece:0,heat:.6,scene:"zstudy"},
 black:{n:"Cánh cửa phòng thí nghiệm",c:"Hắc hóa chạm 100. Tự trách nuốt hết những gì còn lại: hắn khóa trái phòng thí nghiệm, không nghe tên mình, không nghe lời cô, chỉ còn tiếng máy chạy suốt đêm. Bình dung dịch trên bàn lạnh dần. Tiểu Châu khẽ gọi cô đi trước khi ánh đèn cuối cùng tắt.",gain:0,piece:0,heat:1,scene:"clinic"},
 bdead:{n:"Giường bệnh không mở mắt",c:"Sinh mệnh của Hoắc Dịch Trì về 0. Hắn kiệt sức đến mức không hồi lại được. Cô ngồi bên giường bệnh rất lâu, tay vẫn nắm tay hắn, cho đến khi Tiểu Châu khẽ gọi cô về.",gain:0,piece:0,heat:.9,scene:"clinic"},
 dead:{n:"Sức cạn trước ngày cưới",c:"Sinh mệnh của cô cạn kiệt trước khi kịp tới ngày cưới. Cô gục xuống giữa lúc đang lo cho quá nhiều việc cùng lúc. Tiểu Châu kéo linh hồn cô đi, khi ở đâu đó Dịch Trì vẫn đang chạy tới bệnh viện.",gain:0,piece:0,heat:.8,scene:"clinic"}
};

function w11emblem(heat){
  /* Cuốn vở mở ra, một lá thư gấp ở giữa; vòng ngoài ngả đỏ dần theo Hắc hóa */
  return '<svg class="eye" viewBox="0 0 96 96" role="img" aria-label="Cuốn vở mở với lá thư gấp, vòng ngoài ngả đỏ dần theo Hắc hóa"><circle cx="48" cy="48" r="45" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="48" cy="48" r="45" fill="none" stroke="var(--ember)" stroke-width="2" stroke-dasharray="'+(heat*283)+' 283" transform="rotate(-90 48 48)"/>'
   +'<path d="M22 32 Q36 28 48 34 Q60 28 74 32 V66 Q60 62 48 68 Q36 62 22 66Z" fill="var(--surface)" stroke="var(--fg)" stroke-width="2.5" stroke-linejoin="round"/>'
   +'<path d="M48 34 V68" stroke="var(--fg)" stroke-width="2"/><path d="M28 42 H42 M28 49 H42 M54 42 H68 M54 49 H64" stroke="var(--fg)" stroke-width="1.8" stroke-linecap="round" opacity=".6"/>'
   +'<path d="M54 54 H68 V64 H54Z" fill="color-mix(in oklab,var(--ember) '+Math.round(heat*100)+'%,#dfe4ea)" stroke="var(--fg)" stroke-width="1.8"/><path d="M54 54 L61 60 L68 54" fill="none" stroke="var(--fg)" stroke-width="1.8"/></svg>';
}

