function w12spread(k){EV12.forEach(function(e){var r=e.ch.filter(function(c){return c.s&&typeof c.b==="number"||c.b0!==undefined});if(r.length<2)return;r.forEach(function(c){if(c.b0===undefined)c.b0=c.b});var m=r.reduce(function(a,c){return a+c.b0},0)/r.length;r.forEach(function(c){c.b=Math.max(.2,Math.min(.8,m+k*(c.b0-m)))})})}

var ENDS12={
 true:{n:"Mỗi sáng một câu hỏi",c:"Tiểu Châu đọc kết quả: đạt, trọn vẹn. Ác niệm của Giản Mặc Hành đã về không. Hắn học cách buông bớt kiểm soát, không dùng quyền thế chen vào chuyện cô tự giải quyết, và mỗi sáng vẫn hỏi cô một câu: «Hôm nay em có thích anh thêm một chút không?» Đoạn ghi âm ngày xưa được hắn đặt vào hộp riêng, không ai nghe lại. Tống Ý lên làm giám đốc studio; Triều Dương và Thi Dĩnh mỗi năm đều ghé nhà cô một lần. Họ có thêm một bộ phim nữa, rồi một bộ nữa, rồi thôi đếm.",gain:120,piece:1,heat:.1,scene:"ysea"},
 near:{n:"Hắn vẫn học cách buông",c:"Tiểu Châu đọc kết quả: đạt, nhưng chưa trọn. Hai người ở bên nhau, mỗi sáng vẫn có câu hỏi quen thuộc. Nhưng thỉnh thoảng hắn vẫn lặng lẽ kiểm tra lịch của cô, như không yên tâm. Cô không giận. Cô biết hắn đang học cách buông bớt từng chút một, và vệt tối trong mắt hắn mờ dần theo mỗi năm.",gain:90,piece:1,heat:.35,scene:"yroom"},
 half:{n:"Bóng người đứng chờ ngoài cửa",c:"Tiểu Châu đọc kết quả: chưa đạt. Hai người vẫn ở cạnh nhau, vẫn làm phim cùng nhau. Nhưng hắn còn nghiêng về chiếm hữu, chưa làm điều gì sai, chỉ hay đứng chờ ngoài cửa phòng hóa trang lâu hơn cần thiết. Cô ở cạnh hắn những lúc hắn im lặng, hy vọng một ngày hắn tin rằng mình không cần canh giữ ai.",gain:60,piece:0,heat:.6,scene:"ystudio"},
 black:{n:"Cánh cửa phòng chiếu khép lại",c:"Hắc hóa chạm 100. Nỗi sợ mất cô nuốt hết những gì còn lại ở hắn. Hắn không nghe tên mình, không nghe tiếng cô, chỉ còn tiếng máy chiếu quay vào phòng trống. Các cuốn phim chưa kịp quay nằm yên trên kệ. Tiểu Châu khẽ gọi cô đi trước khi ánh đèn cuối cùng tắt.",gain:0,piece:0,heat:1,scene:"ynight"},
 bdead:{n:"Chiếc ghế đạo diễn trống",c:"Sinh mệnh của Giản Mặc Hành về 0. Hắn kiệt sức vì chạy khắp nơi cho cô, không hồi lại được. Chiếc ghế đạo diễn ở phim trường trống từ hôm ấy. Cô ngồi bên hắn rất lâu, tay vẫn nắm tay hắn, cho đến khi Tiểu Châu khẽ gọi cô về.",gain:0,piece:0,heat:.9,scene:"yhosp"},
 dead:{n:"Sức cạn giữa rừng",c:"Sinh mệnh của cô cạn kiệt trước khi kịp trở về. Cô gục xuống giữa lúc đang lo cho quá nhiều việc cùng lúc. Tiểu Châu kéo linh hồn cô đi, khi ở đâu đó Mặc Hành vẫn đang chạy về phía rừng.",gain:0,piece:0,heat:.8,scene:"rforest"}
};

function w12emblem(heat){
  /* Bảng clap phim mở nửa, vòng ngoài ngả đỏ dần theo Hắc hóa */
  return '<svg class="eye" viewBox="0 0 96 96" role="img" aria-label="Bảng clap phim, vòng ngoài ngả đỏ dần theo Hắc hóa"><circle cx="48" cy="48" r="45" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="48" cy="48" r="45" fill="none" stroke="var(--ember)" stroke-width="2" stroke-dasharray="'+(heat*283)+' 283" transform="rotate(-90 48 48)"/>'
   +'<rect x="24" y="40" width="48" height="30" rx="3" fill="var(--surface)" stroke="var(--fg)" stroke-width="2.5"/>'
   +'<path d="M22 36 L70 24 L73 33 L25 45Z" fill="var(--fg)" opacity=".85"/><path d="M32 33 L36 41 M44 30 L48 38 M56 27 L60 35" stroke="var(--surface)" stroke-width="3" stroke-linecap="round"/>'
   +'<path d="M30 52 H66 M30 60 H56" stroke="var(--fg)" stroke-width="1.8" stroke-linecap="round" opacity=".6"/>'
   +'<circle cx="64" cy="62" r="4" fill="color-mix(in oklab,var(--ember) '+Math.round(heat*100)+'%,#dfe4ea)" stroke="var(--fg)" stroke-width="1.5"/></svg>';
}

