var EV16=[
/* ---- Chương 1: Ngày đầu làm vợ (mốc 1–9) ---- */
Q16("x01","vroom","Hứa gia thôn · Phòng cưới nhà họ Hứa","duyen","Sáng đầu tiên làm vợ",
"Tiểu Đào tỉnh dậy trong một căn phòng cưới còn dán chữ hỷ đỏ, trong thân một cô gái hai mươi tuổi. Một quả cầu ngọc xanh nhỏ lơ lửng bên gối: «Ta là Tiểu Châu». Nó giao nhiệm vụ: sống trọn đời cùng Tần Dã và giữ anh khỏi con đường cô độc anh từng đi. Hồ sơ nguyên chủ: Hứa Tiểu Đào, thôn hoa của Hứa gia thôn, được cả nhà cưng như bảo bối. Hôm trước, bờ sông sụt đúng lúc Tần Dã đi qua, rồi Ninh Anh dẫn cô tới vớt anh và gọi cả thôn ra xem, nên hai người phải cưới. Tác giả cuốn truyện bỏ dở ở đó, phần sau cô phải tự đi.",
"Ninh Anh gài bẫy chuyện rơi nước vì sợ ngươi cướp vị hôn phu của nàng. Nhớ cái tên đó. Còn lại, ngươi có một người chồng mặt lạnh.",
"h_dao,h_da,h_anh,tc",[
 K16("Ghi lại từng chi tiết trong hồ sơ để đối chiếu dần","tri",0.560,"Cô ghi đủ tên, ngày và nơi chốn. Đầu óc cô sáng ra, như vừa dọn xong một cái kho.","Cô ghi nhầm thứ tự hai việc, phải xóa đi viết lại mãi mới ổn.",{f:"ghi_ho_so"}),
 K16("Chỉ giữ ý chính, còn lại tính sau","van",0.500,"Cô nhẹ đầu hẳn đi. Có những chuyện để thời gian tự trả lời còn hơn.","Cô quên mất tên một người trong hồ sơ, đến lúc cần phải nhờ Tiểu Châu nhắc.",{}),
 K16("Hỏi Tiểu Châu vì sao Ninh Anh sợ mình đến thế","mi",0.500,"«Cô ta sợ ngươi đẹp, sợ chồng sắp cưới của cô ta nhìn ngươi lâu hơn cần thiết», Tiểu Châu đáp gọn. Cô khẽ gật.","Tiểu Châu lảng sang chuyện khác, chỉ nói «để rồi xem». Cô vẫn chưa hiểu hết.",{})],
{ctx:"Phòng cưới nhà họ Hứa, sáng sau đám cưới vội. Tiểu Đào nhận nhiệm vụ cảm hóa Tần Dã và đọc hồ sơ nguyên chủ."}),

Q16("x02","vkitchen","Hứa gia thôn · Bếp nhà họ Hứa","chon","Hai cái màn thầu trắng",
"Cả nhà đã ra đồng. Trong nồi còn hai cái màn thầu bột trắng mẹ để lại cho cô, và cô ăn ngon lành. Cha mẹ cùng hai anh đều cưng cô, việc nhà cả nhà chia nhau làm. Đi ngang góc phòng, cô để ý chiếc rương gỗ của Tần Dã, dưới đáy có một xấp tài liệu ôn thi đại học chị anh gửi tới. Còn một năm nữa kỳ thi mới được khôi phục, nhưng Tiểu Châu đã cho cô biết điều đó. Cô có thể để yên cái rương, hoặc nói thẳng với anh rằng mình đã biết.",
"Anh giấu cái rương như giấu một cái bóng. Ngươi nhìn thấy thì cũng đừng làm như không thấy.",
"h_dao,h_da,tc",[
 K16("Để yên cái rương, đợi anh tự nói","van",0.520,"Cô khép nắp rương lại như chưa từng mở. Tối đó anh nhìn chiếc rương, rồi nhìn cô, rất lâu.","Cô khép nắp quá mạnh, tiếng gỗ vang lên cả gian bếp. Cô hơi ngượng.",{f:"de_yen_ruong"}),
 K16("Nói thẳng: «Em biết trong rương có gì»","mi",0.480,"Anh sững người, tai đỏ lên, rồi khẽ gật. «Anh biết em sẽ thấy», anh nói rất nhỏ.","Cô nói hơi vội, anh lùi nửa bước như bị bắt quả tang. Phải mất một lúc anh mới mở lời lại.",{f:"noi_thang_ruong"}),
 K16("Lặng lẽ xếp lại cái rương cho gọn, không nói gì","tri",0.500,"Cô xếp xấp tài liệu ngay ngắn, đặt chiếc bút máy lên trên cùng. Anh nhìn là hiểu.","Cô xếp nhầm thứ tự các cuốn sách. Anh phải chỉnh lại, hơi cười.",{})],
{ctx:"Bếp nhà họ Hứa, buổi sáng. Tiểu Đào thấy xấp tài liệu thi đại học dưới đáy rương của Tần Dã."}),

Q16("x03","vroom","Hứa gia thôn · Trưa","chon","Tần Dã trở về",
"Anh làm việc đồng xong thì tắm rửa sạch sẽ mới dám vào phòng. Anh rón rén tới bên giường, kéo chân cô lại trong chăn rồi đỏ tai khi cô mở mắt. Cô nói «chúng ta đã cưới rồi». Anh hứa sẽ chịu trách nhiệm. Cô đòi thêm: phải yêu và thương cô nữa. Anh đáp «vâng» ngay, rồi nói đó là điều hiển nhiên. Trong tay cô còn nửa phần màn thầu chưa ăn.",
"Đừng cười anh. Anh đang cố giữ mặt lạnh mà tai đã đỏ hết.",
"h_dao,h_da,tc",[
 K16("Ôm lấy anh trước, nói «em cảm ơn»","mi",0.520,"Anh đứng cứng người một lúc rồi mới dám đặt tay lên lưng cô. Hơi thở anh chậm lại.","Cô ôm hơi mạnh, anh loạng choạng suýt ngã xuống mép giường. Cả hai cười.",{f:"om_truoc"}),
 K16("Chia nốt phần màn thầu cho anh","van",0.500,"Anh cầm nửa cái màn thầu bằng hai tay, ăn chậm như ăn một món quý.","Cô đưa nhầm phần có vết cắn. Anh vẫn nhận, tai đỏ hơn.",{f:"chia_man_thau"}),
 K16("Hỏi anh: «Anh có hối hận vì chuyện hôm qua không?»","tri",0.480,"«Không», anh đáp ngay, rồi sững lại vì mình trả lời quá nhanh.","Anh im lặng khá lâu. Cô nhận ra mình hỏi sớm quá.",{})],
{ctx:"Nhà họ Hứa, trưa. Tần Dã vừa xong việc đồng, vào phòng với cô."}),

Q16("x04","vroom","Hứa gia thôn · Cùng buổi","chon","Chuyện thi đại học",
"Cô hỏi thẳng anh có muốn thi không, nhà nuôi thêm một người vẫn được. Anh hỏi cô có sợ anh đi rồi không quay lại. Cô đáp: «em đẹp thế này, anh không cần em là tổn thất của anh». Anh im lặng, rồi tự quyết: không thi. Cô nghe ra anh sợ mất cô hơn sợ mất con đường. Cô phải chọn khuyên anh cứ thi, hay ủng hộ quyết định của anh.",
"Anh nghe ra thứ cô muốn nói nhiều hơn thứ cô nói. Chọn từng chữ.",
"h_dao,h_da,tc",[
 K16("Khuyên anh cứ thi, em ở nhà chờ","tri",0.500,"Anh mím môi, bàn tay siết lại trên đầu gối. «Em muốn anh đi sao?», anh hỏi rất khẽ.","Anh nghe thành «em muốn anh đi». Mặt anh lạnh xuống, tai không còn đỏ nữa.",{f:"khuyen_thi",g:[-1,3,2,0],b:[0,4,0,-2]}),
 K16("Ủng hộ anh: «Anh quyết thế nào em theo thế đó»","mi",0.520,"Anh nhìn cô, cuối cùng khẽ cười. «Cảm ơn em đã không đẩy anh đi.»","Câu nói của cô nghe hơi nhạt. Anh gật đầu nhưng vẫn nhìn cô dò xét.",{f:"ung_ho_anh"}),
 K16("Đề nghị cùng ôn thi, ai đỗ thì đỗ, không ép nhau","van",0.480,"Anh bật cười thành tiếng lần đầu tiên. «Cùng ôn thi? Em chịu được không?»","Anh nghĩ cô nói cho vui. Cuộc nói chuyện trôi qua mà chưa ai nói thật lòng.",{f:"cung_on_thi"})],
{ctx:"Phòng cưới, cùng buổi. Tiểu Đào hỏi anh có muốn thi đại học không."}),

Q16("x05","vkitchen","Hứa gia thôn · Bữa trưa cả nhà","chon","Bữa cơm tuyên bố",
"Quanh bàn ăn đông đủ, Tần Dã công bố trước cả nhà rằng anh không thi đại học. Hai anh vợ mừng ra mặt. Cha Hứa Thủ Quốc đập bàn, bảo anh cân nhắc lại, đề nghị anh và cô cùng ôn thi, cả nhà nuôi. Anh nói nhà mình phức tạp, có về cũng chẳng còn chỗ đứng, chi bằng ở lại làm nên chuyện. Mẹ Dư Xuân Lệ vội gắp thức ăn vào bát anh. Cô có thể đỡ lời cho anh, hoặc để anh tự thuyết phục cha.",
"Cha cô là người nóng mà tốt. Ông đập bàn vì thương con rể, không phải vì ghét.",
"h_dao,h_da,h_quoc,h_le,h_ngoc,h_hang,tc",[
 K16("Đỡ lời cho anh: «Cha, anh ấy có kế hoạch riêng»","mi",0.510,"Cha cô nhìn anh rồi nhìn cô, hừ một tiếng và gắp một miếng thịt to vào bát anh.","Cô nói chen giữa câu của anh, cha cô nhíu mày vì tưởng hai đứa đã bàn riêng với nhau.",{f:"do_loi"}),
 K16("Im lặng gắp thức ăn, để anh tự nói","van",0.500,"Anh tự nói hết một hơi. Cha cô nghe xong thì chỉ thở dài: «Thôi, tùy con.»","Anh nói giữa chừng bị cha ngắt. Cả bàn ăn nguội dần trong im lặng.",{f:"de_anh_noi"}),
 K16("Hỏi cha một câu thật lòng: «Cha lo cho anh phải không?»","tri",0.480,"Cha cô khựng lại, giọng dịu xuống. «Phải. Ta lo nó mặc kệ chính mình.»","Câu hỏi làm cha cô ngượng, ông quay sang mắng hai anh vì chuyện khác.",{})],
{ctx:"Bữa trưa cả nhà họ Hứa. Tần Dã tuyên bố không thi đại học."}),

Q16("x06","rforest","Hứa gia thôn · Sườn núi sau thôn","duyen","Lên núi săn và kế hoạch xưởng",
"Chiều đó cô đòi theo xem anh săn, anh nắm tay cô dẫn đi. Anh bắt được một con thỏ và hai con gà rừng, cô đi bên hái rau dại. Trên đường, anh kể kế hoạch: làm xưởng đồ hộp từ sơn trân, bao núi nuôi gà, rồi sửa thôn thành chốn nghỉ ngơi, để sau này nhà nhà ăn thịt hằng ngày. Cô thấy tầm nhìn của anh xa hơn người trong thôn rất nhiều. Cô có thể hỏi thêm chi tiết, hoặc góp một ý của mình.",
"Anh hiếm khi nói dài như vậy. Hỏi hay góp ý, anh đều sẽ nhớ.",
"h_dao,h_da,tc",[
 K16("Hỏi thêm chi tiết: nguồn nguyên liệu, đầu ra, ai làm","tri",0.520,"Anh trả lời từng câu, rồi chợt dừng: «Em hỏi đúng chỗ anh chưa nghĩ tới.» Anh nhìn cô lâu hơn bình thường.","Cô hỏi nhiều quá cùng lúc, anh phải dừng chân ghi nhớ từng câu một.",{f:"hoi_ke_hoach"}),
 K16("Góp một ý: bán thêm quà biếu cho dịp Tết","van",0.480,"Anh đứng khựng giữa đường núi. «Quà biếu... đúng rồi. Sao anh không nghĩ ra.»","Ý của cô hơi sớm, anh gật nhưng chưa thấy khớp với kế hoạch của mình.",{f:"gop_y"}),
 K16("Không nói gì, chỉ hái thêm rau dại và nhìn anh nói","mi",0.500,"Anh tưởng cô không thích. Cô đưa nắm rau cho anh xem, anh bật cười, nói tiếp.","Cô hái nhầm một loại có vị đắng. Anh nhăn mặt rồi vẫn nhận lấy.",{})],
{ctx:"Sườn núi sau thôn, chiều. Tần Dã kể kế hoạch làm xưởng đồ hộp.",learn:{n:"Nhận biết rau dại",s:"van",v:1}}),

Q16("x07","rforest","Hứa gia thôn · Bìa rừng","hiem","Học đặt bẫy",
"Anh dựng một cái bẫy nhỏ ngay bìa rừng. Anh chỉ cô cách tìm dấu chân thú, cách chọn chỗ đặt thòng lọng, và vì sao không được đặt gần lối cô đi để khỏi bị thương. Anh dặn cô đứng ở chỗ an toàn khi anh làm việc. Cô có thể xin tự đặt thử một cái, hoặc đứng xem.",
"Anh dặn thật kỹ. Cô nên nghe, vì thòng lọng không phân biệt người với thỏ.",
"h_dao,h_da,tc",[
 K16("Xin tự đặt thử một cái, nghe theo từng lời anh dặn","tri",0.500,"Cô đặt xong cái bẫy đầu tiên, vụng nhưng đúng. Anh kiểm tra, không sửa chữ nào.","Cô đặt lệch nửa gang, anh phải sửa lại, nắm tay cô kéo ra khỏi vòng thòng lọng.",{f:"dat_bay_dung"}),
 K16("Đứng xem ở chỗ anh dặn, ghi nhớ từng bước","van",0.520,"Cô đứng yên đúng chỗ, nhớ hết từng động tác. Anh liếc nhìn cô, hài lòng.","Cô đứng quá gần, anh phải nhắc hai lần mới chịu lùi.",{f:"dung_xem"}),
 K16("Tự đặt thử một cái, không chờ anh dặn xong","mi",0.470,"Cô đặt đúng chỗ, anh nhìn cô khá lâu mà không nói gì.","Cô sải chân vào vòng thòng lọng, bẫy xiết lại quanh mắt cá chân. Anh lao tới tháo ra, mặt tái đi.",{f:"tu_dat_bay",b:[-1,3,0,-5]})],
{ctx:"Bìa rừng, ngay sau đó. Tần Dã dạy cô đặt bẫy thú nhỏ.",learn:{n:"Đặt bẫy thú nhỏ",s:"van",v:1}}),

Q16("x08","vfield","Hứa gia thôn · Đồng ruộng","chon","Mang nước ra ruộng",
"Mấy ngày sau, cô đem ấm nước mát ra ruộng cho Tần Dã và đứng bên bờ ruộng cả buổi chiều. Anh làm bằng ba người, dân làm cùng ghen tị vì anh có vợ đẹp đứng nhìn. Ninh Anh tìm tới, giọng nhẹ nhàng: «đàn ông muốn chạy thì sẽ tìm cách chạy». Cô đáp anh không thi. Ninh Anh sững lại, ánh mắt thoáng ghen tị. Em gái cô ta Ninh Hiểu Phương đứng xa, lườm. Lúc về, thôn dân trêu anh nên nắm tay cô kẻo cô vấp, anh không dám cãi.",
"Đây là lần đầu ngươi thấy mặt Ninh Anh. Nàng sợ ngươi, mà ngươi chưa biết vì sao nàng sợ.",
"h_dao,h_da,h_anh,h_hphuong,tc",[
 K16("Hỏi ngược Ninh Anh: «Sao cô lo cho tôi thế?»","tri",0.490,"Ninh Anh hơi hoảng, chối rằng chỉ tiện miệng. Cô ghi nhớ nét mặt đó.","Cô hỏi hơi sắc, Ninh Anh cười cười rồi bỏ đi, không để lộ thêm gì.",{f:"hoi_nguoc_anh"}),
 K16("Trả lời gọn, rồi đi tiếp cùng anh","mi",0.520,"Cô quay lưng đi, bàn tay anh ấm hơn bình thường. Ninh Anh đứng lại sau lưng cô.","Câu trả lời cụt quá, Ninh Anh nhìn theo như vừa nhận thêm một chuyện để canh cánh.",{f:"tra_loi_gon"}),
 K16("Nắm tay anh thật chặt, không nhìn Ninh Anh nữa","van",0.500,"Anh siết lại tay cô. Cả thôn thấy, cả thôn cười, và cô không thấy ngượng.","Cô vấp ngay bờ ruộng thật. Anh kịp đỡ, nhưng mặt Ninh Anh đã thoáng hả hê.",{})],
{ctx:"Đồng ruộng Hứa gia thôn, mấy ngày sau. Ninh Anh tìm tới, nhắc khéo chuyện Tần Dã sẽ bỏ đi."}),

Q16("x09","vfield","Hứa gia thôn · Đường về","chon","Lời thề của Tần Dã",
"Trên đường về, cô nói nhỏ rằng Ninh Anh có nhìn anh. Anh giật mình thề rằng anh không hề nhận quà hay quen cô ta, thậm chí không nhớ nổi mặt. Cô nói mình tin anh, nhưng để ý thấy anh phản ứng mạnh vì sợ cô hiểu lầm. Cô có thể trấn an anh, hoặc trêu anh thêm một chút.",
"Anh đang sợ. Chỉ một câu trêu cũng có thể thành vết sâu nếu anh nghe nhầm.",
"h_dao,h_da,tc",[
 K16("Trấn an anh: «Em tin anh. Anh không cần thề.»","tri",0.510,"Anh thở ra, vai chùng xuống. «Em nói vậy anh mới yên tâm.»","Anh vẫn lắc đầu, lặp lại lời thề lần nữa. Cô phải ôm lấy cánh tay anh cho anh dừng.",{f:"tran_an"}),
 K16("Trêu anh: «Nhưng sao anh nhớ rõ là không nhớ mặt?»","mi",0.480,"Anh đỏ bừng mặt, nhìn trời nhìn đất. Cô nghe tiếng anh cười khẽ.","Anh nghe thành nghi ngờ thật. Mặt anh sầm xuống, cô vội nói lại.",{f:"treu_anh",b:[0,3,0,-2]}),
 K16("Nắm tay anh, đi chậm lại để anh nói hết","van",0.500,"Anh nói hết mọi điều, từ lần gặp đầu đến những lần tránh mặt. Tay anh không buông tay cô.","Anh nói được nửa chừng thì có người gọi từ ruộng. Câu chuyện bị cắt ngang.",{})],
{ctx:"Đường về từ ruộng. Tần Dã thề không quen Ninh Anh."}),

/* ---- Chương 2: Xưởng thực phẩm Hứa thị (mốc 10–17) ---- */
Q16("x10","vstudy","Trấn · Văn phòng trấn trưởng","chon","Lên trấn trình kế hoạch",
"Mấy tuần sau, cô, anh và cha cùng lên trấn gặp Lương trấn trưởng. Anh đưa một xấp kế hoạch viết tay; Lương trấn trưởng đọc kỹ, ánh mắt đổi khác nhưng chỉ nói «về chờ tin», vì lập xưởng ở thôn thì tài nguyên cả vùng sẽ nghiêng về đây. Anh nói làm xưởng là vì nước vì dân. Trước khi nộp, cô đã giúp anh chỉnh lại câu chữ trong bản kế hoạch. Giờ cô phải chọn nhấn thêm phần lợi ích cho dân trong vùng, hay phần lợi nhuận của xưởng.",
"Quan trấn nghe lợi cho dân dễ hơn nghe lợi cho xưởng. Nhưng ông cũng không ngốc.",
"h_dao,h_da,h_quoc,h_luong,tc",[
 K16("Nhấn phần lợi ích cho dân: việc làm, thức ăn, trường học","mi",0.520,"Trấn trưởng gật gù, ngón tay gõ khẽ lên bàn. «Nghe có lý.»","Cô nói hơi dài, trấn trưởng nhìn đồng hồ. Anh phải gỡ lại.",{f:"loi_ich_dan"}),
 K16("Nhấn phần lợi nhuận: nộp thuế, nuôi cả trấn","tri",0.480,"Trấn trưởng ngẩng lên, lần đầu hỏi một con số. Anh trả lời không do dự.","Con số cô đưa lệch một chút, anh phải sửa. Trấn trưởng cười nhạt.",{f:"loi_nhuan"}),
 K16("Để anh nói, cô chỉ rót trà và quan sát","van",0.500,"Nhìn cách ông rót trà đáp lễ, cô biết ông đã có ý đồng ý, chỉ chưa nói.","Ấm trà đổ nhẹ ra khay. Ông liếc cô rồi cười, như cười một cô vợ trẻ.",{})],
{ctx:"Văn phòng trấn trưởng, mấy tuần sau. Anh trình kế hoạch xây xưởng đồ hộp.",learn:{n:"Viết đề án xin phép",s:"tri",v:1}}),

Q16("x11","vkitchen","Hứa gia thôn · Tối hôm đó","chon","Đồ hộp làm lén",
"Tối đó, cô phát hiện cả nhà đã nếm đồ hộp anh làm ban đêm lúc cô ngủ. Ai cũng giấu cô để cô bất ngờ. Cô nếm từng món và chấm điểm: món nào quá mặn, món nào hợp làm quà biếu. Anh ngồi bên cạnh ghi chép nghiêm túc từng chữ. Cô có thể nói thẳng cả những món chưa đạt, hoặc chỉ nêu ba món ngon nhất.",
"Anh ghi tất cả những gì cô nói. Cô khen thì anh nhớ, cô chê thì anh sửa.",
"h_dao,h_da,h_le,tc",[
 K16("Nói thẳng cả những món chưa đạt, kèm lý do","tri",0.520,"Anh ghi nhanh, hỏi lại hai chỗ. Hôm sau món đó ngon hẳn lên.","Cô chê gắt quá, anh im lặng một lúc rồi gấp quyển sổ lại.",{f:"che_thang",bonus:sk16("Nhận biết rau dại",.09)}),
 K16("Chỉ nêu ba món ngon nhất, những món còn lại để anh tự thấy","mi",0.480,"Anh nhìn ba món cô chọn, rồi gật. «Anh sẽ làm ba món này thật tốt.»","Anh tưởng cô chê chung cả mẻ. Anh bỏ cả mẻ ra, mất công nửa đêm.",{f:"chi_khen_ba"}),
 K16("Ăn hết phần của mình rồi hỏi anh còn gì muốn nghe","van",0.500,"Anh ngơ ngác rồi bật cười. «Anh muốn nghe em nói còn muốn ăn nữa không.»","Cô ăn nhiều quá, quên mất việc chấm điểm. Anh phải nhắc.",{})],
{ctx:"Nhà họ Hứa, tối hôm đó. Cô nếm đồ hộp đầu tiên của anh.",learn:{n:"Thử vị và chấm điểm",s:"mi",v:1}}),

Q16("x12","vstreet","Trấn · Quán cơm quốc doanh","chon","Gặp nhau ở quán quốc doanh",
"Vài tuần sau, hai người lên trấn ăn ở quán quốc doanh. Cô nhìn sang bàn bên: Ninh Anh ngồi cạnh một quân nhân ít lời, anh Giang Thế Quân, vị hôn phu của cô ta. Tần Dã bẻ mặt cô quay lại: «chỉ nhìn anh». Lúc ra cửa hai bên chạm mặt; Thế Quân thoáng sững khi thấy cô rồi cúi chào Tần Dã, còn Ninh Anh áp sát người anh như giữ của. Tần Dã nắm tay cô chặt hơn, không nói gì. Cô có thể nói thật với anh về chuyện Thế Quân thoáng sững, hoặc bỏ qua.",
"Anh thấy hết, chỉ không nói. Nói thật sớm thì anh đỡ tự nghĩ.",
"h_dao,h_da,h_quan,h_anh,tc",[
 K16("Nói thật với anh: «Anh ấy sững vì chưa quen thấy em»","tri",0.500,"Anh im lặng, rồi gật. «Cảm ơn em đã nói.» Tay anh bớt siết.","Anh nghe xong thì mặt tối lại. Cô nói đúng mà anh vẫn thấy chạnh.",{f:"noi_thang_12"}),
 K16("Bỏ qua, kéo anh đi mua đồ cho mẹ","van",0.520,"Anh để cô kéo đi nhưng cứ ngoái nhìn lại. Ngoài cửa hiệu, anh mới thôi.","Cô kéo hơi gượng. Anh nhìn bóng Thế Quân khuất sau cánh cửa lâu hơn bình thường.",{}),
 K16("Nhìn thẳng Thế Quân, gật đầu chào như người lạ","mi",0.480,"Thế Quân vội lảng đi. Tần Dã nhìn cô, ánh mắt chợt dịu lại.","Cô gật đầu quá lâu, Ninh Anh liếc nhìn. Cô thấy tay anh siết đến trắng cả khớp.",{})],
{ctx:"Quán cơm quốc doanh trên trấn, vài tuần sau. Cô thấy Ninh Anh cùng Giang Thế Quân.",forced:1,fix:w16spikeK("s12","noi_thang_12")}),

Q16("x13","vyard","Hứa gia thôn · Nhà họ Ninh","chon","Ninh Anh gả đi",
"Một tháng sau, Giang Thế Quân về báo cáo kết hôn. Ninh Hiểu Phương nháo đòi gả thay chị, nhà họ Ninh còn xúi giục, nhưng bà Phương Thu Lan, mẹ Thế Quân, chê cô ta ngang ngược. Ninh Anh làm ra vẻ cần mẫn trước mặt mẹ chồng để thắng lòng bà. Rồi Ninh Anh theo chồng vào quân đội, bỏ lại Hiểu Phương và em trai Ninh Thư Bảo ở thôn. Tiểu Đào được mời ra tiễn.",
"Nàng đi rồi. Nhưng cái bẫy ở bờ sông vẫn chưa ai nhắc tới.",
"h_dao,h_anh,h_quan,h_lan,h_hphuong,h_bao,tc",[
 K16("Tiễn bằng một lời tử tế: «Chúc cô sống tốt»","mi",0.510,"Ninh Anh sững người, nụ cười méo đi. Cô ta quay lưng nhanh hơn dự tính.","Lời của cô nghe như thương hại. Ninh Anh trừng mắt, lên xe không nói tiếng nào.",{f:"tien_tu_te"}),
 K16("Không nói gì, chỉ đứng nhìn xe rời thôn","van",0.500,"Bụi đường lắng xuống. Cô thấy mình nhẹ đi một chút.","Cô đứng quá gần, bụi bay vào mắt. Anh vội lấy khăn lau cho cô.",{}),
 K16("Quan sát Ninh Hiểu Phương và Ninh Thư Bảo lúc tiễn","tri",0.490,"Cô thấy Thư Bảo cúi gằm mặt, tay nắm chặt vạt áo. Cậu bé như đang giấu điều gì.","Cô nhìn nhầm hướng, bỏ lỡ nét mặt của Thư Bảo.",{f:"nhin_thu_bao"})],
{ctx:"Hứa gia thôn, một tháng sau. Ninh Anh theo chồng vào quân đội."}),

Q16("x14","jfactory","Hứa gia thôn · Bãi đất ngoài thôn","duyen","Xưởng thực phẩm Hứa thị",
"Vài tháng sau, giấy phép được duyệt. Tần Dã chọn dựng xưởng ngoài thôn để tránh rác và tiếng ồn, và thuyết phục được cha cô. Thôn dân từ chê bai chuyển sang xin làm công nhật vì được chia đồ ăn. Xưởng lấy tên Hứa thị, ký hiệu một chữ «Đường», anh nói vì cô cười ngọt hơn đường. Cô theo thợ cả học quy trình nấu và đóng hộp. Cô phải chọn học kỹ khâu tiệt trùng, hoặc khâu đóng gói.",
"Một xưởng nhỏ vài gian nhà, mà ai cũng nhìn vào. Học cho thật, đừng học cho đẹp.",
"h_dao,h_da,h_quoc,tc",[
 K16("Học kỹ khâu tiệt trùng, nơi dễ sai nhất","tri",0.520,"Cô học thuộc nhiệt độ, thời gian, cách thử kín. Thợ cả gật đầu lần đầu tiên.","Cô nhớ nhầm một con số, may thợ cả kịp sửa trước khi nấu mẻ đầu.",{f:"hoc_tiet_trung",bonus:sk16("Thử vị và chấm điểm",.09)}),
 K16("Học khâu đóng gói, nơi khách nhìn thấy đầu tiên","mi",0.490,"Cô chọn được kiểu nhãn giản dị mà đẹp. Anh nhìn nhãn rất lâu rồi nói: «Giữ nguyên.»","Mẻ nhãn đầu bị lệch, phải in lại. Cô ngượng, anh chỉ cười.",{f:"hoc_dong_goi"}),
 K16("Học cả hai, mỗi buổi một khâu, chấp nhận chậm hơn","van",0.470,"Đến cuối tháng, thợ cả để cô đứng quản cả hai khâu.","Cô mệt nên học dở cả hai. Thợ cả thở dài, bảo học lại từ đầu.",{})],
{ctx:"Bãi đất ngoài thôn, vài tháng sau. Xưởng Hứa thị bắt đầu có nhà.",learn:{n:"Làm đồ hộp",s:"van",v:2}}),

Q16("x15","vkitchen","Hứa gia thôn · Bữa cơm gia đình","chon","Mẹ giục sinh",
"Ba năm sau khi cưới, xưởng đã vào quỹ đạo. Trong bữa cơm, mẹ Dư Xuân Lệ hỏi sao chưa có con, vì sợ không có con thì chồng sẽ đổi lòng. Cô nhìn anh, anh nhìn lại; hai người mải nhìn nhau đến nỗi mẹ bỏ cuộc. Cô có thể nói nhẹ với mẹ, hoặc để mẹ tự bớt lo.",
"Mẹ cô lo nhiều hơn nói. Một câu nhẹ có thể đỡ hơn mười câu cãi.",
"h_dao,h_da,h_le,tc",[
 K16("Nói nhẹ với mẹ: «Con với anh ấy tự biết, mẹ đừng lo»","mi",0.520,"Mẹ gật gù, gắp thêm miếng cá vào bát cô. «Thôi mẹ không hỏi nữa.»","Mẹ lại thở dài, nhưng vẫn gắp thêm cá cho cô.",{f:"noi_nhe_me"}),
 K16("Để mẹ tự bớt lo, cô chỉ cười","van",0.500,"Mẹ nhìn nụ cười của cô rồi đổi chuyện sang xưởng.","Mẹ tưởng cô né tránh, lát sau còn nói với bố.",{}),
 K16("Hứa với mẹ: «Chờ xưởng ổn định rồi tính»","tri",0.480,"Mẹ nghe có hẹn thì yên tâm, nhưng anh thì nhìn cô lâu hơn.","Mẹ nhớ kỹ lời hẹn ấy, lúc nào cũng nhắc lại.",{f:"hua_me"})],
{ctx:"Bữa cơm gia đình, ba năm sau khi cưới. Mẹ giục có con."}),

Q16("x16","vroom","Hứa gia thôn · Tối cùng ngày","chon","Chuyện không có con",
"Tối đó anh bưng nước ngâm chân cho cô. Cô hỏi anh có muốn có con không, nếu cả đời không có thì anh có tiếc. Anh hoảng, tưởng cô bệnh, đòi đi bệnh viện. Cô nói thân thể mình bình thường nhưng hai người sẽ không có con. Anh đáp «anh chỉ cần em», rồi thú nhận anh không chịu nổi việc ánh mắt cô chia cho người khác, dù là con mình. Cô phải chọn: nói thẳng rằng chính cô cũng không muốn có con, hoặc chỉ nói «sẽ không có» mà không giải thích.",
"Đừng thử lòng anh. Anh dễ vỡ ở đúng chỗ người khác nghĩ là chắc.",
"h_dao,h_da,tc",[
 K16("Nói thẳng: «Em cũng không muốn có con, em chỉ cần anh»","tri",0.510,"Anh ôm cô thật chặt, đặt môi lên trán cô. «Vậy là đủ rồi.»","Cô nói vụng, anh ngơ ngác hỏi lại ba lần mới hiểu.",{f:"noi_thang_con"}),
 K16("Chỉ nói «sẽ không có», rồi để anh tự hiểu","van",0.500,"Anh im lặng rất lâu rồi nắm tay cô. «Anh hiểu. Anh không hỏi nữa.»","Anh hiểu nhầm là cô giấu bệnh. Phải giải thích lại cả đêm.",{}),
 K16("Hỏi lại: «Nếu anh đổi ý, em hiểu. Còn kịp mà.»","mi",0.490,"Anh nhìn cô, mắt đỏ lên. «Em thử anh sao? Anh không đổi.»","Câu hỏi làm anh tối mặt. Anh đặt chậu nước xuống, quay đi không nói nữa.",{f:"thu_long_16",g:[-1,4,2,0],b:[0,5,0,-2]})],
{ctx:"Phòng họ, tối cùng ngày. Hai người nói chuyện về chuyện con cái."}),

Q16("x17","school","Hứa gia thôn · Họp thôn","duyen","Trường học và lớp xóa mù",
"Vài tháng sau, họp thôn, Tần Dã phát biểu trước dân làng. Anh đề nghị dựng trường tiểu học và lớp mẫu giáo trong thôn, miễn phí cho con em dân và công nhân xưởng; trước đây nhiều nhà không cho con gái đi học. Thêm một lớp buổi tối cho người lớn, nơi phụ nữ chen nhau đăng ký. Cô được giao soạn chương trình: học viết tên, tính sổ, đọc hợp đồng. Cô có thể tập trung dạy chữ cho phụ nữ, hoặc dạy tính sổ cho những người trông xưởng.",
"Có người cầm bút lần đầu ở tuổi bốn mươi. Đừng làm họ ngại.",
"h_dao,h_da,tc",[
 K16("Tập trung dạy chữ cho phụ nữ, bắt đầu bằng viết tên mình","mi",0.520,"Một bà cụ viết xong tên mình, nhìn rất lâu rồi khóc. Cô thấy ấm cả người.","Cô dạy nhanh quá, nhiều người nản. Cô phải chia lớp nhỏ hơn.",{f:"day_chu",bonus:sk16("Viết đề án xin phép",.09)}),
 K16("Dạy tính sổ cho người trông xưởng, để không bị lừa","tri",0.490,"Một tuần sau, người trông kho báo ra lỗi sổ cũ. Cả xưởng nhìn cô khác đi.","Bài tính khó quá, hai người bỏ lớp. Cô chấn chỉnh lại giáo án.",{f:"day_tinh_so"}),
 K16("Chia lớp: tối đầu tuần dạy chữ, cuối tuần dạy tính","van",0.480,"Lớp học đông đủ. Cô quen mặt hết từng người.","Cô lên lịch chồng chéo hai buổi. Phải lên lại từ đầu.",{})],
{ctx:"Họp thôn, vài tháng sau. Tần Dã đề nghị lập trường và lớp xóa mù.",learn:{n:"Soạn giáo án lớp xóa mù",s:"tri",v:2}}),

/* ---- Chương 3: Từ thôn thành huyện (mốc 18–24) ---- */
Q16("x18","school","Hứa gia thôn · Trường tạm ở ký túc xá","chon","Thầy cô trở về",
"Ít lâu sau, trường học tạm đặt trong ký túc xá của xưởng. Những thanh niên trí thức từng đỗ đại học trở về dạy; họ ngỡ ngàng thấy Hứa gia thôn sạch sẽ, nhà đẹp, đường phẳng. Tần Dã ký hợp đồng và cấp nhà, hộ khẩu cho ai ở lại. Cô tiếp một nữ sinh viên dịu dàng sẽ làm cô giáo mẫu giáo. Cô có thể tự gặp từng người, hoặc để anh lo hợp đồng còn mình lo chuyện giảng dạy.",
"Người đến vì nhà, ở lại vì lớp. Gặp từng người thì họ nhớ, mà cô cũng nhớ họ.",
"h_dao,h_da,tc",[
 K16("Tự gặp từng người, hỏi họ muốn dạy gì","mi",0.510,"Hầu hết đều ở lại. Cô thuộc tên từng người trước khi họ nhận phòng.","Cô gặp quá nhiều người trong một ngày, đến tối giọng đã khàn.",{f:"gap_tung_nguoi"}),
 K16("Để anh lo hợp đồng, mình lo giáo án và lịch dạy","tri",0.500,"Anh lo hợp đồng chặt chẽ, cô lo lịch dạy trơn tru. Hai việc khớp nhau.","Lịch dạy và hợp đồng lệch hai tuần. Hai người cùng ngồi sửa.",{f:"chia_viec"}),
 K16("Mời cô giáo mẫu giáo uống trà, nghe cô kể mong muốn","van",0.490,"Cô gái dịu dàng kể về những đứa trẻ mình định dạy. Cô viết lại hết.","Cô gái ngại ngùng, chỉ nói vài câu rồi xin phép về.",{})],
{ctx:"Trường tạm trong ký túc xá, ít lâu sau. Những thanh niên trí thức từng đỗ đại học trở về dạy."}),

Q16("x19","vstudy","Hứa gia thôn · Thư phòng","duyen","Bản vẽ thành phố",
"Tối đó, ở thư phòng trong nhà, cô đưa anh một xấp bản vẽ: toàn cảnh khu dân cư, thương mại, đường phố, mảng xanh, trường học. Anh ngỡ ngàng rồi ôm cô, nói «em là báu vật». Anh vẫn chưa biết phải mở rộng thôn ra sao; bản vẽ giải được nút thắt đó. Cô có thể giải thích từng chi tiết, hoặc để anh tự hiểu.",
"Anh tìm một chỗ để đặt câu hỏi, mà ngươi đã vẽ sẵn câu trả lời.",
"h_dao,h_da,tc",[
 K16("Giải thích từng chi tiết: vì sao đường rộng, vì sao trường ở giữa","tri",0.520,"Anh ghi chép ngày càng nhanh. Đến cuối, anh chỉ còn nhìn cô.","Cô nói quá nhiều chi tiết, anh nhíu mày rồi xin giải thích lại phần đầu.",{f:"giai_thich_ban_ve"}),
 K16("Để anh tự nhìn, chỉ đặt cho anh một cốc nước","van",0.490,"Anh nhìn tới lúc nước nguội. Rồi anh nói: «Anh hiểu rồi, em thật giỏi.»","Anh nhìn bản vẽ mà không hiểu hết. Cô phải ngồi giải thích lại.",{}),
 K16("Hỏi anh muốn đổi chỗ nào, để bản vẽ là của hai người","mi",0.500,"Anh đổi một đường nhỏ, nét chữ của cô và nét chữ của anh nằm chung trên một tờ giấy.","Anh đòi đổi quá nhiều chỗ, cô phải vẽ lại gần nửa bản.",{f:"ban_ve_cua_hai"})],
{ctx:"Thư phòng trong nhà, buổi tối. Cô đưa anh bản vẽ quy hoạch.",learn:{n:"Vẽ bản đồ quy hoạch",s:"tri",v:2}}),

Q16("x20","vfarm","Hứa gia thôn · Khu mới","duyen","Thôn lớn thành huyện",
"Hai năm sau, Hứa gia thôn nhà lầu mọc lên, người đổ về làm việc. Lương trấn trưởng thăng thị trưởng, thôn thành huyện Hứa, cha cô làm huyện trưởng, anh cả làm trấn trưởng. Dân vẫn gọi chỗ cũ là Hứa gia thôn. Quanh núi, người ta nuôi gà, trồng cây ăn quả, mở khu nghỉ ngơi. Cô có thể đi xem công trình một mình, hoặc đi cùng anh.",
"Từ một thôn nghèo thành một huyện. Hai người làm nên, và chưa từng nghĩ mình làm nên.",
"h_dao,h_da,h_quoc,h_ngoc,tc",[
 K16("Đi một mình, nhìn công trình bằng mắt của người dân","tri",0.500,"Cô đi hết một vòng, ghi lại ba chỗ cần sửa. Người dân kể thật vì không biết cô là ai.","Cô bị nhận ra giữa chừng, người dân đổi giọng khách sáo.",{f:"di_mot_minh",bonus:sk16("Làm đồ hộp",.09)}),
 K16("Đi cùng anh, nắm tay đi hết khu mới","mi",0.510,"Hai người nắm tay đi qua các dãy nhà. Ai gặp cũng chào, mà cô chỉ nhìn tay mình trong tay anh.","Hai người bị vây lại chào hỏi, đi một đoạn mất cả buổi chiều.",{f:"di_cung_anh"}),
 K16("Rủ cha đi cùng, để ông tự thấy công của con rể","van",0.490,"Cha cô đi sau hai người, miệng không nói mà mắt cứ ngước nhìn các tòa nhà.","Cha cô than đau chân, cả ba phải quay về sớm.",{})],
{ctx:"Hứa gia thôn, hai năm sau. Thôn thành huyện Hứa."}),

Q16("x21","vstreet","Huyện Hứa · Chợ","chon","Lời đồn ngoài chợ",
"Một dịp mẹ cô gặp các bà trong huyện, mẹ nghe nói vợ chồng cô không con thì chồng chắc sẽ đổi lòng. Cung Ngọc Trân, mẹ của Ninh Anh, còn chủ động nhắc chuyện này. Ninh Hiểu Phương hỏi thăm Tần Dã khắp nơi. Mẹ về nhà, lo đến mất ngủ. Cô trấn an mẹ: ai dám đến, cô sẽ cho họ một bài học nhớ cả đời. Giờ cô phải chọn hỏi mẹ ai nói gì để biết nguồn, hoặc bảo mẹ đừng đến những buổi trò chuyện đó.",
"Lời đồn không đáng sợ khi biết nó từ đâu ra. Mẹ cô mới là người cần được an ủi.",
"h_dao,h_le,h_tran,h_hphuong,tc",[
 K16("Hỏi mẹ ai nói gì, ghi lại từng người để biết nguồn","tri",0.510,"Mẹ kể hết. Cô gạch được hai cái tên, đúng như cô đoán.","Mẹ kể lộn xộn, cô ghi vào sổ mà không chắc cái nào đúng.",{f:"hoi_nguon"}),
 K16("Bảo mẹ đừng đến những buổi đó, cô sẽ đưa mẹ đi chỗ khác","mi",0.500,"Mẹ gật, mắt hoe đỏ. Hôm sau cô đưa mẹ đi xem phố mới. Mẹ cười suốt đường.","Mẹ cãi lại, bảo mẹ không thể sống cô lập. Hai mẹ con ngồi đến khuya.",{f:"dua_me_di"}),
 K16("Kể cho anh nghe, nhờ anh đưa ra cách xử lý chung","van",0.490,"Anh nghe xong, chỉ nói: «Anh sẽ lo.» Chiều hôm sau, lời đồn lặng hẳn.","Anh nghe xong thì lạnh mặt, cô phải ngăn anh khỏi làm quá.",{})],
{ctx:"Chợ huyện Hứa. Lời đồn về chuyện vợ chồng cô không có con."}),

Q16("x22","vstreet","Huyện Hứa · Phòng khách nhà cô","hiem","Hiểu Phương tìm tới cửa",
"Hôm sau, Ninh Hiểu Phương trang điểm lòe loẹt, xin gặp «tỷ phu» có chuyện quan trọng và muốn nói riêng. Cô từ chối, nói mình nhỏ mọn, rồi bảo cô ta thu cái tâm tư kia lại kẻo không còn đường sống ở huyện Hứa. Hiểu Phương lạnh gáy, bỏ chạy. Tối đó Tần Dã nghe kể, thề trong lòng chỉ có mình cô. Cô có thể nói thẳng như vậy, hoặc chờ cô ta tự lộ ra, giăng một cái bẫy lời.",
"Nàng không đáng sợ bằng cái nàng sẽ làm khi bị dồn. Đừng chờ lâu quá.",
"h_dao,h_da,h_hphuong,tc",[
 K16("Nói thẳng, để cô ta biết đường mà tự rút","mi",0.510,"Hiểu Phương tái mặt, chạy mất. Từ hôm đó không ai thấy cô ta tới phòng khách nhà họ Tần nữa.","Hiểu Phương cười khẩy, hỏi cô lấy tư cách gì. Cô phải đáp lại hai câu nữa.",{f:"noi_thang_hp"}),
 K16("Chờ cô ta tự lộ, giăng một cái bẫy lời để thử","van",0.470,"Cô buông một câu nhỏ. Hiểu Phương cắn câu, thú nhận hết tâm tư rồi tự bỏ chạy.","Hiểu Phương nhanh hơn cô nghĩ, gài ngược một câu khiến chén trà đổ vỡ. Cô bị nước nóng bắn vào tay.",{f:"cho_hp",bonus:sk16("Đặt bẫy thú nhỏ",.09),b:[-1,1,0,-3]}),
 K16("Nhờ anh trai, trấn trưởng Hứa Thiên Ngọc, đứng ra nói giùm","tri",0.490,"Anh cả chỉ nói vài câu chững chạc. Hiểu Phương nghe xong, mặt cắt không còn giọt máu.","Anh cả nói hơi nặng lời, người trong huyện bàn tán vài ngày.",{})],
{ctx:"Phòng khách nhà cô ở huyện Hứa, hôm sau. Ninh Hiểu Phương xin gặp Tần Dã."}),

Q16("x23","vyard","Huyện Hứa · Sân sau","chon","Anh có muốn về kinh?",
"Một tối ngoài sân, cô nhận ra mấy năm nay anh chỉ thư từ với chị mà không liên lạc nơi khác. Anh nói chị sắp cưới, anh muốn về nhưng lo cô bị lời lẽ nhà họ Tần làm đau. Cả nhà họ Hứa dặn anh phải bảo vệ cô, thậm chí cháu trai năm tuổi Hứa Nhạc Nhạc nghiêm túc đòi quyết đấu nếu cô bị ủy khuất. Cô có thể đi cùng anh với nhóm kỹ thuật viên của xưởng, hoặc chỉ hai người.",
"Về nhà đối với anh là đi vào chỗ có vết. Anh muốn đi vì chị, không phải vì họ.",
"h_dao,h_da,h_nhac,tc",[
 K16("Đi cùng nhóm kỹ thuật viên chăn nuôi, trồng trọt","tri",0.500,"Anh gật. Có người cùng đi khiến anh dễ thở hơn. Nhóm kỹ thuật viên háo hức như đi hội.","Nhóm đông nên lịch trình rối, anh phải họp thêm ba buổi.",{f:"di_nhom"}),
 K16("Đi hai người thôi, có gì thì cùng đối mặt","mi",0.510,"Anh nhìn cô, nói khẽ: «Anh sẽ không để em đứng một mình.»","Anh lo cho cô nhiều đến mức quên cả việc chuẩn bị đồ cho mình.",{f:"di_hai_nguoi"}),
 K16("Cười: «Nhạc Nhạc sẽ giúp anh đấy», rồi hứa mang quà về","van",0.490,"Anh bật cười, nỗi lo vơi đi một nửa. Nhạc Nhạc khoái chí.","Nhạc Nhạc tưởng đi thật, khóc đòi đi cùng. Cả nhà dỗ mãi.",{})],
{ctx:"Sân sau nhà ở huyện Hứa, buổi tối. Hai người bàn chuyện về kinh thành."}),

Q16("x24","jcity","Kinh thành · Khách sạn nhỏ và biệt thự","duyen","Kinh thành và chị Tần Thanh",
"Ngày hôm sau cả nhóm tới thủ đô. Các kỹ thuật viên hơi thất vọng vì thủ đô không bằng huyện Hứa. Chị Tần Thanh và anh rể Dương Phàm, giáo sư đại học, ra đón; chị ôm em khóc, cảm ơn cô đã cho em trai một mái nhà. Chị làm bất động sản, hai chị em từng trao đổi trong thư. Anh nói muốn huyện Hứa thành thành phố Hứa. Cô có thể hỏi chị về chuyện nhà anh, hoặc để hai chị em nói chuyện riêng.",
"Chị là người nhà duy nhất anh còn tin. Đối xử tốt với chị, anh sẽ nhớ cả đời.",
"h_dao,h_da,h_thanh,h_pham,tc",[
 K16("Hỏi chị về chuyện nhà anh, để biết trước người mình sẽ gặp","tri",0.500,"Chị kể từng người, từng tính nết. Cô ghi nhớ hết, và chị nhìn cô bằng vẻ mến thật lòng.","Chị ngập ngừng, chỉ nói vài câu rồi đổi chuyện. Cô nhận ra chuyện còn nặng hơn tưởng.",{f:"hoi_chi_nha_tan"}),
 K16("Để hai chị em nói chuyện riêng, cô đi dạo với anh rể","mi",0.510,"Anh rể kể chuyện ngành đại học, cô ghi nhớ làm vốn cho trường sau này.","Cô lỡ lời hỏi nhầm chuyện học thuật, anh rể cười hiền nhưng giảng cả tiếng.",{f:"de_chi_em_rieng"}),
 K16("Tặng chị một hộp đồ hộp của xưởng, kể chuyện từng mẻ","van",0.490,"Chị nếm một miếng rồi lặng đi. «Em chồng em là người có bàn tay thật khéo.»","Hộp bị móp một góc khi vận chuyển, cô ngượng, chị lại cười dỗ.",{})],
{ctx:"Khách sạn nhỏ và biệt thự của chị ở thủ đô. Cô gặp chị Tần Thanh và anh rể Dương Phàm."}),

/* ---- Chương 4: Kinh thành (mốc 25–29) ---- */
Q16("x25","vmansion","Kinh thành · Tứ hợp viện của Văn lão","duyen","Gặp ông ngoại Văn lão",
"Hôm sau, anh dắt cô tới tứ hợp viện của Văn lão, ông ngoại anh. Ông khỏe mạnh, nhận ra cháu sau nhiều năm, tay run khi nắm tay anh. Ông kéo cô vào thư phòng xem đồ sưu tầm, rồi hợp chuyện với cô về thư họa. Ông từ chối về huyện Hứa vì ở lại thủ đô còn giúp được các cháu. Cô có thể khen một món đồ trong thư phòng, hoặc hỏi về bức tranh ông đang vẽ.",
"Ông là người đọc sách. Khen thật hay hỏi thật, ông đều nghe ra.",
"h_dao,h_da,h_van,tc",[
 K16("Khen một món đồ trong thư phòng, nói vì sao cô thích","mi",0.510,"Ông cười, nhấc món đó đặt vào tay cô. «Cháu có mắt. Món này ta giữ bốn mươi năm.»","Cô khen món đồ giả mà không biết. Ông chỉ cười hiền, không nói gì.",{f:"khen_do"}),
 K16("Hỏi về bức tranh dang dở trên bàn, xin ông cho xem nét cuối","tri",0.490,"Ông đưa cô cây bút. «Cháu thử đi.» Cô vẽ một nét nhỏ, ông gật đầu không nói.","Cô hỏi quá sâu về kỹ thuật, ông đáp qua loa rồi đổi sang chuyện khác.",{f:"hoi_tranh"}),
 K16("Mài mực cho ông, ngồi yên nghe ông kể về mẹ của anh","van",0.500,"Ông kể về con gái ông, mẹ của Tần Dã. Cô nghe mà thấy tim mình nặng đi.","Mực mài đặc quá, ông phải ngưng viết để mài lại. Cô ngượng.",{f:"mai_muc"})],
{ctx:"Tứ hợp viện của Văn lão, hôm sau. Anh dắt cô tới giới thiệu."}),

Q16("x26","ywed","Kinh thành · Lễ đường","nan","Hôn lễ của chị và nhà họ Tần",
"Ngày cưới của chị, Tần Dã chỉ cho cô từng người nhà họ Tần ngồi hàng ghế: cha Tần Quốc Vinh, mẹ kế Triệu Nhã Phượng, hai cụ nội, em trai Tần Duệ và em gái Tần Huyên. Cha anh không nhận ra anh; hai cụ nhìn cô với vẻ nghi ngờ. Sau lễ, họ vây hai người, hỏi cưới bao lâu và sao chưa có con. Anh đáp «bảy năm», không khí cứng lại. Cô có thể im lặng quan sát, hoặc lên tiếng ngay.",
"Anh đứng như đứng trước một bức tường cũ. Cô nắm tay anh, đừng buông.",
"h_dao,h_da,h_vinh,h_phuong,h_due,h_huyen,tc",[
 K16("Im lặng quan sát, nắm chặt tay anh","tri",0.500,"Cô nhìn rõ ánh mắt từng người. Tay anh nóng hơn tay cô.","Cô bị hỏi dồn, im quá lâu nên Tần Huyên chen vào trước.",{f:"quan_sat_26"}),
 K16("Lên tiếng ngay: «Cưới bảy năm, chúng tôi sống rất tốt»","mi",0.490,"Câu nói của cô làm hai cụ ngừng lại. Anh liếc cô một cái, khóe môi cong lên.","Giọng cô cao quá, Triệu Nhã Phượng liền nhếch mép như tìm được sơ hở.",{f:"len_tieng_26"}),
 K16("Kéo anh lùi một bước, cùng chào chị rồi xin phép ra ngoài","van",0.510,"Hai người rời khỏi vòng vây êm xuôi. Chị Tần Thanh đã đứng chờ ngoài cửa.","Họ không để hai người đi. Một cụ chặn lại, hỏi thêm ba câu.",{})],
{ctx:"Lễ đường kinh thành, ngày cưới của chị. Tần Dã chỉ cho cô từng người nhà họ Tần."}),

Q16("x27","ywed","Kinh thành · Sảnh sau lễ đường","nan","Họ đổ lỗi cho cô",
"Ngay sau đó, ở sảnh sau, hai cụ ám chỉ cô không sinh được, khuyên anh ly hôn để họ giới thiệu cô gái khác; Tần Huyên chen vào bảo cô nên đi khám. Anh lạnh mặt nhận «không con là lỗi của anh», rồi nói nếu họ còn đổ cho cô, anh sẽ kiện tội trùng hôn năm xưa, hai luật sư bạn anh đang chờ vụ đầu tay. Tay anh siết chặt tay cô. Cô có thể để anh nói một mình, hoặc đứng cạnh anh trả lời một câu.",
"Anh nhận lỗi để bảo vệ cô, nhưng anh sẽ không bao giờ nhận lỗi vì chính mình. Đứng cạnh anh là cách đền đáp tốt nhất.",
"h_dao,h_da,h_vinh,h_phuong,h_huyen,tc",[
 K16("Đứng cạnh anh, trả lời bằng một câu rõ ràng và bình tĩnh","mi",0.480,"Cô nói một câu ngắn. Hai cụ không ngờ được một cô vợ quê lại nói thế. Tần Huyên cúi mặt.","Cô nói run nhẹ, hai cụ nhận ra liền. Anh phải nói thêm hộ.",{f:"dung_canh_27"}),
 K16("Để anh nói một mình, cô chỉ giữ tay anh","van",0.510,"Anh nói hết điều muốn nói. Khi anh dừng, cô cảm thấy tay anh đã bớt run.","Anh nói quá lâu, hai cụ cãi lại. Cô nghe giọng anh khàn dần.",{f:"de_anh_noi_27"}),
 K16("Hỏi lại Tần Huyên: «Cô lo cho tôi, hay tò mò chuyện nhà người ta?»","tri",0.470,"Tần Huyên đỏ mặt. Hai cụ ngập ngừng, không ai đáp lại.","Câu hỏi nghe như khiêu khích, hai cụ cau mày rồi đòi nói chuyện với anh riêng.",{f:"hoi_huyen",g:[-1,2,2,0],b:[0,3,0,-2]})],
{ctx:"Sảnh sau lễ đường, ngay sau đó. Hai cụ đổ lỗi cho cô."}),

Q16("x28","vmansion","Kinh thành · Biệt thự của chị","chon","Kế hoạch đáp trả nhà họ Tần",
"Tối đó ở biệt thự của chị, anh kể cho cô nghe: mẹ anh bị làm cho uất ức đến mất, cha, mẹ kế và hai cụ đều có phần, anh không tha. Anh định kéo Tần Duệ và Tần Huyên rời cơ quan nhà nước ra buôn bán, để những người từng chịu thiệt từ nhà họ Triệu tự nhiên đối đầu với họ. Anh hỏi cô có sợ anh không. Cô đáp «không» và thấy hợp ý. Giờ cô phải chọn: khuyên anh dừng ở mức để họ tự bại, hay đồng ý đi tới cùng.",
"Đây là lúc anh nghe cô nhất. Khuyên đúng, anh dừng lại. Khuyên sai, anh sẽ không dừng.",
"h_dao,h_da,h_thanh,tc",[
 K16("Khuyên anh dừng ở mức để họ tự bại, đừng đẩy tới cùng","tri",0.490,"Anh im lặng lâu rồi gật. «Em nói đúng. Anh không muốn thành người giống họ.»","Anh nghe cô nói nhưng không đáp. Cô biết anh đang cân nhắc, chưa bỏ.",{f:"khuyen_dung",g:[-1,-2,3,0],b:[0,1,0,-2]}),
 K16("Đồng ý đi tới cùng: «Họ đáng phải trả giá»","mi",0.510,"Anh nhìn cô, ánh mắt lạnh đi một chút. «Em thật sự nghĩ vậy?»","Cô nói quá hăng, anh ngạc nhiên rồi nhìn cô lâu, như lần đầu thấy một khía cạnh khác.",{f:"di_toi_cung",g:[-1,6,2,0],b:[0,7,0,-2]}),
 K16("Hỏi anh muốn gì nhất: họ ngã, hay mình yên","van",0.500,"Anh lặng đi. «Anh chưa từng nghĩ như thế.» Lần đầu cô thấy anh bối rối.","Câu hỏi làm anh bực. «Em hỏi vậy làm gì?» Cô phải nói lại cho mềm.",{f:"hoi_anh_muon_gi"})],
{ctx:"Biệt thự của chị ở thủ đô, buổi tối. Anh kể kế hoạch đáp trả nhà họ Tần."}),

Q16("x29","road","Kinh thành · Ga tàu","duyen","Rời kinh thành",
"Mấy ngày sau, anh mở chi nhánh Hứa thị ở thủ đô giao cho anh hai Hứa Thiên Hàng. Nhà họ Tần nghe nói Tần Dã nay giàu có nhưng sợ lời anh dọa nên không dám đến gần. Hai vợ chồng ra ga về huyện Hứa; ở đó họ nghe tin Tần gia đã bị hấp dẫn xuống biển buôn bán. Cô có thể hỏi anh về kế hoạch cho Văn lão, hoặc về chuyện nhà họ Tần.",
"Hai chuyện đều là tâm sự. Hỏi chuyện nào, anh cũng kể.",
"h_dao,h_da,h_hang,h_van,tc",[
 K16("Hỏi kế hoạch đón Văn lão về ở lâu dài cùng hai người","mi",0.510,"Anh sáng mắt lên. «Anh định thế, nhưng chưa dám nói với em.»","Anh nói ông đã từ chối, nhưng vẫn nghe cô hỏi. Hai người ngồi lặng suốt đoạn đường.",{f:"hoi_van_lao"}),
 K16("Hỏi chuyện nhà họ Tần: anh còn muốn gì ở họ không","tri",0.490,"Anh lắc đầu. «Anh chỉ muốn họ đừng làm khó em nữa.»","Anh im lặng suốt chặng đầu. Mãi về gần tới huyện mới nói vài câu.",{f:"hoi_nha_tan"}),
 K16("Ngả đầu vào vai anh, không hỏi gì","van",0.500,"Anh để cô ngả, tàu đưa hai người về, ngoài cửa sổ là đồng lúa đang chín.","Tàu xóc mạnh, cô giật mình. Anh bật cười, kéo cô vào lòng.",{})],
{ctx:"Ga tàu thủ đô, mấy ngày sau. Hai người về huyện Hứa."}),

/* ---- Chương 5: Ninh Anh trở về (mốc 30–36) ---- */
Q16("x30","vstreet","Huyện Hứa · Văn phòng huyện","chon","Tin Giang Thế Quân chuyển ngành",
"Cùng ngày về tới huyện, Tiểu Châu báo: Giang Thế Quân xin chuyển ngành, sẽ đưa Ninh Anh và hai con về; nhà họ Giang ở huyện bên đang chạy việc. Cô đoán Ninh Anh sẽ tức vì không làm được phu nhân đoàn trưởng và khó chịu khi thấy huyện Hứa phồn hoa. Tần Dã nói muốn giúp Thế Quân vì là đồng hương. Cô đồng ý, nhưng có tính toán riêng. Cô có thể để anh giúp trọn gói, hoặc chỉ giúp vừa đủ.",
"Giúp trọn gói là tốt bụng; giúp vừa đủ là khôn ngoan. Cả hai đều đúng, mà chỉ một cái an toàn.",
"h_dao,h_da,h_quan,h_anh,tc",[
 K16("Để anh giúp trọn gói: tìm việc, nhà và trường cho hai đứa nhỏ","mi",0.490,"Thế Quân sẽ biết ơn lâu dài. Anh vui vì giúp được đồng hương, cô cũng thấy lòng nhẹ.","Việc giúp quá nhiều khiến Ninh Anh sinh nghi, sau này còn khó xử hơn.",{f:"giup_tron_goi"}),
 K16("Chỉ giúp vừa đủ: một văn bản giới thiệu chính thức","tri",0.500,"Cô viết văn bản gọn, đúng thủ tục. Không ai có thể nói điều gì ngoài chuyện công.","Văn bản bị lỗi nhỏ về thủ tục, phải gửi lại lần hai.",{f:"giup_vua_du",bonus:sk16("Viết đề án xin phép",.09)}),
 K16("Hỏi Tiểu Châu vì sao cô ta lại muốn quay về","van",0.480,"«Cô ta muốn xem mình bỏ lỡ điều gì», Tiểu Châu đáp. Cô nhẹ cả người, như vừa hiểu ra một câu đố.","Tiểu Châu im lặng. Cô nhận ra có những điều ngay cả hệ thống cũng không đọc được.",{})],
{ctx:"Huyện Hứa, cùng ngày về tới. Tiểu Châu báo tin Giang Thế Quân chuyển ngành."}),

Q16("x31","vyard","Huyện bên · Nhà họ Giang","duyen","Ninh Anh về lại quê",
"Một mùa sau, Tiểu Châu chiếu lại cho cô một cảnh ở nhà họ Giang, huyện bên. Ninh Anh dắt hai con trước nhà, kinh ngạc vì khu này khác hẳn kiếp trước. Bà Phương Thu Lan đeo đầy vàng bạc, khoe nhà vừa phát tài. Khi nghe kể người dựng nên huyện Hứa là Tần Dã và vợ, Ninh Anh tái mặt bước vào phòng. Thế Quân thừa nhận Tần Dã không đơn giản. Cô có thể xem tiếp, hoặc ngắt cảnh.",
"Nàng không bao giờ ngờ người nàng đẩy vào hôn nhân lại dựng nên cả một vùng. Cảnh này là Tiểu Châu cho ngươi xem, không ai biết.",
"h_dao,h_anh,h_quan,h_lan,tc",[
 K16("Xem tiếp, để hiểu cô ta đang nghĩ gì","tri",0.500,"Cô thấy Ninh Anh nhìn mãi vào gương, môi mấp máy một câu gì đó. Cô đoán ra được.","Cảnh tối đi giữa chừng, Tiểu Châu cắt vì quá tải.",{f:"xem_tiep_31"}),
 K16("Ngắt cảnh, không muốn nhìn thêm nỗi không cam của người khác","van",0.510,"Cô lấy lại bình tĩnh. Có những điều không cần xem hết.","Cô ngắt chậm một nhịp, vẫn lỡ nghe một câu gay gắt của Ninh Anh.",{f:"ngat_canh"}),
 K16("Ghi lại những gì thấy, để nhớ chứ không xét đoán","mi",0.490,"Cô viết ra ba dòng ngắn gọn. Sau này sẽ dùng khi cần.","Cô ghi nhầm chi tiết, về sau phải đối chiếu lại.",{})],
{ctx:"Nhà họ Giang ở huyện bên, một mùa sau. Tiểu Châu chiếu lại cảnh Ninh Anh trở về."}),

Q16("x32","vyard","Huyện Hứa · Sân nhà cô","chon","Thế Quân tới nhờ",
"Vài ngày sau, Giang Thế Quân mang quà tới sân nhà cô, xin được chuyển việc về thành phố. Hai người nói chuyện một tiếng, rồi anh nhờ người sắp xếp. Cô nhìn Thế Quân ra về với vẻ hừng hực quyết tâm. Tần Dã ngồi đó, con mèo vẫn nằm trong lòng cô, và anh nhìn con mèo với vẻ ghen. Cô có thể dỗ anh, hoặc cười anh.",
"Anh ghen cả con mèo. Đây là phiên bản dễ thương nhất của việc sợ mất.",
"h_dao,h_da,h_quan,tc",[
 K16("Dỗ anh: bế mèo đặt sang một bên rồi ngồi sát vào anh","mi",0.510,"Anh nhìn cô, khóe môi cong lên rất khẽ. Con mèo quay đi giận dỗi.","Con mèo đòi lại chỗ cũ, anh nhìn trời, cô nhịn cười.",{f:"do_anh_32"}),
 K16("Cười anh: «Anh ghen với một con mèo sao?»","van",0.480,"Anh đỏ tai: «Anh không có.» Cả hai cùng cười.","Anh nghe thành cô chê. Anh quay đi, im lặng rất lâu.",{f:"cuoi_anh_32",b:[0,2,0,-2]}),
 K16("Đưa anh một cái hộp quà của Thế Quân, bảo anh quyết định","tri",0.500,"Anh mở ra, cười vì thấy toàn đồ cũ ở quê. «Anh nhớ rồi.»","Anh xem hộp quà rất lâu mà không nói câu nào.",{})],
{ctx:"Sân nhà cô ở huyện Hứa, vài ngày sau. Giang Thế Quân tới nhờ chuyển việc."}),

Q16("x33","vlou","Huyện Hứa · Nhà hàng","hiem","Bữa cơm tạ ơn",
"Thế Quân mời một bữa ở nhà hàng trong huyện. Ninh Anh đi cùng chồng nhưng cứ cau có. Khi nghe Thế Quân cảm ơn Tần Dã vì xin được chỗ việc ở thành phố, cô ta thét «Anh nói gì?» trước cả phòng, rồi lấp liếm là mình ngạc nhiên. Tần Dã nghe được lời thì thầm trước đó của cô ta và nhớ lại chuyện cũ. Thế Quân xin lỗi hai người và ngầm quyết định xử lý chuyện vợ mình. Cô có thể để Tần Dã tự xử, hoặc nhắc khéo Thế Quân.",
"Lời thì thầm là thứ cô ta không biết mình đã để lộ. Anh nhớ nó.",
"h_dao,h_da,h_quan,h_anh,tc",[
 K16("Để Tần Dã tự xử, cô ngồi cạnh nắm tay anh","van",0.500,"Anh chỉ hỏi một câu, giọng bình tĩnh. Cả bàn im lặng, Ninh Anh cúi gằm.","Anh không hỏi gì cả, chỉ nhìn Ninh Anh. Ly nước trên bàn đổ vì ai đó chạm vào.",{f:"de_anh_xu"}),
 K16("Nhắc khéo Thế Quân: «Anh về hỏi vợ cho kỹ nhé»","mi",0.490,"Thế Quân gật, mắt tối lại. Ninh Anh nghe được, tay run lên.","Cô nói hơi lớn, Ninh Anh bật dậy khỏi bàn, ly nước đổ bắn vào tay áo cô.",{f:"nhac_the_quan",b:[-1,1,0,-3]}),
 K16("Đổi đề tài sang chuyện con cái, giữ bữa cơm yên ổn","tri",0.480,"Hai đứa nhỏ cười nói, bữa cơm êm trở lại. Nhưng ánh mắt Tần Dã vẫn lạnh.","Cô đổi đề tài quá gượng, Thế Quân nhận ra liền. Mọi người nhìn nhau.",{})],
{ctx:"Nhà hàng trong huyện Hứa. Bữa cơm tạ ơn của Giang Thế Quân."}),

Q16("x34","rriver","Huyện Hứa · Bờ sông","chon","Hỏi lại chuyện rơi nước",
"Hôm sau, Tần Dã bắt đầu thắc mắc vì sao bờ sông sụt đúng hôm anh đi qua, và ai gọi người đến đúng lúc. Cô cùng anh đi hỏi những người đứng xem năm xưa, chỉ cách hỏi từng người về giờ giấc, vị trí, câu họ nghe được. Cô nhớ rõ Ninh Anh hẹn mình tới bờ sông ngày đó. Cô có thể nói ra điều mình nhớ, hoặc chờ người khác nói.",
"Một câu hỏi đúng cách đáng giá hơn mười lời kết tội. Hỏi thật kỹ, đừng gợi ý.",
"h_dao,h_da,h_anh,h_bao,tc",[
 K16("Nói ra điều mình nhớ: Ninh Anh hẹn mình tới bờ sông","tri",0.490,"Tần Dã lặng đi, rồi gật. «Vậy là cô ta biết trước.» Cô thấy anh siết tay lại.","Cô nói thiếu đầu thiếu đuôi, anh phải hỏi lại ba lần, hơi bực.",{f:"noi_dieu_nho",bonus:sk16("Hỏi chuyện nhân chứng",.09)}),
 K16("Chờ người khác nói, ghi lại từng lời nhân chứng","van",0.510,"Cô ghi đủ ba lời khai, đúng với nhau. Cô thấy mình như đang dựng lại một bức tranh.","Hai người khai lệch nhau về giờ, cô không biết tin ai.",{f:"cho_nguoi_noi"}),
 K16("Đề nghị anh đi hỏi một mình, cô chờ ở nhà","mi",0.470,"Anh về với mắt đỏ, kể hết. Cô ôm lấy anh, không hỏi thêm.","Anh đi về trong im lặng, cô đoán đã có chuyện nhưng không dám hỏi.",{})],
{ctx:"Bờ sông Huyện Hứa, hôm sau. Hai người hỏi lại những người từng chứng kiến vụ rơi nước.",learn:{n:"Hỏi chuyện nhân chứng",s:"tri",v:2}}),

Q16("x35","rriver","Huyện Hứa · Ngoài bờ sông","nan","Lời khai của Ninh Thư Bảo",
"Tối đó, ngoài bờ sông, Ninh Thư Bảo vô tình nghe được cuộc hỏi, do dự rồi kể: đêm trước ngày đó, cậu thấy chị mình đào bờ sông rồi lấy cỏ che; Ninh Anh còn cho cậu kẹo để đi gọi người tới. Cậu tưởng chị muốn ép Tần Dã cưới, không ngờ lại kéo cô xuống nước. Tần Dã ôm cô thật chặt: «may mà cô ta ghét anh», vì nếu không người vớt anh lên là Ninh Anh và họ sẽ không bao giờ gặp. Anh siết cô lâu đến mức cô thấy lồng ngực anh run.",
"Đây là chuyện anh chưa từng muốn biết. Anh đang vừa mừng vừa sợ: mừng vì gặp cô, sợ vì suýt không gặp.",
"h_dao,h_da,h_bao,h_anh,tc",[
 K16("Ôm lại anh, nói: «Em ở đây, em chưa đi đâu»","mi",0.490,"Anh cúi mặt vào vai cô, im lặng khá lâu. Hơi thở anh chậm dần.","Anh vẫn ôm chặt, tay run đến mức cô phải vỗ lưng anh như dỗ một đứa trẻ.",{f:"om_lai_35",bonus:sk16("Hỏi chuyện nhân chứng",.09)}),
 K16("Hỏi Thư Bảo thêm vài chi tiết, rồi cảm ơn cậu bé","tri",0.500,"Thư Bảo kể rõ hơn, tay vẫn nắm kẹo. Anh nghe xong, đứng thẳng người lại.","Thư Bảo hoảng, kể rối. Cô phải dỗ cậu bé trước khi hỏi tiếp.",{f:"hoi_them_35"}),
 K16("Nắm tay anh, không nói gì, để lời khai tự lắng xuống","van",0.480,"Gió bờ sông mát hơn bình thường. Tay anh dần ấm lại.","Anh bỏ tay cô ra, đi ra mép sông đứng một mình. Cô đành chờ phía sau.",{})],
{ctx:"Ngoài bờ sông, tối đó. Ninh Thư Bảo kể lại chuyện cũ.",forced:1,fix:w16spikeK("s35","noi_thang_12")}),

Q16("x36","vstudy","Huyện Hứa · Phòng khách","duyen","Tránh xa Ninh Anh",
"Ngay sau đó trong phòng khách, anh dặn: từ nay tránh Ninh Anh càng xa càng tốt, rồi nói sang kế hoạch thăng huyện lên thành phố trong năm năm, xây một trường đại học. Cô hứa vẽ bản vẽ trường. Anh nói cùng đi học đến ngày tốt nghiệp. Cô có thể đồng ý và đòi thêm điều kiện, hoặc đùa rằng muốn làm khóa đầu.",
"Anh đã đổi chủ đề rất khéo: đưa nỗi giận về phía một kế hoạch dài. Hỗ trợ anh đi tiếp là cách chữa tốt nhất.",
"h_dao,h_da,tc",[
 K16("Đồng ý và đòi thêm điều kiện: mỗi tối anh về ăn cơm với em","mi",0.510,"Anh bật cười: «Anh vốn định thế rồi.» Khóe mắt anh dịu hẳn.","Anh hơi sững: «Em tưởng anh không về sao?» Cô phải giải thích lại.",{f:"dieu_kien_36"}),
 K16("Đùa rằng muốn làm khóa đầu, sinh viên số một","van",0.500,"Anh cười: «Anh sẽ là sinh viên số hai.» Cả hai cười ngặt nghẽo.","Anh nghĩ cô nghiêm túc, ngồi bàn chuyện suất học thật.",{f:"khoa_dau"}),
 K16("Mở bản vẽ ra bàn ngay, vẽ phác khuôn viên trường","tri",0.490,"Nét bút chạy nhanh. Anh ngồi cạnh, nhìn ngôi trường dần hiện ra.","Bản phác đầu tiên còn lệch tỷ lệ, hai người cùng ngồi sửa.",{f:"ve_phac_truong",bonus:sk16("Vẽ bản đồ quy hoạch",.09)})],
{ctx:"Phòng khách nhà cô, ngay sau đó. Anh bàn chuyện thăng huyện thành thành phố và xây đại học."}),

/* ---- Chương 6: Đại học và những năm cuối (mốc 37–45) ---- */
Q16("x37","vstreet","Huyện Hứa · Quán trà","chon","Lời đồn «dựa hơi»",
"Một chiều ở quán trà trong huyện, có người nói cô chỉ ăn theo danh Tần Dã. Anh bực vì mọi đóng góp của cô ở xưởng, ở trại gà, ở bản vẽ đều bị gạt đi; cô thấy không đáng để ý. Anh vẫn muốn làm gì đó. Cô có thể đính chính bằng việc làm, hoặc bằng một buổi nói chuyện công khai.",
"Anh giận thay cô nhiều hơn cô giận. Hãy để anh thấy cô tự lo được.",
"h_dao,h_da,tc",[
 K16("Đính chính bằng việc làm: công bố bản vẽ trường có tên mình","tri",0.500,"Người trong huyện đọc tên cô trên bản vẽ. Hôm sau không ai nhắc câu «dựa hơi» nữa.","Bản vẽ công bố chậm, lời đồn kéo thêm vài ngày.",{f:"dinh_chinh_viec",bonus:sk16("Vẽ bản đồ quy hoạch",.09)}),
 K16("Đứng ra nói chuyện công khai, kể từng việc cô đã làm","mi",0.480,"Cô nói giản dị, cả hội trường im phăng phắc. Anh ngồi hàng đầu, mắt không rời cô.","Cô nói run, một vài người ngồi cuối vẫn xì xào.",{f:"noi_cong_khai",bonus:sk16("Soạn giáo án lớp xóa mù",.09)}),
 K16("Mặc kệ lời đồn, kéo anh về nhà ăn cơm","van",0.510,"Anh nhìn cô một lúc rồi cười, cơn giận vơi đi một nửa.","Anh vẫn ngồi lại, cứ nghĩ mãi. Cô phải kéo mãi mới chịu đi.",{})],
{ctx:"Quán trà trong huyện Hứa, một chiều. Có người nói cô dựa hơi Tần Dã."}),

Q16("x38","vroom","Huyện Hứa · Phòng khách nhà cô","hiem","Bạch Tử Nguyệt tới thăm",
"Ít ngày sau, trong phòng khách, cô đang đan áo len. Cô nghiên cứu sinh du học về, Bạch Tử Nguyệt, trang điểm thời thượng, tìm cô để «hâm mộ». Cô ta khoe tuổi, văn bằng, chuyện dạy toán ở đại học tương lai, và ngầm cho rằng vợ thôn quê sẽ lạc hậu. Cô vừa đan áo vừa đáp: «cô lớn hơn tôi hai tuổi mà còn đang học, tôi lùi bước sao được». Cô có thể mời Tử Nguyệt dạy toán trong trường, hoặc thử nhờ cô ta chỉ một bài khó.",
"Nàng không đến để hâm mộ. Cô thông minh, mà lòng cô ta cũng thông minh. Đừng giấu anh chuyện này.",
"h_dao,h_da,h_nguyet,tc",[
 K16("Mời Tử Nguyệt dạy toán trong trường, công khai và đàng hoàng","mi",0.500,"Tử Nguyệt ngập ngừng rồi nhận lời. Cô ta không nghĩ cô lại hào phóng vậy.","Tử Nguyệt cười mỉa, hỏi cô muốn gì. Cô phải giải thích rằng mình chỉ cần giáo viên giỏi.",{f:"moi_day_toan"}),
 K16("Nhờ cô ta chỉ một bài toán khó, vừa đan vừa nghe","tri",0.480,"Cô nghe giảng, hỏi lại đúng chỗ. Tử Nguyệt giật mình vì cô hiểu nhanh.","Cô hỏi chưa đúng chỗ, Tử Nguyệt giảng lòng vòng. Vài mũi len bị rối.",{f:"nho_chi_bai",bonus:sk16("Đan áo len",.09)}),
 K16("Tiếp khách lịch sự rồi không kể với anh, tự mình xử lý","van",0.500,"Tử Nguyệt ra về mà cô vẫn đan được hết dòng. Nhưng tối đó anh nhìn cô rất lâu.","Cô giấu anh một chuyện nhỏ. Anh nghe từ người khác, mặt anh tối lại.",{f:"giau_anh_38",g:[-1,3,2,0],b:[0,4,0,-3]})],
{ctx:"Phòng khách nhà cô ở huyện Hứa, ít ngày sau. Bạch Tử Nguyệt đến thăm.",learn:{n:"Đan áo len",s:"van",v:1}}),

Q16("x39","vstudy","Huyện Hứa · Khuôn viên Đại học Hứa thị","duyen","Đại học và đề tự",
"Ba năm sau, khuôn viên đại học đã xây xong. Văn lão cùng các văn hào đến đề chữ cho trường; họ trầm trồ khi thấy chữ của cô, khen ông có cháu dâu như vậy. Tần Dã nhìn cô đứng cạnh các bậc thầy, mắt rưng rưng. Cô có thể tự tay viết một bức để treo ở cổng, hoặc chỉ mài mực cho ông.",
"Cô từng viết bản vẽ cho cả thành phố. Giờ cô viết một bức chữ cho cổng trường.",
"h_dao,h_da,h_van,tc",[
 K16("Tự tay viết một bức, để treo ở cổng trường","mi",0.490,"Cô viết xong, các văn hào gật đầu. Văn lão cười: «Chữ có hồn.» Anh đứng sau, không giấu được mắt đỏ.","Nét cuối của cô run, nhưng Văn lão chỉ vuốt râu: «Run cũng là hồn.»",{f:"tu_tay_viet"}),
 K16("Mài mực cho ông, đứng bên học nét viết","van",0.510,"Ông viết xong còn quay lại hỏi cô nghĩ sao về nét cuối. Cô thấy mình như học trò.","Mực mài loãng, ông nhắc nhẹ. Cô ngượng đỏ mặt.",{f:"mai_muc_39"}),
 K16("Mời Văn lão ở lại huyện thêm vài ngày, cùng dạy vài buổi đầu","tri",0.480,"Ông ngẫm rồi gật. «Được. Ta ở thêm ba ngày.» Anh quay đi lau mắt.","Ông bận lịch ở thủ đô, từ chối nhẹ nhàng. Cô thấy hơi tiếc.",{})],
{ctx:"Khuôn viên Đại học Hứa thị, ba năm sau. Văn lão cùng các văn hào đến đề chữ cho trường."}),

Q16("x40","school","Thành phố Hứa · Lễ khai giảng","chon","Thăng thành phố và khóa đầu",
"Nửa năm sau, huyện Hứa thăng thành thành phố Hứa. Văn lão làm hiệu trưởng đầu tiên, các văn hào làm giáo sư. Cô và Tần Dã vào học khóa đầu, cùng một lớp. Bạch Tử Nguyệt vào dạy, nhưng khi biết cô giỏi toán đến mức giáo sư mời cô theo nghề, cô từ chối vì muốn ở bên anh và dựng thành phố. Giờ cô có thể học thêm toán với giáo sư, hoặc tập trung các môn quản lý.",
"Hai đường đều mở. Chọn đường nào cũng có người đứng cạnh.",
"h_dao,h_da,h_van,h_nguyet,tc",[
 K16("Học thêm toán với giáo sư, giữa giờ vẫn đi họp với anh","tri",0.490,"Cô học đến muộn, anh ngồi bên bàn chờ. Đêm đó họ ngồi chấm bài cùng nhau.","Hai việc chồng nhau, cô mệt đến mức ngủ gục giữa buổi họp.",{f:"hoc_toan",bonus:sk16("Soạn giáo án lớp xóa mù",.09)}),
 K16("Tập trung các môn quản lý, cùng anh học thật sâu","mi",0.510,"Hai người ngồi chung một dãy bàn, thầy giáo nhiều lần mượn ví dụ từ chính xưởng và huyện của họ.","Môn đầu quá khô, cô phải học thêm ban đêm mới theo kịp.",{f:"hoc_quan_ly"}),
 K16("Học cả hai, chấp nhận ngủ ít, nhờ anh nhắc giờ nghỉ","van",0.470,"Anh quản lý lịch rất sát. Cuối kỳ, cả hai cùng đứng nhất lớp.","Cô vẫn thức khuya, ngày thứ ba bị cảm. Anh ép cô nghỉ cả tuần.",{})],
{ctx:"Lễ khai giảng thành phố Hứa, nửa năm sau. Cô và Tần Dã vào học khóa đầu."}),

Q16("x41","vhall","Nhiều nơi · Bục diễn thuyết","duyen","Diễn thuyết và hai người một vé",
"Nhiều năm sau, hai vợ chồng thành người nổi tiếng. Lời mời từ nhiều nơi gửi tới, họ chỉ nhận lời nếu đi cùng nhau hoặc xa nhau không quá ba ngày. Cô lên bục nói về giáo dục và thành phố, anh nói về kinh tế. Cô có thể nói bằng ví dụ gần gũi, hoặc bằng số liệu.",
"Người nghe nhớ câu chuyện lâu hơn nhớ con số. Nhưng con số lại khiến người ta tin.",
"h_dao,h_da,tc",[
 K16("Nói bằng ví dụ gần gũi: bà cụ viết tên mình lần đầu","mi",0.510,"Cả hội trường lặng đi. Có người lau mắt. Anh đứng cuối sảnh, nhìn cô như nhìn ánh đèn.","Cô nghẹn ở giữa câu, phải dừng lại uống nước. Hội trường chờ.",{f:"vi_du_gan_gui",bonus:sk16("Soạn giáo án lớp xóa mù",.09)}),
 K16("Nói bằng số liệu: tỉ lệ biết chữ, thu nhập, số trường","tri",0.490,"Bảng số liệu của cô gọn mà sắc. Nhiều đại biểu ghi chép liên tục.","Cô nhầm một con số, phải đính chính giữa chừng. May có anh nhắc.",{f:"so_lieu"}),
 K16("Kết hợp: một câu chuyện rồi một con số làm chứng","van",0.480,"Hai điều bổ trợ nhau. Cô xuống bục trong tiếng vỗ tay dài.","Cô chuyển ý hơi vội, người nghe cần thêm thời gian để theo kịp.",{})],
{ctx:"Nhiều nơi, nhiều năm sau. Hai vợ chồng đi diễn thuyết.",learn:{n:"Diễn thuyết",s:"mi",v:2}}),

Q16("x42","vmansion","Kinh thành · Tứ hợp viện nhà họ Tần","nan","Nhà họ Tần sụp đổ",
"Mấy năm sau, Tần Duệ và Tần Huyên ra buôn rồi bị những người từng chịu thiệt từ nhà họ Triệu chặn đường; quay về cơ quan thì không có đường lên. Bán một tứ hợp viện lo nhà cho Tần Duệ, Tần Huyên đòi chia, hai cụ nổi giận rồi qua đời. Bán nốt căn kia, Tần Quốc Vinh và Triệu Nhã Phượng phải thuê nhà. Tần Dã nghe tin, chỉ gật đầu. Cô có thể giữ im lặng, hoặc hỏi lòng anh.",
"Anh không vui, cũng không buồn. Có những điều đã tới hạn mới hiểu mình không muốn nữa.",
"h_dao,h_da,h_vinh,h_phuong,h_due,h_huyen,tc",[
 K16("Giữ im lặng, ngồi cạnh anh uống hết tách trà","van",0.510,"Anh uống hết tách trà, rồi nói khẽ: «Anh không thấy hả hê. Lạ thật.»","Tách trà nguội hẳn trước khi anh nói được câu nào. Cô chờ.",{f:"im_lang_42",g:[-1,0,2,0]}),
 K16("Hỏi lòng anh: «Anh có muốn làm gì cho họ không?»","tri",0.480,"Anh nghĩ lâu. «Không. Nhưng anh sẽ không nhắc đến họ nữa.»","Anh lảng đi: «Anh không nghĩ tới.» Cô nhận ra mình hỏi khi anh chưa sẵn sàng.",{f:"hoi_long_anh"}),
 K16("Nhắc anh đến chị Tần Thanh, rủ anh gọi điện cho chị","mi",0.500,"Chị nghe tin, thở dài, rồi nói đúng điều anh cần nghe. Anh cúp máy với đôi mắt đã dịu.","Chị bận họp, nghe tin cũng ngắn. Anh thấy trống trải hơn.",{})],
{ctx:"Tứ hợp viện nhà họ Tần ở kinh thành, mấy năm sau. Tin nhà họ Tần sụp đổ tới tai anh.",fix:function(d){var o=Object.assign({},d);if(S.f.di_toi_cung)o.hac=(o.hac||0)+4;return o}}),

Q16("x43","vmansion","Kinh thành · Tang lễ","nan","Cha anh lúc cuối đời",
"Một năm sau ở kinh thành, Tần Quốc Vinh mất, trước đó vẫn nhắc tên Tần Dã và Tần Thanh. Tần Dã về dự và nhìn Triệu Nhã Phượng, người vẫn nhìn anh bằng ánh mắt chán ghét. Anh nói với cô: «người chết thì giải thoát, người sống còn phải chịu». Giờ cô có thể giữ tay anh khi anh quay đi, hoặc hỏi anh có muốn ở lại thêm.",
"Có những cánh cửa anh sẽ không mở nữa. Việc của ngươi là đứng cạnh anh khi anh quyết định đóng nó.",
"h_dao,h_da,h_vinh,h_phuong,h_thanh,tc",[
 K16("Giữ tay anh khi anh quay đi, rời đám tang cùng anh","mi",0.510,"Anh bước nhanh hơn một chút, rồi chậm lại khi thấy tay cô. Họ ra khỏi cổng cùng nhau.","Anh quay đi quá nhanh, cô phải đi gấp mới theo kịp. Nhưng tay anh không buông.",{f:"giu_tay_43",bonus:sk16("Đan áo len",.09)}),
 K16("Hỏi anh có muốn ở lại thêm, nói chuyện với chị","tri",0.490,"Anh ở lại thêm một giờ với chị. Hai chị em ngồi nói thật nhiều chuyện cũ.","Anh nói không muốn. Giọng nặng hơn dự tính, cô lùi lại, im lặng.",{f:"hoi_o_lai"}),
 K16("Dâng nén hương thay anh, cúi chào ngắn gọn","van",0.500,"Cô cúi chào rất khẽ. Anh nhìn cô, ánh mắt biết ơn.","Cô vụng về làm rơi nén hương, anh đỡ lấy, cười nhạt.",{})],
{ctx:"Kinh thành, một năm sau. Tần Quốc Vinh qua đời, anh về dự tang lễ.",forced:1,fix:w16spikeK("s43","khuyen_dung")}),

Q16("x44","jcity","Thành phố lớn · Nơi Thế Quân làm việc","duyen","Kết cục của Ninh Anh và Thế Quân",
"Cùng thời gian, Giang Thế Quân ly hôn khi con gái út tốt nghiệp đại học; anh nhịn nhiều năm vì con. Ninh Anh sau này tìm tới xin quay lại, bị hai đứa con mời ra. Thế Quân gặp một người thật lòng thích anh và sống hạnh phúc. Tin này tới tay cô qua một bức thư ngắn. Cô có thể nghe tin và để mặc, hoặc gửi một lời nhắn thăm Thế Quân.",
"Mọi người đều được chọn lại. Ninh Anh cũng vậy, chỉ là nàng chọn muộn.",
"h_dao,h_quan,h_anh,tc",[
 K16("Nghe tin và để mặc, không bình luận","van",0.510,"Cô gấp lá thư lại. Gió thổi qua rèm, lòng cô yên.","Cô đọc đi đọc lại, vẫn thấy nặng nặng trong lòng.",{f:"de_mac_44"}),
 K16("Gửi một lời nhắn thăm Thế Quân, chúc anh bình an","mi",0.490,"Thế Quân đáp một dòng cảm ơn, kèm một bức ảnh gia đình mới. Cô mỉm cười.","Lời nhắn bị gửi nhầm địa chỉ, quay lại sau hai tuần.",{f:"nhan_the_quan"}),
 K16("Kể cho anh nghe tin này, hỏi anh nghĩ gì","tri",0.500,"Anh im lặng rồi nói: «Anh mừng cho anh ấy. Anh mừng vì chính mình có em.»","Anh nghe xong, chỉ gật đầu. Cô không biết anh nghĩ gì.",{})],
{ctx:"Thành phố lớn, cùng thời gian. Tin Giang Thế Quân ly hôn tới tay cô."}),

Q16("x45","vfarm","Hứa gia thôn · Căn nhà cũ","nan","Lời kết",
"Một sáng ở căn nhà cũ tại Hứa gia thôn, Tiểu Châu báo nhiệm vụ ở thế giới này đã xong. Tần Dã linh cảm cô sắp rời đi, hỏi «em đi đâu, mang anh theo được không?». Cô nói không biết nên không mang được. Anh xin ở bên cô tới phút cuối, và cô đồng ý. Ngoài sân, dân huyện và dân thành phố đã đến đứng chật bên cổng, vì tin lan nhanh. Anh nắm tay cô, và tay anh run.",
"Anh sẽ siết hay buông, còn tùy chuyện anh học được suốt những năm qua.",
"h_dao,h_da,h_thanh,h_ngoc,h_hang,tc",[
 K16("Nói thật với anh: «Em sẽ đi, nhưng em đã sống trọn ở đây»","mi",0.490,"Anh gật rất chậm, rồi nở nụ cười đã quá quen thuộc. «Vậy là đủ.»","Anh gật mà nước mắt rơi trước. Cô đưa tay lau cho anh.",{f:"noi_that_45",bonus:sk16("Diễn thuyết",.09)}),
 K16("Nắm tay anh, đọc lại lời hứa lúc mới cưới","tri",0.480,"Hai bàn tay không rời nhau. Anh lẩm bẩm theo từng chữ.","Anh nghe đến câu thứ hai thì ôm chặt cô, không cho nói tiếp.",{f:"doc_loi_hua"}),
 K16("Mời cả nhà vào ăn bữa cơm cuối trong sân, như mọi ngày","van",0.500,"Hai anh, cha mẹ, chị Tần Thanh đều ngồi lại. Bữa cơm không ai nói chuyện buồn.","Mẹ khóc, cha lúng túng gắp thức ăn. Anh nắm tay cô dưới bàn.",{f:"bua_com_cuoi"})],
{ctx:"Căn nhà cũ ở Hứa gia thôn, một sáng. Tiểu Châu báo nhiệm vụ ở thế giới này đã xong."})
];

var IX16={};EV16.forEach(function(e,i){e.no=i+1;IX16[e.id]=i});
function w16spread(k){EV16.forEach(function(e){var r=e.ch.filter(function(c){return c.s&&typeof c.b==="number"||c.b0!==undefined});if(r.length<2)return;r.forEach(function(c){if(c.b0===undefined)c.b0=c.b});var m=r.reduce(function(a,c){return a+c.b0},0)/r.length;r.forEach(function(c){c.b=Math.max(.2,Math.min(.8,m+k*(c.b0-m)))})})}

var ENDS16={
 true:{n:"Hai bàn tay, một vòng người đưa tiễn",c:"Tiểu Châu đọc kết quả: đạt, trọn vẹn. Ác niệm của Tần Dã về không. Anh không còn sợ bị bỏ lại, cũng thôi nắm tay cô như nắm một sợi chỉ sắp đứt. Hai người sống đến tuổi già ở Hứa gia thôn đã thành thành phố, xưởng Hứa thị vẫn còn, ngôi trường vẫn mở cổng mỗi sáng. Đến ngày cô phải đi, anh nắm tay cô nhẹ như nắm một cánh hoa, giữa vòng người đưa tiễn chật cả sân. Họ ra đi bình yên, cùng một ngày.",gain:120,piece:1,heat:.1,scene:"vdawn"},
 near:{n:"Anh siết tay cô hơi chặt",c:"Tiểu Châu đọc kết quả: đạt, nhưng chưa trọn. Hai người vẫn bên nhau đến cuối. Thành phố Hứa lớn dần, xưởng và trường đều vững. Chỉ có điều những lần cô sắp đi xa, tay anh vẫn siết hơi chặt, như sợ gió cuốn đi. Cô không giận. Cô biết anh đang học cách tin rằng lần này không ai bị bỏ lại, và vết lo trong mắt anh nhạt dần theo từng mùa.",gain:90,piece:1,heat:.35,scene:"vyard"},
 half:{n:"Căn nhà cũ giữ lại một mình",c:"Tiểu Châu đọc kết quả: chưa đạt. Cô đã làm gần hết nhiệm vụ: thành phố, xưởng, trường học, tất cả đều ổn. Nhưng vết sợ mất trong anh vẫn chưa lành. Đến ngày cô rời đi, anh ở lại một mình giữ căn nhà cũ ở Hứa gia thôn, vẫn rót hai cái chén mỗi sáng. Có những vết, tình thương không đủ để lấp, và cả hai đều biết điều đó.",gain:60,piece:0,heat:.6,scene:"vroom"},
 black:{n:"Cánh cửa khép lại sau lưng anh",c:"Hắc hóa chạm 100. Nỗi sợ mất cô và mối hận với những người từng bỏ rơi anh nuốt trọn Tần Dã. Anh không nghe tên mình, không nghe tiếng cô, chỉ còn tiếng cánh cửa khép lại sau lưng. Tiểu Châu khẽ gọi cô đi trước khi căn nhà lặng hẳn.",gain:0,piece:0,heat:1,scene:"vfire"},
 bdead:{n:"Chiếc áo len dang dở",c:"Sinh mệnh của Tần Dã về 0. Anh kiệt sức vì làm việc không nghỉ để giữ mọi thứ cho cô, vì những đêm không ngủ nghĩ về chuyện cô sẽ đi. Chiếc áo len cô đan dở vẫn nằm trên ghế. Tiểu Châu khẽ gọi cô về.",gain:0,piece:0,heat:.9,scene:"vdawn"},
 dead:{n:"Ấm nước chưa kịp mang ra ruộng",c:"Sinh mệnh của cô cạn kiệt. Một bước chân sai ở bìa rừng hay một lần ngã đưa cô đi nhanh hơn dự tính, và đêm ấy không ai kịp tới ngồi bên giường. Tiểu Châu kéo linh hồn cô đi trước khi Tần Dã chạm tay vào cánh cửa.",gain:0,piece:0,heat:.8,scene:"rforest"}
};

function w16emblem(heat){
  /* Một quả đào và vầng trăng khuyết; viền ngoài ngả đỏ theo Hắc hóa */
  return '<svg class="eye" viewBox="0 0 96 96" role="img" aria-label="Quả đào và vầng trăng, viền ngoài ngả đỏ dần theo Hắc hóa"><circle cx="48" cy="48" r="45" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="48" cy="48" r="45" fill="none" stroke="var(--ember)" stroke-width="2" stroke-dasharray="'+(heat*283)+' 283" transform="rotate(-90 48 48)"/>'
   +'<path d="M48 70 C28 64 28 40 44 34 C52 31 60 36 62 46 C66 60 58 68 48 70Z" fill="color-mix(in oklab,#f0a58c 70%,var(--surface))" stroke="var(--fg)" stroke-width="2.2"/><path d="M48 34 Q50 26 58 24" stroke="var(--fg)" stroke-width="2" fill="none"/>'
   +'<circle cx="68" cy="30" r="10" fill="color-mix(in oklab,var(--ember) '+Math.round(heat*100)+'%,#dfe4ea)" stroke="var(--fg)" stroke-width="2.2"/></svg>';
}

