var EV17=[
/* ---- Chương 1: Ngày đầu ở Hà Lâm (mốc 1–8) ---- */
Q17("t01","rcave","Bộ lạc Hà Lâm · Hang đá của A Kỳ","duyen","Tỉnh dậy trong hang đá",
"A Kỳ tỉnh dậy khi nắng đã lên cao, trong thân một cô gái hai mươi tuổi. Một quả cầu ngọc xanh nhỏ lơ lửng bên tấm da thú: «Ta là Tiểu Châu». Nó giao nhiệm vụ: sống trọn đời cùng Đại Tư Tế Bạch Triệt và giữ anh khỏi con đường trở thành hung thần. Hồ sơ nguyên chủ: A Kỳ, «tiểu công chúa» của bộ lạc Hà Lâm, con gái vị thủ lĩnh cũ đã hy sinh vì bộ lạc, ai cũng nể vì cha mẹ cô. Trên cổ cô treo chiếc vòng cổ xương của mẹ. Cuốn truyện gốc dừng ở đây: hôm nay Khắc Cang sẽ mang một cô gái lạ tên Phương Lạc Nghi về, và ít lâu sau bộ lạc giao A Kỳ cho Hắc Thạch quốc của quốc vương Hách Lôi thay cô ta. Cô bị giao đi và không bao giờ trở về. Phần sau cô phải tự đi.",
"Ngươi biết trước cả cốt truyện, còn bộ lạc thì không. Đó là lợi thế, nhưng đừng khoe ra.",
"tk_ky,tk_triet,tk_loi,tc",[
 K17("Ra cửa hang chờ Khắc Cang mang cô gái lạ về","tri",0.500,"Cô đứng đúng chỗ, đúng giờ, đúng như trang truyện. Tiểu Châu khẽ gật.","Cô ra hơi sớm, đứng giữa nắng quá lâu, hoa cả mắt.",{}),
 K17("Đi tìm Bạch Triệt trước, đừng đợi chuyện tới","mi",0.510,"Từ xa, cô thấy anh đứng trước thạch ốc như đã đợi ai. Ngực cô nhẹ đi.","Cô lạc đường giữa các hang, tới nơi thì anh đã đi hái thuốc.",{}),
 K17("Ghi lại những điều cần nhớ trong cốt truyện gốc","van",0.480,"Cô ghi ngắn gọn từng mốc lên da thú. Đầu óc cô sáng ra, như vừa dọn xong một cái kho.","Cô ghi nhầm thứ tự hai việc, phải xóa đi viết lại mãi mới ổn.",{})],
{ctx:"Hang đá của A Kỳ, sáng muộn. Tiểu Châu giao nhiệm vụ và đọc hồ sơ nguyên chủ."}),

Q17("t02","rfire","Bộ lạc Hà Lâm · Cửa hang, gần trưa","chon","Cô gái lạ trên vai sư tử",
"Gần trưa, các giống cái đang phơi thịt khô và quả khô trước hang. Khắc Cang, dũng sĩ thứ hai của bộ lạc, hóa người ngay trước cổng và khiêng vào một cô gái nhỏ gầy, da trắng, ăn mặc kỳ lạ. Anh tuyên bố trước mọi người: «đây là người của tôi». Thiết Lan, em gái dũng sĩ Thiết Nham, ghé ngồi bên cô gái lạ, chê cô ta quá yếu rồi quay sang hỏi A Kỳ có thích Khắc Cang không. Cô đáp «không». Cô có thể ngồi nghe Thiết Lan nói tiếp để biết ai đang nghĩ gì, hoặc đứng lên đi tìm việc khác.",
"Thiết Lan cười rất hiền khi nói xấu người khác. Nhớ tên nàng.",
"tk_ky,tk_cang,tk_nghi,tk_lan,tk_nham,tc",[
 K17("Ngồi nghe Thiết Lan nói tiếp, ghi nhớ ai nghĩ gì","tri",0.510,"Thiết Lan kể liền một hơi về ba dũng sĩ và hai giống cái. Cô nhớ hết, khuôn mặt vẫn không đổi sắc.","Thiết Lan nhận ra cô lắng nghe hơi chăm chú, liền nói sang chuyện thời tiết.",{}),
 K17("Đứng lên đi phụ các giống cái phơi thịt","van",0.500,"Cô phơi thịt cạnh một bà lão, bà lão chép miệng: A Kỳ hôm nay chịu khó thật.","Cô treo xiên thịt lệch, cả hàng rơi xuống đất. Mấy cô gái cười khúc khích.",{}),
 K17("Nhìn kỹ cô gái lạ, nhớ từng chi tiết","mi",0.490,"Cô gái lạ nhận ra ánh nhìn, rụt rè gật đầu chào. Cô gật lại, không hơn không kém.","Ánh nhìn của cô dài hơn dự tính, cô gái lạ nép vào lưng Khắc Cang.",{})],
{ctx:"Cửa hang bộ lạc Hà Lâm, gần trưa. Khắc Cang mang Phương Lạc Nghi về."}),

Q17("t03","rcave","Bộ lạc Hà Lâm · Thạch ốc ở rìa bộ lạc","chon","Bệnh trong lòng",
"Tối cùng ngày, cô mang thịt khô và quả khô tới thạch ốc ở rìa bộ lạc. Bạch Triệt, Đại Tư Tế 26 tuổi, chữa bệnh và xem mai rùa, được cả bộ lạc kính như thần. Anh sống một mình, không ăn thịt tươi, hay đỏ tai khi bị trêu. Cô nói mình bị «bệnh trong lòng»: một ngày không thấy anh là khó chịu. Anh bắt mạch, rồi nghiêm mặt bảo cô khỏe đến mức đánh chết được một con dê. Cô có thể xin được tới thăm mỗi ngày, hoặc chỉ nói một câu rồi về.",
"Anh là người cả bộ lạc cúi đầu, nên chẳng ai dám ngồi xuống cạnh anh. Ngồi xuống đi.",
"tk_ky,tk_triet,tc",[
 K17("Xin được tới thăm anh mỗi ngày","mi",0.500,"Anh im lặng khá lâu, rồi quay đi pha trà thuốc. «Mai đến sớm», anh nói với cái ấm.","Cô nói quá nhanh, anh nghe thành đùa. Anh đáp «tùy em» rất lạnh, nhưng tai thì đỏ.",{f:"tham_moi_ngay",g:[-3,-2,8,2]}),
 K17("Chỉ nói một câu rồi về, không quấy anh","van",0.520,"Cô đặt thịt xuống, nói «ngủ ngon» rồi đi. Anh đứng ở cửa nhìn theo lâu hơn cần thiết.","Cô vấp ngưỡng cửa, làm đổ cả giỏ quả. Anh cúi xuống nhặt, không nói gì.",{}),
 K17("Hỏi anh bắt mạch thấy gì, nói thật mình mệt thế nào","tri",0.490,"Anh dặn vài vị thuốc lành tính, giọng dịu đi. «Em cần nghỉ nhiều hơn.»","Anh bắt mạch sai tay, đành bắt lại. Cô cười, anh càng đỏ tai.",{})],
{ctx:"Thạch ốc của Bạch Triệt, tối cùng ngày. A Kỳ nói mình bị «bệnh trong lòng»."}),

Q17("t04","rfire","Bộ lạc Hà Lâm · Quanh hang Khắc Cang","duyen","Mùi canh thịt",
"Cả bộ lạc sợ lửa, chỉ giữ mồi lửa khi thật cần. Sáng hôm sau, mùi thịt thơm lan từ hang Khắc Cang: Phương Lạc Nghi nấu canh thịt với hương liệu hái quanh hang, rồi nấu một nồi lớn mời mọi người. Ai cũng khen. Cô nếm thấy canh còn nhạt và chưa ninh kỹ. Cô có thể nhận việc giữ mồi lửa cho cả khu hang của mình, hoặc chỉ nhận bát canh rồi về.",
"Lửa là thứ bộ lạc sợ, và cũng là thứ cứu họ sau này. Học cách giữ nó cho chắc.",
"tk_ky,tk_nghi,tk_cang,tc",[
 K17("Nhận việc giữ mồi lửa cho khu hang của mình","van",0.510,"Cô học cách che gió, chọn củi khô và giữ than đỏ qua đêm. Mồi lửa nhà cô không tắt.","Cô giữ lửa chưa quen, than tắt giữa đêm, phải xin mồi từ hang kế bên.",{f:"giu_moi_lua"}),
 K17("Chỉ nhận bát canh, nếm kỹ rồi về","mi",0.500,"Cô khen đúng chỗ khiến Phương Lạc Nghi mừng ra mặt. Không ai thấy cô có ý gì khác.","Cô nếm lâu quá, Khắc Cang cau mày hỏi có chê không. Cô vội đáp không.",{}),
 K17("Đứng xa quan sát cách Phương Lạc Nghi nấu","tri",0.490,"Cô nhìn ra từng bước: chần, thêm hương liệu, hạ lửa. Đầu cô ghi lại hết.","Khói cay làm cô ho sặc sụa, bỏ lỡ nửa công đoạn.",{})],
{ctx:"Quanh hang Khắc Cang, sáng hôm sau. Phương Lạc Nghi nấu canh thịt cho cả bộ lạc.",learn:{n:"Giữ mồi lửa",s:"van",v:1}}),

Q17("t05","rfire","Bộ lạc Hà Lâm · Bếp đá sau thạch ốc","chon","Canh xương hầm",
"Chiều cùng ngày, cô nhóm lửa ở bếp đá sau thạch ốc của Bạch Triệt, chần xương qua nước sôi, đổ nước đầu rồi hầm lâu với hương liệu. Anh đứng khoanh tay, ngờ vực: cô cũng sợ lửa như mọi người mới phải. Thấy cô làm lưu loát, anh bật cười. Anh nếm một bát, rồi ăn tới bát thứ hai, bảo canh ngon hơn bát của Khắc Cang. Cô có thể nấu thêm thịt nướng cho anh, hoặc để anh tự học làm.",
"Anh không ăn thịt tươi. Đừng ép anh. Chỉ cần canh đúng vị.",
"tk_ky,tk_triet,tc",[
 K17("Nấu thêm thịt nướng cho anh","van",0.500,"Anh ăn từng miếng chậm rãi. «Em làm ra thứ này từ đâu?», anh hỏi. Cô chỉ cười.","Thịt nướng quá lửa, anh ăn vẫn không nói gì, chỉ nhẹ nhàng đẩy phần cháy sang một bên.",{bonus:sk17("Giữ mồi lửa",.09)}),
 K17("Để anh tự học làm, cô đứng cạnh chỉ từng bước","tri",0.510,"Anh làm hỏng hai lần, lần thứ ba thành. Anh nhìn nồi canh với vẻ như vừa thắng một trận.","Anh quên đổ nước đầu, canh đục. Cô bảo làm lại, anh đồng ý rất nghiêm túc.",{f:"day_anh_nau"}),
 K17("Hỏi anh thích vị nào, nấu theo khẩu vị anh","mi",0.490,"Anh ngập ngừng nói vài vị anh nhớ từ nhỏ. Cô ghi nhớ từng cái.","Anh nói «tùy em», cô hỏi lại ba lần mà vẫn không được câu trả lời.",{})],
{ctx:"Bếp đá sau thạch ốc, chiều cùng ngày. Cô nấu canh xương cho Bạch Triệt.",learn:{n:"Hầm canh xương",s:"tri",v:2}}),

Q17("t06","rfire","Bộ lạc Hà Lâm · Trước cửa hang cô","chon","«Không muốn kết bạn»",
"Chiều ngày thứ ba, Phương Lạc Nghi tới trước cửa hang, tự giới thiệu và xin làm bạn. Cô biết người này sẽ khiến cả bộ lạc quay sang mình, nên từ chối thẳng. Các giống cái đứng xem cười khẽ. Thiết Lan lập tức kéo Phương Lạc Nghi đi, nói «A Kỳ vốn thế», và hai người từ đó thân nhau. Cô có thể nói thẳng «tôi không muốn» rồi đi, hoặc dịu giọng nhưng vẫn giữ khoảng cách.",
"Nàng ta không có lỗi gì với ngươi. Lỗi nằm ở cách cả bộ lạc nhìn ngươi sau này.",
"tk_ky,tk_nghi,tk_lan,tc",[
 K17("Nói thẳng «tôi không muốn» rồi đi","mi",0.500,"Cô đi không ngoảnh lại. Có tiếng xì xào sau lưng nhưng bước chân cô vững.","Cô nói quá cộc, Phương Lạc Nghi ngẩn người, mắt đỏ. Mấy giống cái trừng cô.",{}),
 K17("Dịu giọng nhưng giữ khoảng cách: «Tôi quen ở một mình»","tri",0.510,"Phương Lạc Nghi gật đầu, nụ cười vẫn còn nguyên. Thiết Lan nhìn cô thêm một lần.","Lời dịu dàng nghe như xã giao, Phương Lạc Nghi ngượng ngùng bỏ đi.",{f:"diu_giong",both:1}),
 K17("Gật đầu chào, không nói gì thêm","van",0.490,"Cô gật, rồi quay vào hang. Không ai đoán được cô nghĩ gì.","Cô gật đầu hơi muộn, Phương Lạc Nghi đã rảo bước đi.",{})],
{ctx:"Cửa hang A Kỳ, chiều ngày thứ ba. Phương Lạc Nghi xin làm bạn."}),

Q17("t07","rfire","Bộ lạc Hà Lâm · Trước hang Khắc Cang","chon","Ô Nhã và cô gái lạ",
"Chiều đó, một nhóm giống cái vây quanh trước hang Khắc Cang. Ô Nhã, bạn thân từ nhỏ của cô, giống cái đẹp nhất bộ lạc, thích Khắc Cang từ lâu, vừa đi xa về, nghe tin Khắc Cang đã chọn người liền chặn Phương Lạc Nghi, chê cô ta quá yếu, không xứng. Phương Lạc Nghi nhìn sang cầu cứu A Kỳ. Mặc Hạo, thủ lĩnh và đệ nhất dũng sĩ hóa sói đen, cùng Thiết Nham, dũng sĩ thứ ba hóa hổ, tới can; cả hai đều để ý cô gái lạ. Cô có thể lên tiếng bênh Phương Lạc Nghi, hoặc lặng im.",
"Bênh một người là bỏ rơi một người. Cân đo trước khi mở miệng.",
"tk_ky,tk_onha,tk_nghi,tk_hao,tk_nham,tk_cang,tc",[
 K17("Lên tiếng: «Đừng ép cô ấy, chẳng ai chọn được ai thích»","mi",0.500,"Ô Nhã khựng lại, vẫn giận nhưng buông tay. Mặc Hạo nhìn cô, gật đầu rất khẽ.","Ô Nhã hiểu nhầm cô phản bạn, trừng mắt: «Cậu đứng về phía ai?». Cô bị bỏ lại với hai lời giải thích dang dở.",{f:"benh_nghi",both:1}),
 K17("Lặng im, đứng nhìn Mặc Hạo can","van",0.520,"Mặc Hạo ngăn được cuộc cãi. Cô đứng ngoài cuộc, tránh được một trận giận.","Cô đứng im quá lâu, Phương Lạc Nghi nhìn cô với ánh mắt thất vọng.",{}),
 K17("Kéo Ô Nhã ra chỗ khác: «Đi với tớ, nói chuyện riêng»","tri",0.490,"Ô Nhã đi theo, vừa đi vừa càu nhàu nhưng bớt hẳn giận.","Ô Nhã hất tay cô ra: «Cậu cũng đứng về phía cô ta à?».",{})],
{ctx:"Trước hang Khắc Cang, chiều muộn. Ô Nhã chặn Phương Lạc Nghi, Mặc Hạo và Thiết Nham tới can."}),

Q17("t08","rfair","Bộ lạc Hà Lâm · Sân ngoài bộ lạc","chon","Chiếc vòng cổ của thủ lĩnh",
"Chiều muộn, Mặc Hạo đưa cô một chiếc vòng cổ xương đẹp. Anh báo hai bộ lạc bạn, Thanh Hồ của Cự Nha và Phi Ưng của Ưng Dực, đã nhận cùng chống thú triều năm nay, rồi hỏi cô đã để ý giống đực nào chưa. Cô biết anh từng nói sẽ chờ cô, và rồi sẽ quên khi Phương Lạc Nghi chiếm lòng anh. Cô đáp «có». Ô Nhã nghe được, sáng hôm sau gặng hỏi suốt. Cô có thể nói thật với Ô Nhã đó là Bạch Triệt, hoặc chỉ nói «có rồi, đừng hỏi».",
"Vòng cổ này là lời hứa của anh ta. Ngươi biết hứa này sẽ gãy ra sao.",
"tk_ky,tk_hao,tk_onha,tk_triet,tc",[
 K17("Nói thật với Ô Nhã: «Là Bạch Triệt»","tri",0.510,"Ô Nhã há hốc miệng, rồi ôm cô cười thành tiếng. «Chọn gì mà liều thế!»","Ô Nhã không tin, bật cười: «Đại Tư Tế á? Cậu nói đùa». Chuyện này phải giải thích lại.",{f:"noi_that_8"}),
 K17("Chỉ nói «có rồi, đừng hỏi»","van",0.500,"Ô Nhã dừng hỏi, nhưng ánh mắt đã đoán ra bảy phần.","Ô Nhã càng tò mò hơn, theo cô cả buổi, cô bực hơn dự tính.",{}),
 K17("Trả lại chiếc vòng cho Mặc Hạo, nói cô không nhận","mi",0.480,"Mặc Hạo nhận lại, im lặng. Anh hiểu cô nói gì, dù không nói ra.","Mặc Hạo nhăn mặt, nói «cứ giữ đấy», rồi bỏ đi. Cô cầm vòng như cầm một cục than.",{})],
{ctx:"Sân ngoài bộ lạc, chiều muộn. Mặc Hạo tặng vòng cổ xương và hỏi chuyện giống đực."}),

/* ---- Chương 2: Sơn bụng (mốc 9–17) ---- */
Q17("t09","rcave","Bộ lạc Hà Lâm · Hang của Ô Nhã","chon","Lời khuyên cho Ô Nhã",
"Sáng hôm sau, Ô Nhã đang chọn da thú, vẫn bực vì Khắc Cang đã có người. Cô nhớ trong truyện gốc Ô Nhã sẽ chết khi cố bảo vệ Khắc Cang và Phương Lạc Nghi, rồi bị bỏ lại. Cô khuyên bạn đừng ép Khắc Cang: hãy ra các bộ lạc khác tìm một dũng sĩ mạnh hơn, bộ lạc sẽ có thêm người bảo vệ. Ô Nhã bừng sáng, sắm váy da và sáng hôm sau lên đường. Cô có thể khuyên bạn đi tìm, hoặc khuyên ở lại chờ Khắc Cang.",
"Nàng sống hay chết là do một câu của ngươi. Chọn cho kỹ.",
"tk_ky,tk_onha,tk_cang,tc",[
 K17("Khuyên Ô Nhã đi các bộ lạc khác tìm dũng sĩ mạnh hơn","mi",0.510,"Ô Nhã ôm cô thật chặt: «Cậu nói đúng!». Hôm sau cô ấy lên đường, váy da bay trong gió.","Ô Nhã nghi ngờ lời cô, nhưng vẫn bước đi, nửa tin nửa không.",{f:"onha_di",both:1,bonus:fl17("benh_nghi",-.05)}),
 K17("Khuyên ở lại, chờ Khắc Cang đổi ý","van",0.490,"Ô Nhã thở dài, gật đầu. Cô ấy ở lại, nhưng ánh mắt vẫn nhìn về hang Khắc Cang.","Ô Nhã giận dỗi: «Cậu không muốn tớ đi hả?». Cả buổi hai người không nói với nhau.",{f:"onha_o",both:1,bonus:fl17("benh_nghi",-.05)}),
 K17("Nói thật: «Tớ có linh cảm Khắc Cang không hợp với cậu»","tri",0.500,"Ô Nhã im lặng khá lâu, rồi gật. Cô ấy quyết định đi, mang theo lời cô.","Ô Nhã bật cười: «Cậu có linh cảm gì chứ». Cuộc nói chuyện kết thúc chưa ai thuyết phục được ai.",{f:"onha_di",both:1,bonus:fl17("benh_nghi",-.05)})],
{ctx:"Hang của Ô Nhã, sáng hôm sau. A Kỳ khuyên bạn thân về chuyện Khắc Cang."}),

Q17("t10","rfire","Bộ lạc Hà Lâm · Bãi đất giữa bộ lạc","chon","Hai dũng sĩ đánh nhau",
"Chiều vài ngày sau, Thiết Nham nói Phương Lạc Nghi không thuộc riêng ai; Khắc Cang đáp bằng nắm đấm. Phương Lạc Nghi chạy vào cản, rồi đỡ lấy Thiết Nham, khiến Khắc Cang đỏ mắt. Mặc Hạo bắt cả hai về. Thiết Lan ngồi xa, như mong chuyện này lớn thêm. Bạch Triệt băng vết thương cho Thiết Nham; cô đứng phụ. Thiết Lan lại thì thầm bên tai cô: «Khắc Cang ra tay độc quá». Cô có thể cùng chê Khắc Cang, hoặc im lặng giúp băng.",
"Thiết Lan muốn ngươi nói câu đó để nàng đem đi kể lại. Đừng đưa lời cho nàng.",
"tk_ky,tk_nham,tk_cang,tk_nghi,tk_hao,tk_triet,tk_lan,tc",[
 K17("Im lặng giúp Bạch Triệt băng vết thương","van",0.510,"Cô đưa lá thuốc đúng lúc, giữ chặt đúng chỗ. Anh khẽ gật đầu cảm ơn.","Cô băng hơi lỏng, Bạch Triệt lặng lẽ băng lại, không trách.",{}),
 K17("Cùng Thiết Lan chê Khắc Cang ra tay độc","mi",0.470,"Thiết Lan mỉm cười hài lòng. Cô thấy mình vừa nói một câu thừa.","Câu nói của cô truyền đi nhanh hơn dự tính. Khắc Cang nhìn sang, ánh mắt tối lại.",{b:[0,2,0,-3]}),
 K17("Nhìn ngang sang chỗ khác, giả vờ không nghe","tri",0.500,"Thiết Lan hết chuyện để nói, bỏ đi chỗ khác. Cô thở ra nhẹ nhõm.","Thiết Lan lặp lại ba lần, vẫn không thôi. Cô đành đứng nghe.",{})],
{ctx:"Bãi đất giữa bộ lạc, chiều vài ngày sau. Khắc Cang và Thiết Nham đánh nhau."}),

Q17("t11","rcave","Bộ lạc Hà Lâm · Ngoài thạch ốc Bạch Triệt","chon","Cấm nhìn Khắc Cang",
"Vài ngày sau, mỗi ngày cô tới ngồi xem anh nghiền thuốc. Bạch Triệt nghiêm mặt: «Khắc Cang đã có người, em đừng nhìn anh ta nữa». Cô hiểu anh đang ghen, bật cười và đáp «từ nay em chỉ nhìn anh». Anh đỏ tai, bảo cô hiểu chuyện. Cô có thể nói thật rằng mình chẳng để ý Khắc Cang chút nào, hoặc trêu thêm cho anh đỏ tai.",
"Anh nghiêm túc hơn ngươi tưởng. Anh ghen và không biết gọi nó là gì.",
"tk_ky,tk_triet,tk_cang,tc",[
 K17("Nói thật: «Em chưa bao giờ để ý anh ta»","tri",0.510,"Anh im lặng, rồi khẽ thở ra. «Thế thì tốt», anh nói với cái cối thuốc.","Anh nghe xong nhưng vẫn cúi gằm mặt. Cô phải nói thêm một lần.",{f:"noi_that_11",g:[-3,-2,8,2]}),
 K17("Trêu thêm: «Vậy anh ghen à?»","mi",0.480,"Anh nghiêm mặt, tai đỏ rực. «Không có», anh đáp, nhưng tay nghiền thuốc nhanh hơn.","Anh đặt cối xuống, im lặng đi vào trong. Cô nghĩ mình trêu hơi quá.",{}),
 K17("Ngồi xuống nghiền thuốc cùng anh, không nói gì","van",0.500,"Hai người nghiền thuốc cả buổi. Khi cô đứng dậy, anh khẽ nói: «Mai lại đến».","Cô nghiền quá mạnh, thuốc bắn tung. Anh nhìn cô, khóe miệng giật giật.",{})],
{ctx:"Ngoài thạch ốc Bạch Triệt, vài ngày sau. Anh nói cô đừng nhìn Khắc Cang nữa."}),

Q17("t12","rfire","Bộ lạc Hà Lâm · Cổng sơn động","chon","Phương Lạc Nghi mất tích",
"Mấy ngày sau, trời nhá nhem, Khắc Cang chạy về một mình báo tin: anh và Phương Lạc Nghi đi hái hương liệu rồi lạc nhau. Thiết Nham lao vào đánh anh vì làm mất cô ta. Mặc Hạo can, chia người đi tìm. Các giống cái xì xào «cô ta yếu, chắc chết rồi». Cô biết cô ta vẫn an toàn nhưng chưa thể nói ra. Cô có thể đi tìm cùng đoàn một ngày, hoặc xin đi hái thuốc với Bạch Triệt.",
"Nàng không sao. Nhưng ngươi không thể nói lý do ngươi biết.",
"tk_ky,tk_cang,tk_nham,tk_hao,tk_nghi,tk_triet,tc",[
 K17("Đi tìm cùng đoàn một ngày","van",0.500,"Cô đi cạnh Mặc Hạo, hỏi han từng khe đá. Không ai trách cô thờ ơ.","Cô đi chậm hơn đoàn, bị tụt lại. Mặc Hạo phải quay lại đón.",{}),
 K17("Xin đi hái thuốc với Bạch Triệt, nói thú triều sắp tới","tri",0.520,"Mặc Hạo gật đầu ngay. «Việc đó cũng quan trọng.»","Mặc Hạo cau mày, không phản đối nhưng cũng không đồng ý ngay.",{f:"khong_tim",both:1}),
 K17("Ở lại trông các giống cái và trẻ nhỏ","mi",0.490,"Các giống cái bớt hoảng hơn khi có cô ở cạnh. Không ai nhắc chuyện cô không đi tìm.","Vài giống cái liếc cô, thì thầm: «Cô ta lạnh lùng thật».",{f:"khong_tim",both:1})],
{ctx:"Cổng sơn động, trời nhá nhem. Khắc Cang báo Phương Lạc Nghi mất tích."}),

Q17("t13","rhill","Chân núi · Bãi hái thuốc","duyen","Bức vẽ thảo dược",
"Hôm sau, Bạch Triệt tính thú triều sắp tới nên cần thêm thuốc. Cô đi cùng; anh dạy cô nhận từng loại. Cô vẽ ký hiệu từng loại lên da thú bằng văn tự bộ lạc, điều chưa ai nghĩ ra. Anh đọc từ đầu đến cuối rồi sững người. Cô giấu một điều: cô vừa thấy một khe gió thổi ra từ chân núi, đúng chỗ cô nhớ trong truyện gốc. Cô có thể dẫn anh tới khe gió, hoặc tiếp tục hái thuốc.",
"Anh nhìn bức vẽ như nhìn một phép lạ. Đừng hủy nó vì khiêm tốn.",
"tk_ky,tk_triet,tc",[
 K17("Dẫn anh tới khe gió, nói «em thấy gió thổi từ đây»","tri",0.510,"Anh áp tay vào đá, rồi gật chậm. «Đúng là có hang.» Anh nhìn cô lâu hơn.","Cô chỉ nhầm hướng, phải vòng qua hai bụi cỏ mới tìm lại đúng chỗ.",{f:"chi_khe_gio"}),
 K17("Tiếp tục hái thuốc, để khe gió cho ngày mai","van",0.500,"Cô hái đầy giỏ. Tối đó cô vẫn thấy khe gió trong mắt.","Cô vô ý hái nhầm một loại độc nhẹ, anh phát hiện kịp, nghiêm giọng dặn lại.",{}),
 K17("Hỏi anh về những loại cô chưa biết, vẽ thêm vào bản","mi",0.490,"Anh kể mỗi loại một câu chuyện nhỏ. Bản vẽ thêm đầy, anh cũng nói nhiều hơn thường ngày.","Anh trả lời ngắn gọn, đoán cô mệt. Cô cười, nói không sao.",{})],
{ctx:"Chân núi, hôm sau. A Kỳ và Bạch Triệt đi hái thuốc.",learn:{n:"Viết văn tự bộ lạc",s:"tri",v:2}}),

Q17("t14","rhill","Chân núi · Lối qua bụi cỏ","hiem","Cái hang sau bụi cỏ",
"Cùng ngày, sợ cô lạc, Bạch Triệt nắm tay cô suốt đường. Sau lớp cỏ dày là một khe hang cao bằng người; bên trong là lối hẹp dẫn vào sơn bụng: hai khoảng rộng, phía trên có khe hở lọt ánh sáng. Anh nhận ra nơi này có thể chứa cả bộ lạc khi thú triều tới. Đá trên trần có vẻ lỏng. Cô có thể chui vào dò trước, hoặc để anh đi trước.",
"Đá lỏng thì phải đi nhẹ. Đừng để anh đi trước mà ngươi cũng đừng đi trước một cách liều.",
"tk_ky,tk_triet,tc",[
 K17("Chui vào dò trước, bảo anh đứng ngoài","van",0.480,"Cô lách người qua khe hẹp, gõ đá thử từng chỗ. Trần hang vững hơn cô sợ.","Một mảng đá bên trên rơi xuống đúng lúc cô bước vào, sượt qua vai.",{b:[-1,1,0,-6]}),
 K17("Để anh đi trước, cô theo sát phía sau","mi",0.520,"Anh đi trước từng bước, tay vẫn nắm tay cô. Hang không có gì nguy hiểm.","Anh đi chậm quá, đá nhỏ rơi rào rào, cô phải kéo anh lùi lại.",{}),
 K17("Cùng gõ đá thử từng bước, đi song song","tri",0.500,"Hai người gõ đá, lắng tiếng vang, chọn từng bước. Lối vào sơn bụng hiện ra.","Tiếng vang lẫn lộn làm hai người mất phương hướng một lúc.",{})],
{ctx:"Chân núi, cùng ngày. Khe hang sau bụi cỏ dẫn vào sơn bụng."}),

Q17("t15","rforest","Chân núi · Bãi cỏ cao","chon","Tiếng động sau bụi cỏ",
"Chiều tối, trên đường về, họ nghe giọng Phương Lạc Nghi, rồi thấy Huyền Lâm, một người Xà tộc cao gầy, dắt cô ta đi. Cô ta cười, nép vào anh, không hề bị ép buộc. Bạch Triệt khẽ hỏi có nên báo Khắc Cang không. Anh nói trước giờ anh chưa nghĩ tới chuyện kết đôi, nhưng giờ thì có. Cô có thể báo Khắc Cang ngay, hoặc để họ tự giải quyết rồi hỏi anh định kết đôi với ai.",
"Chuyện của họ là chuyện của họ. Chuyện của ngươi và anh mới là chuyện ngươi cần nghe.",
"tk_ky,tk_triet,tk_nghi,tk_lam,tk_cang,tc",[
 K17("Để họ tự giải quyết, hỏi anh: «Anh định kết đôi với ai?»","mi",0.500,"Anh nhìn cô thật lâu, rồi quay mặt đi: «Em biết rồi còn hỏi». Tai anh đỏ tới tận cổ.","Cô hỏi hơi sớm, anh nghe thành đùa. Anh đáp «để sau», nhưng ngón tay siết lại.",{f:"hoi_ket_doi",g:[-3,-2,9,2]}),
 K17("Báo Khắc Cang ngay, để anh ta tự quyết","tri",0.480,"Khắc Cang nghe xong thì sững người, rồi nắm cổ áo Huyền Lâm. Chuyện ầm ĩ nhưng rõ ràng.","Khắc Cang không tin, lại nổi giận với cô. Cô đứng giữa hai người đang gầm gừ.",{}),
 K17("Lặng lẽ kéo Bạch Triệt đi khuất, không nói gì với ai","van",0.510,"Hai người rời bãi cỏ yên lặng. Trên đường về, anh nắm tay cô chặt hơn.","Cô giẫm phải cành khô, tiếng gãy vang cả bãi cỏ. Huyền Lâm quay đầu nhìn.",{})],
{ctx:"Bãi cỏ cao ngoài chân núi, chiều tối. Họ thấy Huyền Lâm cùng Phương Lạc Nghi."}),

Q17("t16","rfire","Bộ lạc Hà Lâm · Sân bộ lạc, lửa mừng","chon","Tin vui và lửa mừng",
"Hôm sau, Bạch Triệt cùng Mặc Hạo công bố sơn bụng và nói người tìm ra là A Kỳ. Cả bộ lạc reo mừng. Đêm đó họ đốt lửa lớn, mặc váy da đẹp nhất, hát những khúc ca cổ quanh đống lửa. Mặc Hạo chuyền cho cô bát nước hoa quả. Cô có thể nhận lời khen để bộ lạc nhớ ơn mình, hoặc đẩy công sang Bạch Triệt.",
"Ơn thì nhớ, nhưng công cũng gây ghen. Cả hai đều có lợi và hại.",
"tk_ky,tk_triet,tk_hao,tk_lan,tc",[
 K17("Nhận lời khen: «Đúng, em tìm thấy»","mi",0.510,"Cả sân reo lên. Bà lão kéo cô vào lòng: «Con gái thủ lĩnh quả không phụ cha mẹ».","Tiếng reo lẫn tiếng xì xào. Có người nhìn cô với ánh mắt dò xét.",{f:"nhan_cong",both:1}),
 K17("Đẩy công sang Bạch Triệt: «Đại Tư Tế cùng em tìm»","van",0.500,"Anh nhìn cô lạ lẫm rồi gật đầu. Dân bộ lạc ca ngợi cả hai.","Anh lúng túng vì bị khen, đỏ tai, trốn ra sau tảng đá.",{}),
 K17("Chia đều: «Cả hai người tìm, nhờ gió chỉ đường»","tri",0.490,"Cả sân cười ồ. Câu đùa vừa vặn, không ai nhớ ai công nhiều hơn.","Câu đùa không ai hiểu, sân yên lặng một nhịp.",{})],
{ctx:"Sân bộ lạc, tối hôm sau. Bộ lạc đốt lửa mừng sơn bụng."}),

Q17("t17","rcave","Sơn bụng · Các hốc mới đục","duyen","Dọn vào sơn bụng",
"Mấy ngày sau, sơn bụng đã đục thêm các hốc nhỏ để ở. Cả bộ lạc dọn vào, chia hốc theo từng nhà; cô chọn hốc cạnh Bạch Triệt. Khắc Cang, Phương Lạc Nghi và Huyền Lâm cũng về. Cô đẩy một tấm đá khoét cửa nhỏ giữa hốc mình và hốc anh; anh không bịt, chỉ treo một tấm da. Cô có thể đi qua cửa đó mỗi tối, hoặc chỉ để mở.",
"Cánh cửa nhỏ này là lời hẹn đầu tiên của hai người. Đừng vội mà cũng đừng chậm.",
"tk_ky,tk_triet,tk_onha,tk_mich,tk_khue,tk_cang,tk_nghi,tk_lam,tc",[
 K17("Đi qua cửa nhỏ mỗi tối, mang canh sang cho anh","mi",0.500,"Mỗi tối, tấm da khẽ lay và có người đặt một bát canh nóng. Anh quen dần với điều đó.","Có tối cô sang đúng lúc anh đang ngủ, bát canh nguội ngắt. Cô để lại rồi lẳng lặng về.",{f:"qua_cua_nho"}),
 K17("Chỉ để cửa mở, chờ anh tự bước sang","van",0.510,"Một tối nọ, tấm da lay nhẹ từ phía bên kia. Anh đứng đó, tay cầm cuộn da thuốc.","Hai đêm trôi qua, không ai bước sang. Cô nằm nhìn tấm da, đợi.",{}),
 K17("Giúp Ô Nhã và các bạn dọn hốc, tối mới sang","tri",0.490,"Cô chia việc rõ ràng, hốc nào xong hốc đó. Cuối ngày anh đã đợi sẵn một bát nước ấm.","Cô dọn hốc quá lâu, tới khi sang thì anh đã ngủ.",{})],
{ctx:"Sơn bụng, mấy ngày sau. Cả bộ lạc dọn vào ở.",}),

/* ---- Chương 3: Thú triều (mốc 18–25) ---- */
Q17("t18","rcave","Sơn bụng · Họp bàn trước thú triều","chon","Đề nghị của Phương Lạc Nghi",
"Vài ngày sau, họp bàn trước thú triều, Phương Lạc Nghi đề nghị cho hai bộ lạc bạn, Thanh Hồ và Phi Ưng, vào ở chung và đục thêm hốc. Mặc Hạo gật đầu. Cô chen vào: đục thêm quá nhiều thì sơn thể sẽ sập. Phương Lạc Nghi xin lỗi, mắt đỏ; vài người nhìn cô như thể cô cản đường. Cuối cùng họ chọn cách dồn người vào chung hốc. Cô có thể giải thích cặn kẽ vì sao sơn thể sẽ sập, hoặc nói gọn một câu.",
"Nàng không xấu. Nàng chỉ không biết núi. Ngươi biết, nên nói cho đủ mà đừng nói cho gắt.",
"tk_ky,tk_nghi,tk_hao,tc",[
 K17("Giải thích cặn kẽ: hốc nào chịu lực, hốc nào không","tri",0.500,"Cô vẽ lên đất từng lớp đá. Mặc Hạo nhìn rất lâu rồi gật. Không ai cãi được nữa.","Cô nói dài quá, nhiều người ngáp. Vài ánh mắt nhìn cô như người bới móc.",{f:"giai_thich_18"}),
 K17("Nói gọn một câu: «Đục thêm là sập, dồn người thì an toàn»","mi",0.510,"Câu nói ngắn mà chắc. Mặc Hạo gật đầu đồng ý ngay, Phương Lạc Nghi cũng thôi đòi.","Câu nói quá cộc, Phương Lạc Nghi khẽ run vai. Ánh mắt bộ lạc đổ về phía cô.",{}),
 K17("Nhờ Bạch Triệt xem mạch núi rồi nói thay cô","van",0.490,"Anh nói ngắn gọn, mọi người nghe. Cô đứng sau anh, nhẹ gánh.","Bạch Triệt đi hái thuốc chưa về, cô phải quay lại một mình, vẫn chưa nói hết ý.",{})],
{ctx:"Sơn bụng, vài ngày sau. Họp bàn trước khi hai bộ lạc bạn vào ở."}),

Q17("t19","rtop","Đỉnh núi và chân núi","duyen","Hố bẫy và lăn thạch",
"Vài ngày sau, cô cùng Bạch Triệt leo núi và thấy đã chất sẵn đá lớn bé. Dưới lớp bùn, cô nhặt được một thanh đại đao rỉ sét vẫn chém đứt được cây gậy. Cô vạch kế hoạch: đào hố sâu quanh chân núi, cắm cọc nhọn gọt bằng đại đao, đẩy lăn thạch từ trên cao xuống. Bạch Triệt khen «A Kỳ thật có trí tuệ». Mặc Hạo cho cả bộ lạc đào hố. Cô có thể đích thân chỉ cách đào, hoặc giao việc cho các dũng sĩ.",
"Một cái hố đúng chỗ giá trị hơn mười dũng sĩ đứng đúng chỗ. Hố thì không biết sợ.",
"tk_ky,tk_triet,tk_hao,tc",[
 K17("Đích thân chỉ cách đào: sâu, rộng, cọc hướng nào","tri",0.510,"Cô cầm gậy vẽ từng đường. Các dũng sĩ đào theo, hố nào hố nấy thẳng tắp.","Cô tính nhầm độ sâu, phải đào lại hai hố đầu. Dũng sĩ càu nhàu nhưng làm lại.",{f:"chi_dao_ho"}),
 K17("Giao việc cho các dũng sĩ, cô kiểm tra mỗi ngày","mi",0.500,"Cô đi dọc chân núi mỗi chiều, khen đúng chỗ, sửa đúng chỗ. Hố đào nhanh hơn dự tính.","Có hai nhóm hiểu nhầm lệnh, đào hố trùng chỗ. Cô mất nửa ngày chỉnh lại.",{}),
 K17("Cùng Bạch Triệt gọt cọc, chia việc với bầy giống cái","van",0.490,"Hai người gọt cọc suốt buổi. Các giống cái tới phụ, hố bẫy thành hình nhanh hơn.","Đại đao nặng tay, cô gọt lệch cọc. Anh thay cô gọt lại.",{})],
{ctx:"Đỉnh núi và chân núi, vài ngày sau. Cô vạch kế hoạch hố bẫy và lăn thạch.",learn:{n:"Đào hố bẫy",s:"tri",v:2}}),

Q17("t20","rfire","Sơn bụng · Bếp chung","chon","Lời đồn đầu tiên",
"Vài ngày sau, ở bếp chung của sơn bụng, Phương Lạc Nghi dạy cả bộ lạc làm giày bằng da và gỗ, ai cũng mến. Thiết Lan lan lời đồn «A Kỳ ghét Phương Lạc Nghi vì cô ta cướp nổi bật», rồi rủ cô đi bảo Phương Lạc Nghi đừng giành hốc với bộ lạc mình. Cô từ chối. Thiết Lan hậm hực bỏ đi, lời đồn lan thêm. Cô có thể lờ đi, hoặc nói rõ trước mọi người rằng không có chuyện đó.",
"Lời đồn là thứ càng lờ càng lớn, càng cãi càng đúng. Chọn cách ít tệ hơn.",
"tk_ky,tk_lan,tk_nghi,tc",[
 K17("Lờ đi, tiếp tục làm việc của mình","van",0.500,"Cô đi qua bếp mỗi ngày, mặt không đổi sắc. Dần dần ít người nhắc lại.","Cô lờ quá lâu, lời đồn đã mọc thêm vài ngọn mới.",{bonus:bn17(fl17("diu_giong",.05),fl17("nhan_cong",-.05),fl17("onha_o",-.04))}),
 K17("Nói rõ trước mọi người: «Tôi chưa từng ghét cô ấy»","mi",0.490,"Cô nói bình thản, không giận dỗi. Vài người gật đầu. Phương Lạc Nghi nhìn cô, ánh mắt phức tạp.","Cô nói ra thì đúng, mà nghe như biện hộ. Thiết Lan mỉm cười như đã đợi câu này.",{bonus:bn17(fl17("diu_giong",.05),fl17("nhan_cong",-.05),fl17("onha_o",-.04))}),
 K17("Hỏi thẳng Thiết Lan lời đồn từ đâu ra, trước mặt người khác","tri",0.480,"Thiết Lan đỏ mặt, lắp bắp. Lời đồn mất chỗ đứng chỉ trong một buổi.","Thiết Lan khóc, nói cô ép người. Cả bếp quay sang an ủi nàng.",{b:[0,2,0,-3],bonus:bn17(fl17("diu_giong",.05),fl17("nhan_cong",-.05),fl17("onha_o",-.04))})],
{ctx:"Bếp chung sơn bụng, vài ngày sau. Thiết Lan lan lời đồn về A Kỳ."}),

Q17("t21","rtop","Đỉnh núi · Sáng sớm","hiem","Thú triều đầu tiên",
"Sáng sớm, đất rung từ xa; một bầy thú cuồng điên lao về phía núi, rơi xuống hố sâu và gục trên cọc. Trước giờ giao chiến, Bạch Triệt nói «người anh muốn kết đôi là em»; cô nhận lời. Mười mấy con còn lại vòng ra sau núi; cô và anh đẩy lăn thạch xuống kịp. Cô có thể đẩy đá ngay, hoặc chờ chúng xông lên gần hơn cho trúng.",
"Chờ đến lúc đá rơi trúng thì cũng là lúc thú tới sát chân ngươi. Đừng tham.",
"tk_ky,tk_triet,tc",[
 K17("Đẩy đá ngay khi chúng vừa vòng ra sau núi","van",0.520,"Đá lăn rầm rập, đè bẹp đường vòng của bầy thú. Cô ngã ngồi, thở hổn hển, tay vẫn nắm tay anh.","Đá lăn hơi sớm, một nửa trật đích. Anh phải xông ra chặn đường những con còn lại.",{bonus:sk17("Đào hố bẫy",.09)}),
 K17("Chờ chúng xông lên gần hơn rồi mới đẩy","tri",0.480,"Đá rơi đúng khoảnh khắc. Cả đợt thú ngã xuống, im lặng hẳn.","Đá lăn muộn một nhịp, bầy thú đã sát sườn. Một con vồ trúng vai cô.",{b:[-1,1,0,-8],bonus:sk17("Đào hố bẫy",.09)}),
 K17("Gọi Bạch Triệt cùng đẩy, đếm nhịp thật rõ","mi",0.500,"Hai người đẩy đồng nhịp. Tảng đá thứ nhất rơi, tảng thứ hai theo sau, không sót.","Tiếng gọi bị tiếng thú gầm át, anh đẩy trước cô một nhịp, một tảng đá lăn lệch.",{bonus:sk17("Đào hố bẫy",.09)})],
{ctx:"Đỉnh núi, sáng sớm. Thú triều đầu tiên lao về phía núi."}),

Q17("t22","rtop","Đỉnh núi · Cuối nửa tháng thú triều","nan","Bạch Triệt ra đi",
"Cuối nửa tháng thú triều, không ai chết. Bạch Triệt kể: cha anh, Bạch Hàn, từng nhận ra thú triều không tự nhiên rồi mất tích. Anh đã theo dấu thú năm năm và lần này phải đi tiếp. Anh hôn lên trán cô, hóa tuyết lang chạy vào rừng. Cô có thể hứa chờ và dặn anh quay về, hoặc đòi theo.",
"Anh phải đi, và ngươi không giữ được. Nhưng lời ngươi để lại sẽ là thứ anh nắm chặt nhất.",
"tk_ky,tk_triet,tk_han,tc",[
 K17("Hứa chờ anh, dặn anh nhất định quay về","mi",0.500,"Anh nhìn cô thật lâu, rồi nói rất khẽ: «Anh sẽ về.» Tuyết lang biến vào rừng, lời hứa còn lại trong gió.","Giọng cô run quá, anh phải ôm cô một lúc mới đi được. Cô nhìn theo cho tới khi hết bóng.",{f:"hua_cho",both:1,g:[-3,0,4,2],b:[-1,1,0,-3]}),
 K17("Đòi đi cùng, nói không muốn bị bỏ lại","van",0.470,"Anh lắc đầu, hôn lên trán cô lần nữa: «Chỗ đó nguy hiểm.» Cô đành đứng nhìn.","Cô túm áo anh, anh nhẹ nhàng gỡ ra. Cô thấy tay mình trống rỗng.",{}),
 K17("Đưa anh thuốc và lương khô cô chuẩn bị sẵn","tri",0.510,"Anh nhận túi, giữ thật chặt trong tay. «Có em ở đây là đủ rồi», anh nói.","Cô đưa muộn, anh đã hóa thú, phải đuổi theo mới đặt được túi vào miệng anh.",{})],
{ctx:"Đỉnh núi, cuối nửa tháng thú triều. Bạch Triệt hóa tuyết lang ra đi.",forced:1,fix:w17spikeK("s22","hua_cho")}),

Q17("t23","rcave","Sơn bụng · Ba bộ lạc","hiem","Ba bộ lạc dưới một mái núi",
"Ít ngày sau, sơn bụng quá chật. Cự Nha, thủ lĩnh Thanh Hồ, bị Phương Lạc Nghi từ chối thì nổi giận, đòi đuổi Hà Lâm ra khỏi hang. Ưng Dực, thủ lĩnh Phi Ưng, quay sang bảo vệ Phương Lạc Nghi, gia nhập Hà Lâm làm phó thủ lĩnh và cùng Mặc Hạo đuổi Cự Nha cùng bộ lạc Thanh Hồ đi. Cô thấy thêm một dũng sĩ nghiêng về phía Phương Lạc Nghi. Cô có thể đứng ngoài, hoặc lên tiếng ủng hộ Mặc Hạo.",
"Ngươi không cần thắng cuộc cãi này. Ngươi chỉ cần bộ lạc còn nguyên vẹn.",
"tk_ky,tk_nha,tk_duc,tk_hao,tk_nghi,tc",[
 K17("Đứng ngoài, quan sát và ghi nhớ","tri",0.500,"Cô nhìn ra ai thật sự muốn đánh, ai chỉ muốn dọa. Cuộc cãi tự hạ nhiệt.","Cô đứng quá gần Cự Nha, bị xô trúng vai, loạng choạng.",{}),
 K17("Lên tiếng ủng hộ Mặc Hạo: «Hà Lâm cho các anh chỗ ở, không phải đất cắm dùi»","mi",0.490,"Cả sơn bụng im phăng phắc. Mặc Hạo nhìn cô, gật đầu. Cự Nha lầm bầm rồi lùi bước.","Cự Nha quay lại trừng cô, tay đã đặt lên cán rìu. Mặc Hạo phải chắn trước.",{b:[-1,1,0,-6]}),
 K17("Kéo Ô Nhã và các giống cái ra góc trong, tránh vạ lây","van",0.510,"Các giống cái và trẻ nhỏ lùi vào góc an toàn. Cuộc đối đầu ở ngoài kết thúc không đổ máu.","Cô chia người chưa kịp thì cãi đã nổ. Một nửa giống cái đứng giữa vòng xung đột.",{})],
{ctx:"Sơn bụng, ít ngày sau. Cự Nha đòi đuổi Hà Lâm, Ưng Dực quay sang phía Phương Lạc Nghi."}),

Q17("t24","rcave","Sơn bụng · Hốc của Ô Nhã","chon","Dặn Ô Nhã đừng ra ngoài",
"Tối trước ngày đi hái, Phương Lạc Nghi xin Mặc Hạo cho đoàn đi tìm hương liệu mới; Mặc Hạo, Khắc Cang, Thiết Nham và Ưng Dực cùng đi. Cô sang dặn Ô Nhã: ngày mai ở yên, đừng cho ai ra ngoài. Ô Nhã tin cô. Nếu Ô Nhã đã có Hồ Mịch và Hồ Khuê bên cạnh, hai người nhìn nhau: A Kỳ biết điều gì đó. Cô có thể kể cho Ô Nhã lý do, hoặc chỉ bảo «tin tớ».",
"Ngươi không thể nói cô biết trước tương lai. Nhưng ngươi có thể nói ngươi lo.",
"tk_ky,tk_onha,tk_mich,tk_khue,tc",[
 K17("Kể cho Ô Nhã lý do: «Tớ lo cho cả đoàn, đường ngoài kia không yên»","tri",0.500,"Ô Nhã gật chậm. «Tớ hiểu. Cậu không bao giờ lo vu vơ.» Cả nhóm ở yên.","Ô Nhã hỏi dồn, cô trả lời quanh co. Ô Nhã vẫn tin, nhưng nhìn cô lâu hơn thường.",{f:"ke_ly_do_24"}),
 K17("Chỉ nói «tin tớ», không giải thích","mi",0.500,"Ô Nhã nắm tay cô: «Được, tớ tin cậu.» Không cần nói gì thêm.","Ô Nhã cau mày: «Cậu giấu tớ điều gì?». Cô đành lảng sang chuyện khác.",{}),
 K17("Rủ Ô Nhã cùng nấu bữa lớn để cả nhóm ở yên trong hang","van",0.510,"Cả nhóm tụ lại nấu ăn, cười nói cả buổi. Không ai nghĩ đến chuyện ra ngoài.","Bữa ăn bị cháy khét, nhưng mọi người vẫn cười. Ô Nhã vẫn hơi băn khoăn.",{})],
{ctx:"Hốc của Ô Nhã, tối trước ngày đi hái. A Kỳ dặn cô ấy đừng ra ngoài."}),

Q17("t25","rcave","Sơn bụng · Chiều hôm sau","hiem","Ngày cả đoàn lạc đường",
"Chiều hôm sau, đoàn đi tìm hương liệu quay về chật vật, riêng Khắc Cang và Phương Lạc Nghi chưa về. Cả bộ lạc hoảng. Thiết Lan buột miệng «giá mà cô ta không về nữa». Cô đứng lên, lặp lại từng chữ trước mọi người và nhắc họ Phương Lạc Nghi đã cho bộ lạc những gì. Mọi người quay sang quở Thiết Lan. Cô có thể tha cho Thiết Lan sau khi cô ấy xin lỗi, hoặc để lời đồn tự lan.",
"Nói đúng chưa chắc có lợi. Nàng sẽ nhớ cái nhục này rất lâu.",
"tk_ky,tk_lan,tk_nghi,tk_cang,tc",[
 K17("Lặp lại từng chữ của Thiết Lan trước mọi người","mi",0.490,"Cả sơn bụng im lặng. Thiết Lan mặt tái đi, cúi gằm. Không ai bênh nàng.","Cô nói quá cao giọng, vài người nhìn cô như thể cô cũng đang gây chuyện.",{f:"noi_cong_khai_25",both:1,b:[-1,3,0,-5]}),
 K17("Chờ Thiết Lan xin lỗi rồi tha, không làm lớn chuyện","tri",0.510,"Thiết Lan lí nhí xin lỗi. Cô gật đầu, chuyện nhẹ nhàng khép lại. Ô Nhã ôm vai cô.","Thiết Lan xin lỗi bằng giọng chẳng thật lòng. Cô tha, mà biết lời đồn vẫn chưa hết.",{}),
 K17("Để lời đồn tự lan, ra cổng hang chờ hai người về","van",0.500,"Khi cô tới cổng, tiếng bước chân vang trong rừng. Hai bóng người thấp thoáng đi về.","Cô đứng chờ thật lâu, trời tối dần. Vẫn chưa thấy ai.",{})],
{ctx:"Sơn bụng, chiều hôm sau. Khắc Cang và Phương Lạc Nghi chưa về; Thiết Lan lỡ lời."}),

/* ---- Chương 4: Bị giao đi (mốc 26–31) ---- */
Q17("t26","rcave","Sơn bụng · Cổng sơn bụng","hiem","Huyền Lâm trọng thương trở về",
"Chiều hôm sau, Khắc Cang cõng Huyền Lâm đầy vết thương về; Phương Lạc Nghi khóc nức nở. Huyền Lâm đã cứu hai người khỏi một bầy thú dữ. Bạch Triệt chưa về nên không ai chữa được. Phương Lạc Nghi quỳ xin cô; các dũng sĩ nhìn cô chờ đợi. Cô biết nếu chữa dở sẽ bị đổ lỗi. Cô có thể nhận chữa, hoặc từ chối vì mình chưa học đủ.",
"Chữa dở thì bị trách, không chữa thì cũng bị trách. Nhưng chỉ có một lựa chọn cứu được mạng.",
"tk_ky,tk_lam,tk_nghi,tk_cang,tk_hao,tc",[
 K17("Nhận chữa, bảo mọi người lui ra","tri",0.510,"Cô ra lệnh dứt khoát, mọi người lui nhanh. Máu đã ngừng chảy khi cô đặt tay xuống.","Tay cô run, băng đầu tiên quấn sai chỗ. May Khắc Cang đỡ giúp.",{f:"nhan_chua",both:1,bonus:bn17(fl17("khong_tim",-.04),sk17("Giữ mồi lửa",.06))}),
 K17("Từ chối: «Tôi chưa học đủ, chờ Đại Tư Tế về»","van",0.520,"Cô giải thích rõ lý do, nhưng một số dũng sĩ vẫn nhìn cô lạnh lẽo.","Cô nói chưa dứt, Phương Lạc Nghi đã bật khóc to hơn. Cả hang nhìn cô như người máu lạnh.",{f:"tu_choi_26",both:1}),
 K17("Cầm máu tạm thời và cử người đi tìm Bạch Triệt","mi",0.490,"Cô cầm máu đúng chỗ. Hai dũng sĩ chạy đi tìm anh, giữ được thời gian.","Cầm máu chưa chặt, vết thương rỉ máu suốt đêm. Mọi người hoảng thêm.",{bonus:bn17(fl17("khong_tim",-.04))})],
{ctx:"Cổng sơn bụng, chiều hôm sau. Huyền Lâm trọng thương."}),

Q17("t27","rcave","Sơn bụng · Hốc của Phương Lạc Nghi","chon","Chữa cho Huyền Lâm",
"Đêm cùng ngày, trong hốc của Phương Lạc Nghi, cô cầm máu, đun nước sôi rồi rửa vết thương, đắp thảo dược. Có sỏi và mẩu cành kẹt trong da, cần cho Huyền Lâm hóa bản thể để lấy ra. Cô có thể làm đúng quy trình dù mất nhiều thời gian và để người đau thêm một lúc, hoặc làm nhanh cho xong.",
"Đun nước cho sôi là chuyện nhỏ. Bỏ qua nó là chuyện lớn.",
"tk_ky,tk_lam,tk_nghi,tc",[
 K17("Đun nước sôi, rửa sạch và lấy dị vật đúng quy trình","tri",0.500,"Cô làm từng bước, không vội. Huyền Lâm rên khẽ rồi thiếp đi, vết thương sạch.","Cô tính sai thời gian đun, nước nguội phải đun lại. Huyền Lâm đau thêm một lúc.",{f:"chua_ky",both:1,bonus:sk17("Giữ mồi lửa",.09)}),
 K17("Làm nhanh cho xong, băng ngay khi cầm máu","van",0.490,"Vết thương khép lại nhanh, mọi người thở phào. Cô cũng thế.","Cô băng vội, không để ý bên trong còn vật lạ. Huyền Lâm nhíu mày nhưng không nói.",{f:"lam_nhanh",both:1}),
 K17("Hỏi Phương Lạc Nghi cách rửa vết thương ở quê cô ta","mi",0.480,"Phương Lạc Nghi nói về nước muối loãng, cô bắt chước. Vết thương sạch hơn dự tính.","Phương Lạc Nghi nói lan man, cô nghe nửa vời. Cuối cùng vẫn làm theo cách quen.",{f:"lam_nhanh",both:1})],
{ctx:"Hốc của Phương Lạc Nghi, đêm cùng ngày. Cô chữa cho Huyền Lâm.",learn:{n:"Nấu nước sát trùng",s:"tri",v:2}}),

Q17("t28","rfire","Sơn bụng · Sân sơn bụng","hiem","Con xà kêu đau",
"Mười ngày sau, vết thương của Huyền Lâm khép bề mặt nhưng bên trong còn sỏi và gỗ; anh quằn quại, kêu đau suốt đêm. Mặc Hạo trách cô «không kiểm kỹ»; cô đáp mình đâu phải Đại Tư Tế. Họ tự rạch ra lấy dị vật, Huyền Lâm nằm bất động, từ đó hận cô. Cô có thể giúp lấy dị vật để anh đỡ đau, hoặc để họ tự làm.",
"Điều này xảy ra vì ngươi vội. Đừng vội thêm lần nữa.",
"tk_ky,tk_lam,tk_hao,tk_nghi,tc",[
 K17("Giúp lấy dị vật: đun nước, sắp dụng cụ, trấn an anh","tri",0.490,"Cô làm đủ bước, Huyền Lâm hết kêu. Anh nhìn cô lần đầu không giận.","Dị vật ở sâu hơn cô nghĩ, cô phải nhờ Khắc Cang giữ chặt. Huyền Lâm vẫn nhìn cô lạnh.",{bonus:sk17("Nấu nước sát trùng",.09)}),
 K17("Để họ tự làm, cô đứng ngoài trông chừng","van",0.510,"Họ làm xong trong yên lặng. Huyền Lâm thiếp đi, cô thở ra.","Họ rạch lệch, máu chảy nhiều hơn. Cô phải xông vào cầm máu.",{b:[-1,2,0,-5]}),
 K17("Xin lỗi Huyền Lâm: «Tôi chưa kiểm kỹ»","mi",0.500,"Huyền Lâm im lặng, nhìn đi chỗ khác, nhưng bớt căng. Mặc Hạo không trách nữa.","Huyền Lâm bật cười nhạt: «Xin lỗi thì đau có hết không?». Cô chịu trận.",{})],
{ctx:"Sân sơn bụng, mười ngày sau. Vết thương của Huyền Lâm hành đau.",cond:function(){return !!S.f.lam_nhanh},skipWhy:"Cô đã chữa kỹ cho Huyền Lâm ở mốc 27 nên vết thương không hành đau. Huyền Lâm cảm ơn và bớt thù."}),

Q17("t29","rcave","Sơn bụng · Cuối thu","chon","Các dũng sĩ nghiêng về một phía",
"Cuối thu, mùa lạnh sắp tới, Mặc Hạo, Thiết Nham và Ưng Dực lần lượt nói với Phương Lạc Nghi rằng họ muốn ở bên cô ta, ngoài Khắc Cang và Huyền Lâm; không ai đòi cô ta chọn một người. Cả bộ lạc bàn tán: người có ích cho bộ lạc là Phương Lạc Nghi. Thiết Lan châm: «có người sinh ra để được che chở, có người thì không». Mặc Hạo tránh ánh mắt cô; năm xưa anh từng nói sẽ chờ cô lớn. Cô có thể nhắc anh lời năm xưa, hoặc để anh tự nhớ.",
"Lời hứa của anh ta là thứ vỡ đầu tiên. Nhắc cũng không giữ được, nhưng nhắc cho ngươi nhẹ lòng.",
"tk_ky,tk_hao,tk_nham,tk_duc,tk_nghi,tk_lan,tc",[
 K17("Nhắc Mặc Hạo lời năm xưa, bình thản và không trách","mi",0.500,"Mặc Hạo trầm mặt, dặn «đừng nói với ai». Cô gật. Anh không nhìn thẳng cô được nữa.","Cô nhắc quá thẳng, Mặc Hạo cau mày, quay đi. Giữa hai người có một khoảng cách mới.",{f:"nhac_hao",both:1}),
 K17("Để anh tự nhớ, cô không nói gì","van",0.510,"Cô cười nhạt, bước đi. Sau lưng, Mặc Hạo nhìn theo rất lâu.","Cô bước nhanh quá, vấp phải đá, Thiết Lan bật cười.",{}),
 K17("Đi tìm Bạch Triệt trong rừng thay vì ở lại nghe bàn tán","tri",0.480,"Cô ra bìa rừng, ngồi nhìn trời. Đêm đó trăng sáng, cô thấy lòng bớt nặng.","Cô đi lạc nửa buổi, đêm lạnh. Về tới hang trong tình trạng run bần bật.",{b:[-1,1,0,-5]})],
{ctx:"Sơn bụng, cuối thu. Ba dũng sĩ cùng nghiêng về Phương Lạc Nghi."}),

Q17("t30","rhill","Sơn bụng · Trước cổng","nan","Hắc Thạch quốc đến đòi người",
"Giữa trưa, hai trăm dũng sĩ Hắc Thạch cưỡi thú bao vây núi. Quốc vương Hách Lôi nghe tin đồn từ các thương nhân bộ lạc về «cô gái da trắng tên Phương Lạc Nghi», cho ba ngày để giao người; nếu không thì san bằng bộ lạc và bắt các giống cái đi. Đêm đầu Mặc Hạo dẫn bộ lạc rút ra sau núi, bị thú săn của họ chặn: hai thành viên bị thương nặng. Họ rút về và được thêm hai ngày. Cô có thể khuyên đừng chạy nữa, ở lại bàn cách đối phó, hoặc im lặng nghe bộ lạc tự bàn.",
"Hắc Thạch có sắt, gốm, chữ và vua. Hà Lâm chỉ có đá lăn và hố bẫy. Ngươi biết kết quả.",
"tk_ky,tk_loi,tk_hao,tk_nghi,tc",[
 K17("Khuyên: «Chạy không thoát, ở lại bàn cách đối phó»","tri",0.490,"Mặc Hạo nhìn cô, đồng ý. Bộ lạc ở lại cùng bàn, ít nhất không thêm người bị thương.","Ý kiến của cô bị gạt đi. Vài người cho rằng cô sợ nên không chịu chạy.",{bonus:sk17("Đào hố bẫy",.09)}),
 K17("Im lặng nghe bộ lạc tự bàn, đưa ra ý kiến khi được hỏi","van",0.510,"Mặc Hạo cuối cùng quay sang hỏi cô. Cô nói gọn ba điều.","Không ai hỏi cô. Cô nghe họ cãi nhau cả đêm, không đi tới đâu.",{}),
 K17("Giúp chăm sóc hai người bị thương, nấu nước sôi cho họ","mi",0.500,"Cô túc trực bên giường hai người. Một người tỉnh dậy, nắm tay cô nói cảm ơn.","Cô thức quá khuya, sáng hôm sau chóng mặt, đứng không vững.",{bonus:sk17("Nấu nước sát trùng",.09)})],
{ctx:"Cổng sơn bụng, giữa trưa. Hai trăm dũng sĩ Hắc Thạch đến đòi Phương Lạc Nghi."}),

Q17("t31","rcave","Sơn bụng · Đêm cuối hạn","nan","Đêm bị giao đi",
"Đêm cuối hạn, cả bộ lạc họp. Thiết Lan nói «A Kỳ nhỏ gầy, da trắng, giống Phương Lạc Nghi»; vài giọng ngập ngừng, rồi Huyền Lâm tuyên bố nên giao A Kỳ đi. Mặc Hạo không phản đối. Ô Nhã gào lên bênh cô; Hồ Mịch và Hồ Khuê chắn trước cô. Nhưng khuya đó Huyền Lâm vào hốc, đưa cô cho dũng sĩ Hắc Thạch, gọi cô là Phương Lạc Nghi. Cô có thể lén để lại chiếc vòng cổ xương của mẹ cho Bạch Triệt dưới gốc cây ở cửa hang, hoặc mang theo bên mình.",
"Chiếc vòng này là thứ duy nhất anh sẽ tìm thấy. Để lại, và hy vọng nó nói đủ.",
"tk_ky,tk_lan,tk_lam,tk_hao,tk_onha,tk_mich,tk_khue,tk_triet,tc",[
 K17("Lén để chiếc vòng cổ xương của mẹ dưới gốc cây cửa hang","van",0.490,"Cô nhét vòng vào khe rễ, che bằng lá. Dũng sĩ Hắc Thạch không để ý. Cô nhìn gốc cây đến khi khuất.","Cô đặt vòng vội, lá che chưa kín. Cô chỉ có thể hy vọng không ai thấy trước anh.",{f:"de_vong",both:1,bonus:bn17(fl17("noi_cong_khai_25",-.05),fl17("tu_choi_26",-.04),fl17("nhac_hao",-.03))}),
 K17("Mang chiếc vòng theo bên mình, nắm chặt trong lòng bàn tay","mi",0.510,"Cô giữ chặt vòng dưới áo. Nó ấm lên theo hơi cô.","Dũng sĩ Hắc Thạch giật lấy chiếc vòng xem rồi ném lại. Cô nhặt, giấu sâu hơn.",{bonus:bn17(fl17("noi_cong_khai_25",-.05),fl17("tu_choi_26",-.04),fl17("nhac_hao",-.03))}),
 K17("Nhìn Ô Nhã lần cuối, dặn nhỏ: «Đợi tớ. Rồi tìm tớ ở Hắc Thạch»","tri",0.480,"Ô Nhã nghẹn lời, nắm tay cô thật chặt. Cô để lại lời đó, và hy vọng cô ấy giữ.","Dũng sĩ kéo cô đi giữa chừng câu nói. Ô Nhã chỉ nghe được nửa.",{f:"dan_onha",bonus:bn17(fl17("noi_cong_khai_25",-.05),fl17("tu_choi_26",-.04),fl17("nhac_hao",-.03))})],
{ctx:"Sơn bụng, đêm cuối hạn. Bộ lạc giao A Kỳ cho Hắc Thạch."}),

/* ---- Chương 5: Trí giả Hắc Thạch (mốc 32–38) ---- */
Q17("t32","gcarriage","Đường tới Hắc Thạch · Cỗ xe thú","chon","Trên cỗ xe thú",
"Ba ngày đường trên cỗ xe do hai con thú kéo, đoàn dũng sĩ Hắc Thạch đi quanh. Cô tỉnh lại trên xe. Bàng Thích, đệ nhất dũng sĩ của Hách Lôi, lạnh nhạt dặn không được bỏ trốn. Cô xin lửa, nấu canh cho cả đoàn; họ ăn ngon tới quên cả canh chừng. Dần dần họ đối xử tử tế, khoe thành đá, trí giả, quý tộc và nhắc tới Tư Lăng, em trai vua bị đuổi khỏi cung. Bàng Thích vẫn nhìn cô dò xét. Cô có thể nhận lòng tốt của họ để dò tin, hoặc giữ khoảng cách.",
"Ngươi không phải tù nhân mà là một thứ họ chưa biết cách dùng. Đó là chỗ đứng ngươi cần.",
"tk_ky,tk_thich,tk_loi,tk_lang,tc",[
 K17("Nhận lòng tốt của họ, hỏi chuyện Hách Lôi và Tư Lăng","mi",0.500,"Họ nói nhiều hơn dự tính. Cô biết thêm vua thích gì, ghét gì, em vua sợ gì.","Họ chỉ cười, kể chuyện nấu nướng. Cô biết ít hơn cô muốn.",{f:"nhan_long_tot",both:1,bonus:bn17(sk17("Giữ mồi lửa",.06),sk17("Hầm canh xương",.06))}),
 K17("Giữ khoảng cách, nấu canh nhưng ít nói","van",0.510,"Họ ăn canh, vẫn kính cẩn với cô. Bàng Thích nhìn cô ít dò xét hơn.","Cô ít nói quá, đám dũng sĩ cảm thấy cô lạnh nhạt, bớt vồn vã.",{bonus:bn17(sk17("Giữ mồi lửa",.06),sk17("Hầm canh xương",.06))}),
 K17("Quan sát Bàng Thích, đoán xem ông ta nghĩ gì","tri",0.490,"Cô nhận ra ông nhìn cô không phải để canh chừng mà để đánh giá. Cô ghi nhớ.","Bàng Thích bắt gặp cô nhìn, nheo mắt. Cô vội cúi xuống.",{bonus:bn17(sk17("Giữ mồi lửa",.06),sk17("Hầm canh xương",.06))})],
{ctx:"Cỗ xe thú trên đường tới Hắc Thạch, ba ngày đường. Cô nấu canh cho đoàn."}),

Q17("t33","vwall","Hắc Thạch · Cổng thành và vương cung","duyen","Thành đá Hắc Thạch",
"Ngày thứ ba, họ tới cổng thành Hắc Thạch: tường đá, nhà đá, bát gốm; bếp của vua vẫn nướng thịt cháy. Hách Lôi gặp cô, hứa phong quý tộc nếu cô đem «tài trí» tới. Cô dạy bếp vua hầm canh xương, rồi học thợ gốm cách nặn và nung bát. Họ cho người đi theo canh chừng. Cô có thể tỏ ra ngoan ngoãn để Hách Lôi chủ quan, hoặc tỏ ra có ích nhưng khó bảo.",
"Một vị vua thích sự ngoan ngoãn, nhưng chỉ tin người có giá trị. Làm cả hai.",
"tk_ky,tk_loi,tc",[
 K17("Tỏ ra ngoan ngoãn, nhận mọi việc được giao","van",0.500,"Hách Lôi cười hài lòng. Người canh chừng bớt bám sát, cô tự do hơn.","Cô ngoan quá, người canh chừng cho rằng cô giả vờ, bám sát hơn.",{f:"ngoan_ngoan",bonus:sk17("Hầm canh xương",.09)}),
 K17("Tỏ ra có ích nhưng khó bảo: «Tôi dạy, nhưng tôi chọn việc»","mi",0.490,"Hách Lôi nheo mắt, rồi bật cười. «Ta thích người có cốt cách.» Cô giữ được chỗ đứng.","Hách Lôi nhíu mày. Cô thấy ánh mắt nghi ngờ hiện lên rồi biến mất.",{bonus:sk17("Hầm canh xương",.09)}),
 K17("Học thợ gốm thật nhanh, nặn bát ngay trong ngày","tri",0.510,"Chiếc bát đầu tiên của cô méo, chiếc thứ ba thì tròn. Thợ gốm nể cô.","Cô nung nhầm lửa, bát nứt. Thợ gốm không cười, chỉ lặng lẽ chỉ cô cách khác.",{bonus:sk17("Hầm canh xương",.09)})],
{ctx:"Cổng thành và vương cung Hắc Thạch, ngày thứ ba. Hách Lôi gặp cô.",learn:{n:"Nung gốm",s:"tri",v:2}}),

Q17("t34","rfair","Hắc Thạch · Phố thợ rìa thành","chon","Gặp Tư Lăng",
"Một tháng sau, ở phố thợ rìa thành, cô biết trước Tư Lăng đang âm thầm gom người chống lại anh trai mình, Hách Lôi. Cô tìm đến, ngồi nói chuyện vài lần; ông không tin. Cô vẽ lại sơ đồ những người trung thành với ông và những người Hách Lôi đã mua chuộc, điều chưa ai biết; ông giật mình. Cô có thể nói điều ông tin nhất, hoặc điều ông sợ nhất.",
"Ông không cần ai khuyên. Ông cần ai đó biết chuyện ông chưa nói ra.",
"tk_ky,tk_lang,tk_loi,tc",[
 K17("Nói điều ông tin nhất: «Dân Hắc Thạch cần một vị vua biết lắng nghe»","mi",0.500,"Ông im lặng khá lâu, rồi hạ giọng: «Cô nói tiếp đi.» Ánh mắt ông đã dịu.","Lời cô nghe quá lý tưởng, ông cười nhạt: «Ai chẳng nói được thế.»",{f:"noi_dieu_tin",bonus:bn17(sk17("Viết văn tự bộ lạc",.09),fl17("nhan_long_tot",.05))}),
 K17("Nói điều ông sợ nhất: «Hách Lôi sẽ giết ông trước kỳ lễ tế»","tri",0.490,"Ông tái mặt, nắm chặt tay vịn. «Làm sao cô biết?», ông hỏi khẽ.","Ông giận dữ, tưởng cô dọa. Cô phải giải thích thêm mãi mới dịu.",{f:"noi_dieu_so",bonus:bn17(sk17("Viết văn tự bộ lạc",.09),fl17("nhan_long_tot",.05))}),
 K17("Đưa tờ sơ đồ trước, để ông tự đọc và tự hỏi","van",0.510,"Ông đọc xong, ngồi lặng. Rồi hỏi: «Cô muốn gì?». Cuộc nói chuyện bắt đầu thật sự.","Ông đọc nhanh quá, bỏ qua vài chi tiết. Cô phải giải thích lại từng nhánh.",{bonus:bn17(sk17("Viết văn tự bộ lạc",.09),fl17("nhan_long_tot",.05))})],
{ctx:"Phố thợ rìa thành Hắc Thạch, một tháng sau. Cô tìm Tư Lăng.",learn:{n:"Vẽ sơ đồ thế lực",s:"tri",v:2}}),

Q17("t35","vhall","Hắc Thạch · Sảnh lớn vương cung","hiem","Đêm lễ tế",
"Vài tháng sau, đêm lễ tế Thạch Vương. Cô nói với Tư Lăng ngày giờ lễ tế và nơi Hách Lôi chắc chắn lộ diện; theo đúng cốt truyện, ông ra tay. Bàng Thích rút kiếm kịp nhưng Hách Lôi gục trong sảnh; Tư Lăng lên ngôi, tuyên bố trước mọi người cô là «A Kỳ, trí giả đệ nhất của Hắc Thạch». Cô có thể khuyên ông tha những người chưa chống lại, hoặc trừng cả phe vua cũ.",
"Một vị vua mới sợ nhất là bị kẻ thù cũ báo thù. Nhưng khoan dung cũng cần người dám nói.",
"tk_ky,tk_lang,tk_loi,tk_thich,tc",[
 K17("Khuyên ông tha những người chưa chống lại, đứng ngoài sảnh","tri",0.500,"Tư Lăng gật đầu. Phần lớn phe vua cũ cúi đầu quy phục, sảnh yên dần.","Lời khuyên bị tiếng hò hét át. Một nhóm vẫn kháng cự, ông phải ra tay mạnh hơn.",{f:"khuyen_tha",bonus:bn17(sk17("Vẽ sơ đồ thế lực",.09),fl17("nhan_long_tot",.04))}),
 K17("Khuyên ông trừng cả phe vua cũ để dứt hậu họa","mi",0.470,"Tư Lăng ra lệnh dứt khoát, sảnh im phăng phắc. Cô thấy lòng nặng trĩu.","Ông nghe nhưng ngập ngừng. Cả sảnh nhìn nhau, bầu không khí đặc quánh.",{b:[0,3,0,-3],bonus:bn17(sk17("Vẽ sơ đồ thế lực",.09),fl17("nhan_long_tot",.04))}),
 K17("Đứng ngay trong sảnh, tận mắt quan sát từng người","van",0.490,"Cô nhìn ra từng gương mặt dao động. Khi ông phán xử, cô thì thầm tên đúng người.","Một mũi giáo lạc bay sát vai cô, cô loạng choạng ngã sau cột đá.",{b:[-1,1,0,-10],bonus:bn17(sk17("Vẽ sơ đồ thế lực",.09),fl17("nhan_long_tot",.04))})],
{ctx:"Sảnh lớn vương cung Hắc Thạch, vài tháng sau. Đêm lễ tế Thạch Vương."}),

Q17("t36","vpalace","Hắc Thạch · Tòa nhà riêng","chon","Trí giả của Hắc Thạch",
"Mười ngày sau, Tư Lăng tặng cô nhà riêng, người hầu, và xin cô giúp mở rộng lãnh thổ. Cô từ chối làm vua hay quý tộc, chỉ nhận danh trí giả và quyền ra vào tự do, để chờ một người; ông không hỏi người đó là ai. Dân Hắc Thạch bắt đầu gọi cô bằng giọng như gọi một vị thần. Cô có thể nói thẳng «tôi chờ Đại Tư Tế Bạch Triệt», hoặc giữ bí mật.",
"Nói tên anh ra, dù chỉ một người nghe, anh cũng sẽ nghe được sớm hơn.",
"tk_ky,tk_lang,tk_triet,tc",[
 K17("Nói thẳng: «Tôi chờ Đại Tư Tế Bạch Triệt của Hà Lâm»","mi",0.500,"Tư Lăng gật đầu thật chậm. Ông dặn thủ vệ ở cổng thành: nếu thấy người tên ấy, báo ngay.","Ông im lặng, rồi hỏi lại tên. Cô nhận ra mình nói hơi nhiều.",{f:"noi_ten_36",both:1}),
 K17("Giữ bí mật: «Một người từ rất xa»","van",0.510,"Ông không hỏi thêm, chỉ gật đầu tôn trọng. Cô được yên tĩnh.","Cô nói quá mơ hồ, ông nghi ngờ nhưng vẫn không hỏi.",{}),
 K17("Tập trung việc của trí giả: xin mở xưởng gốm và lớp dạy chữ","tri",0.490,"Tư Lăng đồng ý ngay. Xưởng gốm đầu tiên của Hắc Thạch bắt đầu nung mẻ đầu.","Ông chưa hiểu «lớp dạy chữ» là gì, cô phải giải thích mãi.",{bonus:sk17("Nung gốm",.09)})],
{ctx:"Tòa nhà riêng của trí giả, mười ngày sau. Tư Lăng ban nhà và danh trí giả."}),

Q17("t37","vgate","Hắc Thạch · Cổng thành","chon","Ô Nhã đến Hắc Thạch",
"Hai tháng sau, Ô Nhã cùng Hồ Mịch và Hồ Khuê rời Hà Lâm sau trận cãi với Mặc Hạo, đi theo lời cô dặn, tới tận cổng thành. Thủ vệ gọi «Ô Nhã đại nhân» vì nghe nói bạn của trí giả. Ô Nhã ôm cô khóc. Cô giúp Hồ Mịch và Hồ Khuê lập Đoàn Hồ Tộc, đoàn thương nhân đầu tiên của Hắc Thạch. Cô có thể giữ Ô Nhã ở cạnh mình, hoặc để hai người theo chồng đi buôn.",
"Nàng đã chọn cách rời Hà Lâm theo lời ngươi. Ngươi nợ nàng một chỗ đứng.",
"tk_ky,tk_onha,tk_mich,tk_khue,tc",[
 K17("Giữ Ô Nhã ở cạnh mình, cùng làm việc ở xưởng gốm","mi",0.500,"Hai người sống chung một mái, buổi tối ngồi nặn bát và trò chuyện như ngày nhỏ.","Ô Nhã không quen việc nặn gốm, tay chai sần. Cô ấy cười, nhưng hơi gượng.",{bonus:sk17("Nung gốm",.09)}),
 K17("Để Ô Nhã theo chồng đi buôn, lập Đoàn Hồ Tộc","tri",0.500,"Đoàn thương nhân đầu tiên xuất hành ngay tuần sau. Ô Nhã vẫy tay từ xe thú, mắt sáng rỡ.","Tuyến buôn đầu tiên gặp cướp, đoàn phải quay về giữa chừng. Ô Nhã bình tĩnh, nhưng cô lo.",{bonus:sk17("Nung gốm",.09)}),
 K17("Hỏi Ô Nhã muốn gì, để cô ấy tự chọn","van",0.500,"Ô Nhã suy nghĩ cả đêm rồi chọn đi buôn cùng chồng, nhưng hứa về mỗi mùa. Cô gật.","Ô Nhã lưỡng lự, sau cùng nói «để tớ nghĩ thêm». Cả ba cùng im lặng một lúc.",{bonus:sk17("Nung gốm",.09)})],
{ctx:"Cổng thành Hắc Thạch, hai tháng sau. Ô Nhã và hai bạn đời Hồ tộc tới tìm cô."}),

Q17("t38","vgate","Hắc Thạch · Cổng thành","nan","Bạch Triệt trở về",
"Nửa năm sau, Tiểu Châu chiếu lại: Bạch Triệt về Hà Lâm, nghe bộ lạc kể cô đã bị giao đi, nhìn Mặc Hạo và nói «các người bỏ cô ấy, vậy ta bỏ các người», rồi hóa tuyết lang chạy về phía Hắc Thạch. Ở cổng thành, thủ vệ gọi «Bạch Triệt đại nhân»; anh ôm cô, hôn lên má, hỏi «em có bị thương không». Cô có thể kể hết cho anh nghe, hoặc chỉ nói «em ổn».",
"Anh chưa nổi giận vì bất cứ điều gì trong đời. Đây là lần đầu. Nắm chặt tay anh.",
"tk_ky,tk_triet,tk_hao,tc",[
 K17("Kể hết cho anh nghe, từng chuyện từng người","tri",0.490,"Anh nghe xong, siết tay cô thật chặt nhưng không nói gì. Lát sau, anh thì thầm: «Cảm ơn em đã nói.»","Anh nghe đến đoạn Huyền Lâm đưa cô đi thì run lên, phải ôm cô một lúc mới bình tĩnh.",{f:"ke_het_38",bonus:bn17(fl17("noi_ten_36",.05),fl17("de_vong",.05))}),
 K17("Chỉ nói «em ổn», rồi kéo anh vào trong","mi",0.500,"Anh nhìn cô rất lâu. Cô thấy mắt anh dịu lại, tay anh nắm tay cô như nắm một cánh hoa.","Anh nhìn ra cô nói dối. Ánh mắt anh tối hẳn lại, nhưng anh không hỏi thêm.",{bonus:bn17(fl17("noi_ten_36",.05),fl17("de_vong",.05))}),
 K17("Đưa anh chiếc vòng cổ xương mà cô đã giữ lại","van",0.480,"Anh cầm vòng, lặng đi. «Em vẫn giữ nó», anh nói, giọng thấp.","Chiếc vòng tuột khỏi tay anh, rơi xuống đất. Anh nhặt lên, im lặng.",{bonus:bn17(fl17("noi_ten_36",.05),fl17("de_vong",.05))})],
{ctx:"Cổng thành Hắc Thạch, nửa năm sau. Bạch Triệt tìm tới.",forced:1,fix:w17spikeK("s38","de_vong")}),

/* ---- Chương 6: Bức tường (mốc 39–45) ---- */
Q17("t39","vpalace","Hắc Thạch · Hiên nhà trí giả","chon","Kế hoạch báo thù",
"Đêm, ở hiên nhà cô trong vương cung, Bạch Triệt hỏi cô muốn báo thù Hà Lâm thế nào. Cô nói không muốn giết ai: cô muốn Hắc Thạch chiếm mọi vùng đất, chỉ chừa lại một khu rừng lớn, để họ không còn chỗ đi và hằng năm vẫn lo thú triều. Anh gật đầu: «anh giúp em». Cô có thể trả thù tới cùng, hoặc dừng ở mức bắt họ nhận lỗi.",
"Báo thù tới cùng thì anh sẽ đi cùng ngươi tới cùng, kể cả khi ngươi muốn dừng lại.",
"tk_ky,tk_triet,tc",[
 K17("Trả thù tới cùng: để họ không còn chỗ nào để đi","mi",0.510,"Anh gật đầu chậm rãi. Ánh mắt anh tối đi một tầng, nhưng bàn tay vẫn nắm tay cô.","Anh nghe xong, nhìn đi chỗ khác. Hơi thở anh nặng hơn.",{f:"toi_cung",both:1,g:[-3,5,6,2],b:[-1,6,0,-3],bonus:sk17("Vẽ sơ đồ thế lực",.09)}),
 K17("Dừng ở mức bắt họ nhận lỗi, rồi để họ đi","tri",0.490,"Anh im lặng khá lâu, rồi nói: «Em tốt hơn anh.» Bàn tay anh thả lỏng.","Anh khẽ cau mày: «Họ bỏ em mà em tha dễ vậy sao?». Cô phải giải thích thêm.",{f:"dung_muc",both:1,bonus:sk17("Vẽ sơ đồ thế lực",.09)}),
 K17("Chưa quyết, để anh ngủ lại một đêm rồi nói tiếp","van",0.500,"Sáng hôm sau, cô đã nghĩ rõ. Anh pha trà, hai người nói chuyện bình tĩnh.","Cả đêm cô mất ngủ, sáng hôm sau mắt thâm quầng. Anh nhìn cô lo lắng.",{bonus:sk17("Vẽ sơ đồ thế lực",.09)})],
{ctx:"Hiên nhà trí giả trong vương cung, đêm. Bạch Triệt hỏi cô muốn trả thù Hà Lâm thế nào."}),

Q17("t40","rsnow","Màn Ngăn Lực · Sáu tháng đường","hiem","Màn Ngăn Lực",
"Sáu tháng đường, vách đá xa; cô đi cùng một trăm dũng sĩ Hắc Thạch. Bạch Triệt dẫn cô tới nơi đàn thú biến mất: một tấm màn trong suốt dựng giữa núi. Cô nhận ra đây là kết giới do người dựng. Trên đường họ vẽ bản đồ để khỏi lạc. Hai người cùng bước qua; Bạch Triệt thấy huyết mạch thức tỉnh, nóng ran cả người rồi khỏe hẳn lên. Một trăm dũng sĩ vào theo cũng thức tỉnh. Cô có thể cho cả đoàn vào cùng, hoặc chỉ hai người vào trước.",
"Đàn thú không biến mất. Chúng bị đuổi. Ai dựng bức màn này biết rõ thú nhân.",
"tk_ky,tk_triet,tc",[
 K17("Chỉ hai người vào trước, đoàn chờ phía ngoài","tri",0.510,"Hai người bước qua, cảm giác như đi qua mặt nước lạnh. Phía bên kia yên tĩnh lạ thường.","Màn chắn đẩy ngược cô một nhịp, tay cô tê dại. Anh kéo cô vào bằng cả hai tay.",{f:"hai_nguoi_vao",bonus:sk17("Vẽ sơ đồ thế lực",.06)}),
 K17("Cho cả đoàn vào cùng một lúc để tiết kiệm thời gian","van",0.480,"Cả đoàn bước qua, tất cả đều thức tỉnh. Tiếng reo vang khắp vách đá.","Cả đoàn ập vào cùng lúc, màn chấn động dữ dội, cô bị đẩy ngã trên nền đá.",{b:[-1,1,0,-8],bonus:sk17("Vẽ sơ đồ thế lực",.06)}),
 K17("Cử một dũng sĩ thử trước, cô và anh quan sát","mi",0.500,"Dũng sĩ bước qua, cả người đỏ ửng rồi mỉm cười. Cô gật đầu cho phần còn lại vào.","Dũng sĩ ngã gục ngay cạnh màn. Cô phải kéo anh ra, mất hơn nửa buổi cứu chữa.",{bonus:sk17("Vẽ sơ đồ thế lực",.06)})],
{ctx:"Vách đá phía xa, sau sáu tháng đường. Bạch Triệt dẫn cô tới Màn Ngăn Lực.",learn:{n:"Vẽ bản đồ đường đi",s:"tri",v:2}}),

Q17("t41","vstreet","Nhân giới · Thị trấn nhân loại","duyen","Học nghề ở nhân giới",
"Ba năm sau, trong một thị trấn nhân loại, hai người mặc áo vải, trà trộn vào dân thường, lấy quần áo của họ để sống. Bạch Triệt đã ghi đầy giấy những thứ cần mang về. Cô học thợ rèn nhân loại cách nung quặng và rèn sắt thô. Tiểu Châu tóm tắt ba năm: hai người ở trọ nhà thợ, ăn cùng thợ, đổi công việc lấy kiến thức. Cô có thể học rèn sắt cho thật vững, hoặc học thêm một nghề nữa.",
"Sắt là thứ Hắc Thạch cần nhất. Ba năm này đổi được một thế kỷ.",
"tk_ky,tk_triet,tc",[
 K17("Học rèn sắt cho thật vững, mỗi ngày bên lò","tri",0.510,"Cô học từng nhiệt độ, từng nhịp búa. Bàn tay chai sần, nhưng thanh sắt cuối cùng thẳng tắp.","Cô mất kiên nhẫn, rèn lệch mấy lần. Thợ cả thở dài, bắt làm lại từ đầu.",{bonus:sk17("Vẽ bản đồ đường đi",.06)}),
 K17("Học thêm một nghề nữa: dệt hoặc làm thuốc","van",0.500,"Cô học thêm nghề dệt trong hai tháng. Ngón tay mềm hơn, đầu óc rộng hơn.","Cô học dở cả hai nghề, thợ cả nhẹ nhàng nhắc: tham thì thâm.",{bonus:sk17("Vẽ bản đồ đường đi",.06)}),
 K17("Giúp Bạch Triệt sao chép và phân loại những gì anh đã ghi","mi",0.490,"Hai người ngồi sắp xếp cả đêm. Sáng ra, mọi thứ ngăn nắp, anh nhìn cô như nhìn một kho báu.","Cô viết nhầm hai mục. Anh phát hiện kịp, nhẹ nhàng sửa.",{bonus:sk17("Vẽ bản đồ đường đi",.06)})],
{ctx:"Thị trấn nhân loại, ba năm sau. A Kỳ và Bạch Triệt học nghề.",learn:{n:"Rèn sắt thô",s:"van",v:2}}),

Q17("t42","vbook","Nhân giới · Thư viện cũ","duyen","Đọc chữ và bí mật thú triều",
"Cô học đọc chữ nhân loại và cùng Bạch Triệt đọc sử cũ ở thư viện: nhân loại và thú nhân từng sống chung; thú nhân mạnh nhưng vụng mưu; một người bán thú nhân dựng Màn Ngăn Lực để đuổi thú nhân đi, mỗi năm cho thú nuôi uống thuốc để tạo thú triều. Giữa đống sách, anh tìm thấy một trang ghi chép tay của cha, dừng giữa chừng. Anh ngồi lặng hồi lâu. Cô có thể nói «chúng ta cùng mang tất cả về», hoặc «mình chỉ lấy điều cần».",
"Trang giấy dừng giữa chừng. Đừng ép anh đọc tiếp nếu anh chưa muốn.",
"tk_ky,tk_triet,tk_han,tc",[
 K17("Nói: «Chúng ta cùng mang tất cả về»","mi",0.500,"Anh nhìn cô, gật đầu. Hai người ôm sách từng chồng, đêm đó đóng kiện đến tận khuya.","Cô nói quá lạc quan, anh nhìn đống sách chất cao như núi rồi thở dài.",{bonus:bn17(sk17("Vẽ bản đồ đường đi",.06),sk17("Rèn sắt thô",.04))}),
 K17("Nói: «Mình chỉ lấy điều cần, phần còn lại để lại»","tri",0.500,"Anh gật đầu chậm. «Em đúng.» Hai người chọn lọc kỹ, mang đi những gì cốt lõi.","Hai người cãi nhẹ về cuốn nào cần, cuốn nào không, mất hơn nửa ngày.",{bonus:bn17(sk17("Vẽ bản đồ đường đi",.06),sk17("Rèn sắt thô",.04))}),
 K17("Ngồi xuống bên anh, đọc to trang ghi chép của cha anh","van",0.490,"Anh lắng nghe, tay siết nhẹ tay cô. Giọng cô đều đặn, anh thở chậm dần.","Cô đọc vấp một chữ lạ, anh khẽ sửa. Hai người cười rồi lại đọc tiếp.",{bonus:bn17(sk17("Vẽ bản đồ đường đi",.06),sk17("Rèn sắt thô",.04))})],
{ctx:"Thư viện cũ ở nhân giới. A Kỳ đọc chữ nhân loại và tìm ra bí mật thú triều.",learn:{n:"Đọc chữ nhân loại",s:"tri",v:2}}),

Q17("t43","vwall","Vọng Lâm Lâu · Cạnh tường thành","nan","Họ bước ra khỏi rừng",
"Mười sáu năm sau, trên Vọng Lâm Lâu, cạnh tường thành, Tiểu Châu tóm: Hắc Thạch thống nhất thú nhân giới nhờ sắt, gốm và chữ; thú triều thành bữa tiệc thịt của các dũng sĩ thức tỉnh; cô cho dựng Vọng Lâm Lâu để ngắm Đại Mê Lâm. Một sáng, người Hà Lâm bước ra khỏi rừng và dừng trước tường thành: Phương Lạc Nghi được cõng, Khắc Cang, Mặc Hạo, Thiết Nham, Ưng Dực, Huyền Lâm theo sau. Bạch Triệt nhìn họ, bàn tay siết lại. Cô có thể nắm tay anh nói «để em lo», hoặc để anh quyết.",
"Họ đã đến. Anh chờ ngày này lâu hơn ngươi tưởng. Đừng để tay anh siết thêm.",
"tk_ky,tk_triet,tk_nghi,tk_cang,tk_hao,tk_nham,tk_duc,tk_lam,tc",[
 K17("Nắm tay anh, nói: «Để em lo»","mi",0.500,"Anh nhìn cô, hơi thở chậm lại. Bàn tay anh dần mở ra trong tay cô.","Cô nói quá nhẹ, anh không nghe rõ. Bàn tay anh vẫn siết, đầu ngón trắng bệch.",{f:"de_em_lo",bonus:bn17(sk17("Rèn sắt thô",.05),sk17("Đọc chữ nhân loại",.05))}),
 K17("Để anh quyết, đứng sát cạnh anh, không nói gì","van",0.500,"Anh im lặng, rồi nói rất khẽ: «Anh muốn nghe em nghĩ gì.» Cô đáp, anh gật đầu.","Anh đứng bất động, không nói gì. Cô đứng cạnh, bàn tay lạnh toát.",{bonus:bn17(sk17("Rèn sắt thô",.05),sk17("Đọc chữ nhân loại",.05))}),
 K17("Nhìn thẳng xuống đoàn người, quan sát từng người một","tri",0.490,"Cô thấy dáng họ già đi, mệt mỏi, không còn như năm xưa. Cơn giận của cô dịu đi một chút.","Cô nhìn quá lâu, ánh mắt vô tình chạm ánh mắt Phương Lạc Nghi. Cô quay đi, tim đập nhanh.",{bonus:bn17(sk17("Rèn sắt thô",.05),sk17("Đọc chữ nhân loại",.05))})],
{ctx:"Vọng Lâm Lâu, mười sáu năm sau. Người Hà Lâm bước ra khỏi rừng.",forced:1,fix:w17spikeK("s43","dung_muc")}),

Q17("t44","vwall","Hắc Thạch · Cổng thành phía rừng","chon","Điều kiện ở cổng thành",
"Mấy ngày sau, theo lệnh cô, thủ vệ ở cổng thành phía rừng nói với từng người xin vào: muốn vào thì phải bỏ thân nhân sau lưng; mỗi người có hai lần trả lời. Từng thành viên Hà Lâm lần lượt bỏ bạn bè, rồi bỏ cả người thân; con cái của Phương Lạc Nghi vào thành, các dũng sĩ cũng từng người rời đi. Huyền Lâm cuối cùng lặng lẽ quay về hang. Phương Lạc Nghi đứng một mình dưới tường, đã không còn trẻ. Thiết Lan vào thành nhưng không còn nhìn ai. Cô có thể nhìn đến cùng, hoặc quay đi và nắm tay anh.",
"Ngươi đặt điều kiện này, nên ngươi phải nhìn. Nhưng nhìn xong thì đừng nhìn lại nữa.",
"tk_ky,tk_triet,tk_nghi,tk_cang,tk_hao,tk_nham,tk_duc,tk_lam,tk_lan,tc",[
 K17("Nhìn đến cùng, ghi nhớ từng người bước qua","tri",0.500,"Cô nhìn từng gương mặt, không giận cũng không thương. Lòng cô bình thản kỳ lạ.","Cô nhìn mãi, thấy mắt cay xè. Cô không biết mình đang khóc vì ai.",{f:"nhin_den_cung",bonus:bn17(sk17("Rèn sắt thô",.04),sk17("Đọc chữ nhân loại",.04))}),
 K17("Quay đi, nắm tay anh, nói «ta vào trong thôi»","mi",0.500,"Anh nắm tay cô thật nhẹ, hai người rời Vọng Lâm Lâu, bỏ lại tiếng bước chân sau lưng.","Anh không đi ngay mà quay lại nhìn họ một lúc. Cô phải kéo tay anh mới chịu đi.",{f:"quay_di",bonus:bn17(sk17("Rèn sắt thô",.04),sk17("Đọc chữ nhân loại",.04))}),
 K17("Ra lệnh cho thủ vệ cho Ô Nhã gặp từng người trước khi họ vào","van",0.490,"Ô Nhã đứng giữa cổng, nói với từng người những lời cô không nói được. Mọi thứ bớt nặng nề.","Ô Nhã run giọng, khóc trước khi nói được hết câu. Buổi gặp kết thúc dở dang.",{bonus:bn17(sk17("Rèn sắt thô",.04),sk17("Đọc chữ nhân loại",.04))})],
{ctx:"Cổng thành phía rừng Hắc Thạch, mấy ngày sau. Người Hà Lâm lần lượt xin vào thành."}),

Q17("t45","vdawn","Vọng Lâm Lâu · Căn phòng trên cao","nan","Lời kết",
"Một sáng, trong căn phòng trên Vọng Lâm Lâu, trời vừa lên. Cô đã già; Tiểu Châu báo nhiệm vụ ở thế giới này đã xong. Bạch Triệt nắm tay cô, hỏi «em đi đâu, anh đi cùng được không?». Cô nói không biết nên không mang được. Anh xin ở bên cô tới phút cuối, và cô đồng ý, hẹn «kiếp sau gặp». Ngoài cửa sổ, Đại Mê Lâm xanh một màu, tường thành sáng lên dưới nắng. Anh nắm tay cô, và tay anh run.",
"Anh sẽ siết hay buông, còn tùy chuyện anh học được suốt những năm qua.",
"tk_ky,tk_triet,tc",[
 K17("Nói thật: «Em sẽ đi, nhưng em đã sống trọn ở đây»","mi",0.490,"Anh gật rất chậm, rồi nở nụ cười đã quá quen thuộc. «Vậy là đủ.»","Anh gật mà nước mắt rơi trước. Cô đưa tay lau cho anh.",{f:"noi_that_45",bonus:bn17(sk17("Đọc chữ nhân loại",.06),sk17("Viết văn tự bộ lạc",.04))}),
 K17("Nắm tay anh, nhắc lại những ngày đầu ở cửa hang","tri",0.480,"Hai bàn tay không rời nhau. Anh lẩm bẩm theo từng chữ, mắt dịu dần.","Anh nghe tới câu thứ hai thì ôm chặt cô, không cho nói tiếp.",{f:"nhac_ngay_dau",bonus:bn17(sk17("Đọc chữ nhân loại",.06),sk17("Viết văn tự bộ lạc",.04))}),
 K17("Pha trà thuốc như mọi sáng, ngồi cạnh anh nhìn rừng","van",0.500,"Hai người uống trà trong yên lặng. Anh tựa vào vai cô, nhẹ như hơi thở.","Ấm trà nguội trước khi cô rót xong. Anh bật cười, nắm lấy tay cô thay cho tách trà.",{bonus:bn17(sk17("Đọc chữ nhân loại",.06),sk17("Viết văn tự bộ lạc",.04))})],
{ctx:"Căn phòng trên Vọng Lâm Lâu, một sáng. Tiểu Châu báo nhiệm vụ ở thế giới này đã xong."})
];

var IX17={};EV17.forEach(function(e,i){e.no=i+1;IX17[e.id]=i});
dyn17(EV17[IX17.t17],(function(base){return function(){var s=base;
 s+=S.f.onha_di?" Ô Nhã đã đi tìm dũng sĩ và trở về cùng hai bạn đời Hồ tộc, Hồ Mịch và Hồ Khuê, gầy nhưng khỏe và nhanh trí. Bộ lạc chê họ «xấu», cô chỉ nhớ họ đánh giỏi.":(S.f.onha_o?" Ô Nhã vẫn ở lại bộ lạc, ngày ngày nhìn về hang Khắc Cang, buồn không nói thành lời.":"");
 return s}})(EV17[IX17.t17].text));
function w17spread(k){EV17.forEach(function(e){var r=e.ch.filter(function(c){return c.s&&typeof c.b==="number"||c.b0!==undefined});if(r.length<2)return;r.forEach(function(c){if(c.b0===undefined)c.b0=c.b});var m=r.reduce(function(a,c){return a+c.b0},0)/r.length;r.forEach(function(c){c.b=Math.max(.2,Math.min(.8,m+k*(c.b0-m)))})})}

var ENDS17={
 true:{n:"Hai bàn tay, một tòa lầu",c:"Tiểu Châu đọc kết quả: đạt, trọn vẹn. Ác niệm của Bạch Triệt về không. Anh không còn sợ bị bỏ lại, cũng thôi nắm tay cô như nắm một sợi chỉ sắp đứt. Hai người sống đến tuổi già trên Vọng Lâm Lâu, nhìn Đại Mê Lâm xanh dưới nắng, nhìn Hắc Thạch mở cổng đón những người đến từ nhân giới. Đến ngày cô phải đi, anh nắm tay cô nhẹ như nắm một cánh hoa. Họ ra đi bình yên, cùng một ngày.",gain:120,piece:1,heat:.1,scene:"vdawn"},
 near:{n:"Anh siết tay cô hơi chặt",c:"Tiểu Châu đọc kết quả: đạt, nhưng chưa trọn. Hai người vẫn bên nhau đến cuối. Hắc Thạch thống nhất thú nhân giới, sắt và gốm và chữ lan khắp Đại Mê Lâm. Chỉ có điều những lần cô sắp đi xa, tay anh vẫn siết hơi chặt, như sợ gió cuốn đi. Cô không giận. Cô biết anh đang học cách tin rằng lần này không ai bị bỏ lại, và vết lo trong mắt anh nhạt dần theo từng mùa.",gain:90,piece:1,heat:.35,scene:"vwall"},
 half:{n:"Một mình trên lầu cao",c:"Tiểu Châu đọc kết quả: chưa đạt. Cô đã làm gần hết nhiệm vụ: Hắc Thạch ổn, thú triều không còn là nỗi sợ, Hà Lâm đã bước ra khỏi rừng. Nhưng vết sợ mất trong anh vẫn chưa lành. Đến ngày cô rời đi, anh ở lại một mình trên Vọng Lâm Lâu, vẫn đặt hai cái chén mỗi sáng. Có những vết, tình thương không đủ để lấp, và cả hai đều biết điều đó.",gain:60,piece:0,heat:.6,scene:"rtop"},
 black:{n:"Tiếng gầm trên Đại Mê Lâm",c:"Hắc hóa chạm 100. Nỗi sợ bị bỏ lại và mối hận với bộ lạc đã giao cô đi nuốt trọn Bạch Triệt. Anh hóa tuyết lang mà không còn nghe tên mình, chạy thẳng về phía Hà Lâm. Tiếng gầm vang khắp Đại Mê Lâm, chim bay tán loạn. Tiểu Châu khẽ gọi cô đi trước khi sơn bụng lặng hẳn.",gain:0,piece:0,heat:1,scene:"vfire"},
 bdead:{n:"Chiếc áo lông còn ấm",c:"Sinh mệnh của Bạch Triệt về 0. Anh kiệt sức vì chạy theo thú triều, vì những đêm không ngủ nghĩ về chuyện cô sẽ đi. Chiếc áo lông cô khâu dở vẫn nằm trên ghế đá, hơi ấm chưa kịp tan. Tiểu Châu khẽ gọi cô về.",gain:0,piece:0,heat:.9,scene:"vdawn"},
 dead:{n:"Ngọn lửa chưa kịp truyền",c:"Sinh mệnh của cô cạn kiệt. Một bước chân sai ở bìa rừng, hay một lần ngã đưa cô đi nhanh hơn dự tính, và đêm ấy không ai kịp chạy tới. Tiểu Châu kéo linh hồn cô đi trước khi Bạch Triệt chạm tay vào cánh cửa thạch ốc.",gain:0,piece:0,heat:.8,scene:"rforest"}
};

function w17emblem(heat){
  /* Dấu chân sói trong vòng tròn, viền ngoài ngả đỏ theo Hắc hóa */
  return '<svg class="eye" viewBox="0 0 96 96" role="img" aria-label="Dấu chân sói trong vầng sáng, viền ngoài ngả đỏ dần theo Hắc hóa"><circle cx="48" cy="48" r="45" fill="var(--surface)" stroke="var(--line)" stroke-width="1.5"/><circle cx="48" cy="48" r="45" fill="none" stroke="var(--ember)" stroke-width="2" stroke-dasharray="'+(heat*283)+' 283" transform="rotate(-90 48 48)"/>'
   +'<ellipse cx="48" cy="60" rx="15" ry="12" fill="color-mix(in oklab,var(--ember) '+Math.round(heat*100)+'%,#dfe4ea)" stroke="var(--fg)" stroke-width="2.2"/>'
   +'<ellipse cx="30" cy="40" rx="6" ry="8" fill="#dfe4ea" stroke="var(--fg)" stroke-width="2.2" transform="rotate(-20 30 40)"/><ellipse cx="42" cy="30" rx="6" ry="8.5" fill="#dfe4ea" stroke="var(--fg)" stroke-width="2.2" transform="rotate(-6 42 30)"/><ellipse cx="55" cy="30" rx="6" ry="8.5" fill="#dfe4ea" stroke="var(--fg)" stroke-width="2.2" transform="rotate(6 55 30)"/><ellipse cx="67" cy="40" rx="6" ry="8" fill="#dfe4ea" stroke="var(--fg)" stroke-width="2.2" transform="rotate(20 67 40)"/></svg>';
}

